import socket
import threading
import time
import signal
import sys
import os

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except Exception:
    DigitalOutputDevice = None
    PWMOutputDevice = None
    GPIOZeroError = Exception

try:
    import spidev
except Exception:
    spidev = None

# --- Configuration ---
MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23

MOISTURE_SENSOR_1_CHANNEL = 0
MOISTURE_SENSOR_2_CHANNEL = 1

SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7

SERVER_HOST = '0.0.0.0'
SERVER_PORT = 12345

SENSOR_READING_WINDOW = 5
SENSOR_READING_DELAY = 0.02
SENSOR_READING_TIMEOUT = 5

WATERING_DURATION = 5
THRESHOLD = 30

# --- Globals ---
running = True
motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counter_clockwise = None
motor_a_enable = None
motor_b_enable = None
spi = None
sensor1 = None
sensor2 = None

server_socket = None
sensor_data_lock = threading.Lock()
sensor_data = {'sensor1': {'moisture': 0.0, 'timestamp': None}, 'sensor2': {'moisture': 0.0, 'timestamp': None}}
last_sensor_readings = {'sensor1': {'avg': 0.0, 'count': 0}, 'sensor2': {'avg': 0.0, 'count': 0}}

shutdown_event = threading.Event()

# --- Hardware Initialization ---
def init_gpio():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counter_clockwise, motor_a_enable, motor_b_enable, spi, sensor1, sensor2
    try:
        motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
        motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
        motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
        motor_b_counter_clockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
        motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=1000)
        motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=1000)
        motor_a_enable.value = 0
        motor_b_enable.value = 0
    except Exception as e:
        print(f"GPIO init error: {e}")
        motor_a_forward = motor_a_backward = motor_b_clockwise = motor_b_counter_clockwise = motor_a_enable = motor_b_enable = None
        return False
    try:
        if spidev is not None:
            spi = spidev.SpiDev()
            spi.open(0, 0)
            spi.max_speed_hz = 1000000
            spi.mode = 0
        else:
            print("spidev not available; using simulated SPI.")
            spi = None
    except Exception as e:
        print(f"SPI init error: {e}")
        spi = None
    try:
        sensor1 = MCP3008(spi, SPI_CLK_PIN, SPI_MOSI_PIN, SPI_MISO_PIN, SPI_CS_1_PIN, MOISTURE_SENSOR_1_CHANNEL)
        sensor2 = MCP3008(spi, SPI_CLK_PIN, SPI_MOSI_PIN, SPI_MISO_PIN, SPI_CS_2_PIN, MOISTURE_SENSOR_2_CHANNEL)
    except Exception as e:
        print(f"Sensor init error: {e}")
        sensor1 = sensor2 = None
    return True

class MCP3008:
    def __init__(self, spi, clk, mosi, miso, cs, channel):
        self.spi = spi
        self.clk = clk
        self.mosi = mosi
        self.miso = miso
        self.cs = cs
        self.channel = channel
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1000000
        self.spi.mode = 0
        self.cs.off()

    def read(self):
        try:
            self.cs.on()
            time.sleep(0.0001)
            self.cs.off()
            time.sleep(0.0001)
            self.spi.xfer2([1, (8 + self.channel) << 4, 0])
            adc = self.spi.readbytes(2)
            data = ((adc[1] & 3) << 8) + adc[0]
            return data
        except Exception as e:
            print(f"SPI read error: {e}")
            return -1

def read_moisture(sensor):
    if sensor is None:
        return -1
    readings = []
    for _ in range(SENSOR_READING_WINDOW):
        try:
            val = sensor.read()
            if val >= 0:
                readings.append(val)
            else:
                return -1
        except Exception as e:
            print(f"Sensor read error: {e}")
            return -1
        time.sleep(SENSOR_READING_DELAY)
    if not readings:
        return -1
    return sum(readings) / len(readings)

def apply_watering(motor_a, motor_b, duration):
    if motor_a is None or motor_b is None:
        return
    try:
        motor_a_forward.on()
        motor_a_backward.off()
        motor_b_clockwise.on()
        motor_b_counter_clockwise.off()
        motor_a_enable.value = 0.5
        motor_b_enable.value = 0.5
        time.sleep(duration)
    except Exception as e:
        print(f"Watering error: {e}")
    finally:
        motor_a_forward.off()
        motor_a_backward.off()
        motor_b_clockwise.off()
        motor_b_counter_clockwise.off()
        motor_a_enable.value = 0
        motor_b_enable.value = 0

def get_sensor_data():
    global sensor_data, last_sensor_readings
    s1 = read_moisture(sensor1)
    s2 = read_moisture(sensor2)
    if s1 >= 0:
        with sensor_data_lock:
            sensor_data['sensor1']['moisture'] = s1
            sensor_data['sensor1']['timestamp'] = time.time()
        last_sensor_readings['sensor1']['avg'] += s1
        last_sensor_readings['sensor1']['count'] += 1
    if s2 >= 0:
        with sensor_data_lock:
            sensor_data['sensor2']['moisture'] = s2
            sensor_data['sensor2']['timestamp'] = time.time()
        last_sensor_readings['sensor2']['avg'] += s2
        last_sensor_readings['sensor2']['count'] += 1
    return {'sensor1': sensor_data['sensor1'], 'sensor2': sensor_data['sensor2']}

def set_threshold(value):
    global THRESHOLD
    try:
        THRESHOLD = int(value)
    except ValueError:
        print("Invalid threshold value. Must be an integer.")

def set_watering_duration(value):
    global WATERING_DURATION
    try:
        WATERING_DURATION = int(value)
    except ValueError:
        print("Invalid watering duration. Must be an integer.")

def handle_client(conn, addr):
    global running
    try:
        with conn:
            print(f"Connected by {addr}")
            while running:
                data = conn.recv(1024).decode()
                if not data:
                    break
                print(f"Received: {data}")
                parts = data.split()
                if not parts:
                    continue
                cmd = parts[0]
                if cmd == 'WATER_PLANT_1':
                    apply_watering(motor_a_forward, motor_b_clockwise, WATERING_DURATION)
                elif cmd == 'WATER_PLANT_2':
                    apply_watering(motor_a_backward, motor_b_counter_clockwise, WATERING_DURATION)
                elif cmd == 'GET_SENSOR_DATA':
                    data = get_sensor_data()
                    conn.sendall((f"{data['sensor1']['moisture']},{data['sensor2']['moisture']}\n").encode())
                elif cmd.startswith('SET_THRESHOLD'):
                    try:
                        val = int(cmd.split()[1])
                        set_threshold(val)
                    except (ValueError, IndexError):
                        conn.sendall(b"Invalid argument. Use 'SET_THRESHOLD <integer>'\n")
                elif cmd.startswith('SET_WATERING_DURATION'):
                    try:
                        val = int(cmd.split()[1])
                        set_watering_duration(val)
                    except (ValueError, IndexError):
                        conn.sendall(b"Invalid argument. Use 'SET_WATERING_DURATION <integer>'\n")
                else:
                    conn.sendall(b"Invalid command. Use: WATER_PLANT_1, WATER_PLANT_2, GET_SENSOR_DATA, SET_THRESHOLD <value>, SET_WATERING_DURATION <value>\n")
    except Exception as e:
        print(f"Client error: {e}")

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False
    shutdown_event.set()

def cleanup():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counter_clockwise, motor_a_enable, motor_b_enable, spi, server_socket
    print("Cleaning up resources...")
    try:
        if motor_a_forward is not None:
            motor_a_forward.close()
        if motor_a_backward is not None:
            motor_a_backward.close()
        if motor_b_clockwise is not None:
            motor_b_clockwise.close()
        if motor_b_counter_clockwise is not None:
            motor_b_counter_clockwise.close()
        if motor_a_enable is not None:
            motor_a_enable.close()
        if motor_b_enable is not None:
            motor_b_enable.close()
    except Exception as e:
        print(f"GPIO cleanup error: {e}")
    try:
        if spi is not None:
            spi.close()
    except Exception as e:
        print(f"SPI cleanup error: {e}")
    try:
        if server_socket is not None:
            server_socket.close()
    except Exception as e:
        print(f"Socket cleanup error: {e}")

def main():
    global running, server_socket
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not init_gpio():
        print("GPIO init failed. Running in simulation mode.")
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((SERVER_HOST, SERVER_PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        print(f"Server listening on {SERVER_HOST}:{SERVER_PORT}")
    except Exception as e:
        print(f"Server socket error: {e}")
        cleanup()
        sys.exit(1)
    while running:
        try:
            conn, addr = server_socket.accept()
            t = threading.Thread(target=handle_client, args=(conn, addr), daemon=True)
            t.start()
        except socket.timeout:
            continue
        except Exception as e:
            if running:
                print(f"Accept error: {e}")
        time.sleep(0.1)
        if shutdown_event.is_set():
            break
        if running:
            print("Health check...")
            time.sleep(60)
    cleanup()

if __name__ == "__main__":
    main()

