#!/usr/bin/python3

import time
import logging
import signal
import sys
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADS1x15:
    REG_POINTER_CONVERT = 0x00
    REG_POINTER_CONFIG = 0x01
    REG_POINTER_LOWTHRESH = 0x02
    REG_POINTER_HITHRESH = 0x03
    REG_POINTER_MODE = 0x04
    REG_POINTER_DR = 0x05
    REG_POINTER_PGA = 0x06
    REG_POINTER_CQUE = 0x07
    REG_POINTER_CQUE_SRC = 0x08
    REG_POINTER_CQUE_MODE = 0x09
    REG_POINTER_CQUE_CLOCK = 0x0A
    REG_POINTER_CQUE_POL = 0x0B
    REG_POINTER_CQUE_LAT = 0x0C
    REG_POINTER_CQUE_QUE = 0x0D
    REG_POINTER_CQUE_QUE_MASK = 0x0E
    REG_POINTER_CQUE_QUE_SHIFT = 0x0F

    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.debug = debug
        self._bus = None
        self._running = True
        try:
            self._bus = smbus2.SMBus(busnum)
        except FileNotFoundError:
            logging.error(f"I2C bus {busnum} not found. Enable I2C and check /dev/i2c-{busnum}.")
            raise
        except PermissionError:
            logging.error(f"Permission denied on /dev/i2c-{busnum}. Add user to the 'i2c' group or run with appropriate privileges.")
            raise
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {busnum}: {e}")
            raise

        if not self._probe():
            logging.error(f"No device found at I2C address 0x{address:02X}. Check wiring and address.")
            self.close()
            raise IOError(f"No device found at I2C address 0x{address:02X}")

        self._configure(0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000, 0x8000)

    def _probe(self):
        try:
            return self._read_register(self.REG_POINTER_CONFIG)[0] != 0
        except IOError:
            return False

    def _write_register(self, reg, value):
        try:
            self._bus.write_word_data(self.address, reg, value)
        except IOError as e:
            logging.error(f"I2C write error to register 0x{reg:02X}: {e}")
            raise

    def _read_register(self, reg):
        try:
            return self._bus.read_word_data(self.address, reg)
        except IOError as e:
            logging.error(f"I2C read error from register 0x{reg:02X}: {e}")
            raise

    def _read_block(self, reg, length):
        try:
            return self._bus.read_i2c_block_data(self.address, reg, length)
        except IOError as e:
            logging.error(f"I2C block read error from register 0x{reg:02X}: {e}")
            raise

    def _configure(self, mode, sps, pga, latching, active_low, threshold_high, threshold_low, cque_src, cque_mode, cque_clock, cque_pol, cque_lat, cque_QUE, cque_QUE_MASK, cque_QUE_SHIFT):
        self._write_register(self.REG_POINTER_MODE, mode)
        self._write_register(self.REG_POINTER_DR, sps)
