import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio
from math import atan2, degrees

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
ADC_CHANNEL = 0
ADC_GAIN = 1
PWM_FREQUENCY = 500
ADC_I2C_ADDRESS = 0x48

# Global state
running = True
pi = None

class MotorController:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("pigpio daemon not running")
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self._init_gpio()

    def _init_gpio(self):
        self.pi.set_mode(self.dir_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.step_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.ms0_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.ms1_pin, pigpio.OUTPUT)
        self._set_resolution(pigpio.MS_FULL)
        self._set_direction(pigpio.CCW)
        self.pi.set_PWM_frequency(self.step_pin, PWM_FREQUENCY)
        self.pi.set_PWM_range(self.step_pin, 255)
        self.pi.set_PWM_dutycycle(self.step_pin, 0)

    def _set_resolution(self, resolution):
        self.pi.write(self.ms0_pin, 0)
        self.pi.write(self.ms1_pin, 0)
        if resolution == pigpio.MS_HALF:
            self.pi.write(self.ms0_pin, 1)
        elif resolution == pigpio.MS_1/4:
            self.pi.write(self.ms0_pin, 1)
            self.pi.write(self.ms1_pin, 1)
        elif resolution == pigpio.MS_1/8:
            self.pi.write(self.ms1_pin, 1)
        elif resolution == pigpio.MS_FULL:
            pass
        else:
            raise ValueError(f"Invalid resolution: {resolution}")

    def _set_direction(self, direction):
        self.pi.write(self.dir_pin, 1 if direction == pigpio.CW else 0)

    def set_duty_cycle(self, duty_cycle):
        duty_cycle = max(0, min(255, duty_cycle))
        self.pi.set_PWM_dutycycle(self.step_pin, duty_cycle)

    def stop(self):
        self.pi.set_PWM_dutycycle(self.step_pin, 0)

    def cleanup(self):
        self.stop()
        self.pi.stop()

class SensorManager:
    def __init__(self, i2c):
        self.i2c = i2c
        self.accel = None
        self.mag = None
        self._init_sensors()

    def _init_sensors(self):
        try:
            self.accel = adafruit_lsm303_accel.LSM303_Accel(self.i2c)
        except Exception as e:
            print(f"Error initializing accelerometer: {e}")
            self.accel = None
        try:
            self.mag = adafruit_lsm303dlh_mag.LSM303DLH_Mag(self.i2c)
        except Exception as e:
            print(f"Error initializing magnetometer: {e}")
            self.mag = None

    def get_acceleration(self):
        if self.accel is None:
            return None, None, None
        try:
            return self.accel.acceleration
        except Exception as e:
            print(f"Error reading acceleration: {e}")
            return None, None, None

    def get_magnetic_field(self):
        if self.mag is None:
            return None, None, None
        try:
            return self.mag.magnetic
        except Exception as e:
            print(f"Error reading magnetic field: {e}")
            return None, None, None

    def get_heading(self):
        if self.mag is None:
            return None
        try:
            x, y, _ = self.get_magnetic_field()
            if x is None or y is None:
                return None
            return degrees(atan2(y, x))
        except Exception as e:
            print(f"Error calculating heading: {e}")
            return None

    def get_inclination(self):
        try:
            x, y, z = self.get_acceleration()
            if x is None or y is None or z is None:
                return None, None
            xz = degrees(atan2(x, z))
            yz = degrees(atan2(y, z))
            return xz, yz
        except Exception as e:
            print(f"Error calculating inclination: {e}")
            return None, None

    def cleanup(self):
        pass

class ADCManager:
    def __init__(self, i2c, address, channel, gain):
        self.i2c = i2c
        self.address = address
        self.channel = channel
        self.gain = gain
        self.adc = None
        self._init_adc()

    def _init_adc(self):
        try:
            self.adc = Adafruit_ADS1x15.ADS1015(address=self.address)
            self.adc.gain = gain
        except Exception as e:
            print(f"Error initializing ADC: {e}")
            self.adc = None

    def read_voltage(self, channel):
        if self.adc is None:
            return None
        try:
            return self.adc.read_adc(channel, gain=self.gain)
        except Exception as e:
            print(f"Error reading ADC channel {channel}: {e}")
            return None

    def cleanup(self):
        self.stop_pwm()

    def stop_pwm(self):
        pass

def main():
    global running, pi
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

    motor = MotorController(MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN)
    sensor = SensorManager(i2c)
    adc = ADCManager(i2c, ADC_I2C_ADDRESS, ADC_CHANNEL, ADC_GAIN)

    pi = motor.pi

    def signal_handler(sig, frame):
        nonlocal running
        running = False

    try:
        while running:
            voltage = adc.read_voltage(ADC_CHANNEL)
            if voltage is not None:
                duty_cycle = int((voltage / 3.3) * 255)
                motor.set_duty_cycle(duty_cycle)

            accel_x, accel_y, accel_z = sensor.get_acceleration()
            mag_x, mag_y, mag_z = sensor.get_magnetic_field()
            heading = sensor.get_heading()
            inclination_xz, inclination_yz = sensor.get_inclination()

            print(f"Voltage: {voltage:.2f}V, Duty Cycle: {duty_cycle}")
            print(f"Acceleration: ({accel_x}, {accel_y}, {accel_z})")
            print(f"Magnetic Field: ({mag_x}, {mag_y}, {mag_z})")
            print(f"Heading: {heading:.2f} degrees")
            print(f"Inclination: XZ={inclination_xz:.2f}, YZ={inclination_yz:.2f}")
            print("-" * 40)

            time.sleep(1)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        motor.stop()
        motor.cleanup()
        sensor.cleanup()
        if pi is not None and pi.connected:
            pi.stop()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

