import spidev
import RPi.GPIO as GPIO
import time
import logging
import argparse
import queue
import threading
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = True
        self.last_event_time = 0.0
        self.event_queue = queue.Queue()
        self.event_lock = threading.Lock()
        self.spi = None
        self.gpio_initialized = False

        if self.sensor_type == 'digital':
            if not self.gpio_pins:
                logging.error(f"Digital sensor {self.sensor_id}: no GPIO pins specified")
                return
            try:
                for pin in self.gpio_pins:
                    GPIO.setmode(GPIO.BCM)
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                self.gpio_initialized = True
                logging.info(f"Digital sensor {self.sensor_id}: GPIO pins {self.gpio_pins} initialized")
            except Exception as e:
                logging.error(f"Digital sensor {self.sensor_id}: GPIO setup failed: {e}")
                return
        elif self.sensor_type == 'analog':
            if not self.channels:
                logging.error(f"Analog sensor {self.sensor_id}: no ADC channels specified")
                return
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                logging.info(f"Analog sensor {self.sensor_id}: SPI opened on bus 0, device 0 at {self.spi_speed} Hz")
            except Exception as e:
                logging.error(f"Analog sensor {self.sensor_id}: SPI initialization failed: {e}")
                return
        else:
            logging.error(f"Unknown sensor type: {self.sensor_type}")
            return

    def read_sound_level(self):
        if self.sensor_type == 'digital':
            try:
                return GPIO.input(self.gpio_pins[0])
            except Exception as e:
                logging.error(f"Digital sensor {self.sensor_id}: read error: {e}")
                return None
        elif self.sensor_type == 'analog':
            try:
                adc = self.spi.xfer2([1, (8 + self.channels[0]) << 4, 0])
                data = ((adc[1] & 3) << 8) + adc[2]
                return data
            except Exception as e:
                logging.error(f"Analog sensor {self.sensor_id}: read error: {e}")
                return None
        return None

    def detect_sound_event(self):
        sound_level = self.read_sound_level()
        if sound_level is None:
            return False
        if self.sensor_type == 'digital' and sound_level == 1:
            return True
        if self.sensor_type == 'analog' and sound_level >= self.threshold:
            return True
        return False

    def debounce(self):
        if self.sensor_type == 'digital':
            return
        if self.sensor_type == 'analog':
            time.sleep(0.1)

    def run(self):
        logging.info(f"Sound sensor {self.sensor_id} started")
        while self.running:
            try:
                if self.detect_sound_event():
                    self.last_event_time = time.time()
                    self.event_queue.put(self.sensor_id)
                    self.log_queue.put(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Sound detected by {self.sensor_id}")
                    self.debounce()
                time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Sound sensor {self.sensor_id}: error in run loop: {e}")
                time.sleep(1)
        logging.info(f"Sound sensor {self.sensor_id} stopped")

    def stop(self):
        self.running = False
        if self.gpio_initialized:
            try:
                GPIO.cleanup(self.gpio_pins)
            except Exception as e:
                logging.error(f"Digital sensor {self.sensor_id}: GPIO cleanup error: {e}")
        if self.spi:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Analog sensor {self.sensor_id}: SPI close error: {e}")
        logging.info(f"Sound sensor {self.sensor_id} stopped and resources released")

def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring system for Raspberry Pi")
    parser.add_argument("--sensor_type", type=str, required=True, choices=['digital', 'analog'], help="Sensor type")
    parser.add_argument("--threshold", type=int, default=500, help="Analog threshold (for analog sensors)")
    parser.add_argument("--sample_rate", type=int, default=100, help="Sampling rate in Hz")
    parser.add_argument("--log_file", type=str, default="sound_sensor.log", help="Log file path")
    parser.add_argument("--gpio_pins", type=str, default="[17, 18]", help="Comma-separated list of GPIO pins for digital sensors")
    parser.add_argument("--channels", type=str, default="[0]", help="Comma-separated list of MCP3008 channel numbers for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", type=str, default="sensor1,sensor2", help="Comma-separated list of sensor IDs")
    args = parser.parse_args()

    log_queue = queue.Queue()
    threads = []
    for sid in args.sensor_ids.split(','):
        sid = sid.strip()
        if sid:
            try:
                int(sid)
            except ValueError:
                logging.error(f"Invalid sensor ID: {sid}")
                continue
            sensor = SoundSensor(sid, args.sensor_type, args.threshold, args.sample_rate, [int(p) for p in args.gpio_pins.split(',')], [int(c) for c in args.channels.split(',')], args.spi_speed, log_queue)
            t = threading.Thread(target=sensor.run, daemon=True)
            threads.append(t)
            t.start()
    for t in threads:
        t.join()

if __name__ == "__main__":
    main()

