import smbus2
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADS1x15:
    _REG_POINTER_CONVERT = 0x00
    _REG_POINTER_CONFIG = 0x01

    def __init__(self, address=0x48, busnum=1, sps=8, pga=6144):
        self.address = address
        self.sps = sps
        self.pga = pga
        self._bus = None
        self._closed = False
        try:
            self._bus = smbus2.SMBus(busnum)
            self._configure()
        except Exception as e:
            logging.error(f"Failed to initialize ADS1x15 on bus {busnum}: {e}")
            self._bus = None
            raise

    def _configure(self):
        config = self._build_config()
        try:
            self._bus.write_i2c_block_data(self.address, self._REG_POINTER_CONFIG, [(config >> 8) & 0xFF, config & 0xFF])
        except Exception as e:
            logging.error(f"Failed to write configuration to ADS1x15: {e}")
            raise

    def _build_config(self):
        config = (self._REG_POINTER_CONFIG << 16) | (self.sps << 12) | (self.pga << 4) | 0x03
        return config

    def read(self, channel):
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")
        if self._bus is None:
            raise RuntimeError("I2C bus is not initialized")
        try:
            self._configure()
            time.sleep(0.01)
            data = self._read_conversion(channel)
            return self._convert_to_voltage(data, self.pga)
        except Exception as e:
            logging.error(f"Error reading ADS1x15 channel {channel}: {e}")
            raise

    def _read_conversion(self, channel):
        reg = self._REG_POINTER_CONVERT | ((channel & 0x07) << 4)
        try:
            return self._bus.read_i2c_block_data(self.address, reg, 2)
        except Exception as e:
            logging.error(f"Error reading conversion register for channel {channel}: {e}")
            raise

    def _convert_to_voltage(self, data, pga):
        raw = (data[0] << 8) | data[1]
        if raw > 0x7FFF:
            raw -= 0x10000
        return raw * (pga / 32768.0)

    def close(self):
        if not self._closed and self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._closed = True

    def __del__(self):
        self.close()

def main():
    adc = None
    def signal_handler(sig, frame):
        if adc is not None:
            adc.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        adc = ADS1x15(address=0x48, busnum=1, sps=8, pga=6144)
        for ch in range(4):
            try:
                voltage = adc.read(ch)
                logging.info(f"Channel {ch}: {voltage:.2f} mV")
            except Exception as e:
                logging.error(f"Failed to read channel {ch}: {e}")
    finally:
        if adc is not None:
            adc.close()

if __name__ == "__main__":
    main()

