import time
import logging
import configparser
import random
import signal
import sys
from gpiozero import AngularServo

CONFIG_FILE = 'config.ini'
LOG_FILE = 'hydroponics.log'

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

servo_pin = 17
pot_pin = 18
DEFAULT_CONFIG = {
    'CALIBRATION': {
        'min_angle': '0',
        'max_angle': '90',
        'min_pot_value': '0.1',
        'max_pot_value': '0.9'
    }
}

running = True
servo = None


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def load_config():
    config = configparser.ConfigParser()
    if not config.read(CONFIG_FILE):
        logging.warning(f"Config file {CONFIG_FILE} not found; creating with defaults.")
        try:
            with open(CONFIG_FILE, 'w') as f:
                config.write(f)
        except OSError as e:
            logging.error(f"Could not write default config: {e}")
            sys.exit(1)
    return config


def read_potentiometer(config):
    try:
        pot_value = random.uniform(float(config['CALIBRATION']['min_pot_value']), float(config['CALIBRATION']['max_pot_value']))
        logging.info(f"Simulated potentiometer reading: {pot_value:.4f}")
        return pot_value
    except Exception as e:
        logging.error(f"Error reading potentiometer: {e}")
        return 0.5


def read_temperature():
    try:
        temperature = random.uniform(20, 30)
        logging.info(f"Simulated temperature reading: {temperature:.2f}°C")
        return temperature
    except Exception as e:
        logging.error(f"Error reading temperature: {e}")
        return 25.0


def read_greenness():
    try:
        greenness = random.randint(0, 100)
        logging.info(f"Simulated plant greenness score: {greenness}")
        return greenness
    except Exception as e:
        logging.error(f"Error reading greenness: {e}")
        return 50


def calculate_temperature_factor(temperature):
    if temperature < 22:
        return 0.0
    elif temperature > 28:
        return 1.0
    else:
        return (temperature - 22) / (28 - 22)


def calculate_greenness_factor(greenness):
    factor = 1.0 - (greenness / 100.0)
    return max(0.0, min(1.0, factor))


def calculate_vent_angle(temperature_factor, greenness_factor, min_angle, max_angle, min_pot_value, max_pot_value):
    pot_value = random.uniform(float(min_pot_value), float(max_pot_value))
    pot_weight = 0.4
    temp_weight = 0.6
    pot_contribution = pot_value * pot_weight
    temp_contribution = temperature_factor * temp_weight
    total = pot_contribution + temp_contribution
    angle = (total * (max_angle - min_angle) / 2.0) + min_angle
    return max(min_angle, min(max_angle, angle))


def main():
    global servo
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    config = load_config()
    try:
        min_angle = float(config['CALIBRATION']['min_angle'])
        max_angle = float(config['CALIBRATION']['max_angle'])
        min_pot_value = float(config['CALIBRATION']['min_pot_value'])
        max_pot_value = float(config['CALIBRATION']['max_pot_value'])
    except KeyError as e:
        logging.error(f"Missing config key: {e}")
        sys.exit(1)
    try:
        servo = AngularServo(
            servo_pin,
            initial_angle=min_angle,
            min_angle=min_angle,
            max_angle=max_angle,
            min_pulse_width=1.0 / 1000,
            max_pulse_width=2.0 / 1000,
            frame_rate=50
        )
    except Exception as e:
        logging.error(f"Failed to initialize servo on GPIO{servo_pin}: {e}")
        sys.exit(1)
    logging.info("Hydroponics vent control system started.")
    try:
        while running:
            temperature = read_temperature()
            greenness = read_greenness()
            temperature_factor = calculate_temperature_factor(temperature)
            greenness_factor = calculate_greenness_factor(greenness)
            vent_angle = calculate_vent_angle(
                temperature_factor,
                greenness_factor,
                min_angle,
                max_angle,
                min_pot_value,
                max_pot_value
            )
            logging.info(f"Temperature: {temperature:.2f}°C, Greenness: {greenness}, Vent Angle: {vent_angle:.1f}°")
            try:
                servo.angle = vent_angle
            except Exception as e:
                logging.error(f"Failed to set servo angle: {e}")
            time.sleep(5)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if servo is not None:
            try:
                servo.close()
                logging.info("Servo closed.")
            except Exception as e:
                logging.error(f"Error closing servo: {e}")
        logging.info("Hydroponics vent control system stopped.")


if __name__ == '__main__':
    main()

