import time
import random
import signal
import sys
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Configuration
I2C_ADDRESS = 0x69
BUZZER_PIN = 17
TEMP_THRESHOLD = 30.0
LOOP_DELAY = 0.1
BUZZER_DURATION = 1.0

# Global resources for cleanup
i2c = None
amg = None
buzzer = None
running = True


def cleanup():
    """Release all hardware resources."""
    global i2c, buzzer
    if buzzer is not None:
        buzzer.close()
        buzzer = None
    if i2c is not None:
        i2c.deinit()
        i2c = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_sensor():
    """Initialize I2C bus and AMG8833 sensor. Returns sensor object or None."""
    global i2c, amg
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

    try:
        amg = adafruit_amg88xx.AMG88XX(i2c, addr=I2C_ADDRESS)
        time.sleep(0.1)  # Allow sensor to stabilize after init
        return amg
    except ValueError as e:
        print(f"AMG8833 not found at address 0x{I2C_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing AMG8833: {e}")
        return None


def init_buzzer():
    """Initialize the buzzer on GPIO17."""
    global buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        return buzzer
    except Exception as e:
        print(f"Error initializing buzzer on GPIO{BUZZER_PIN}: {e}")
        return None


def detect_human(thermal_data):
    """Return True if any pixel in the 8x8 thermal frame exceeds the threshold."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > TEMP_THRESHOLD:
                return True
    return False


def trigger_alert(buzzer):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
    except Exception as e:
        print(f"Error triggering buzzer: {e}")


def simulate_thermal_data():
    """Generate simulated 8x8 thermal data (20-45°C)."""
    return [[random.uniform(20, 45) for _ in range(8)] for _ in range(8)]


def main():
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    amg = init_sensor()
    buzzer = init_buzzer()

    if amg is None:
        print("Using simulated thermal data (no sensor detected).")
        thermal_data = simulate_thermal_data()
    else:
        thermal_data = None

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            if amg is not None:
                try:
                    thermal_data = amg.pixels
                except Exception as e:
                    print(f"Error reading thermal data: {e}")
                    thermal_data = None
            else:
                thermal_data = simulate_thermal_data()

            if detect_human(thermal_data):
                print("Human detected!")
                trigger_alert(buzzer)
            else:
                print("No human detected.")

            time.sleep(LOOP_DELAY)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

