from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cam0 = None
    cam1 = None

    try:
        cam0 = Picamera2(camera_num=0)
        cam1 = Picamera2(camera_num=1)

        config = cam0.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameDurationLimits": (33333, 33333)}
        )
        cam0.configure(config)
        cam1.configure(config)

        cam0.start()
        cam1.start()
        time.sleep(0.5)

        while running:
            try:
                img0 = cam0.capture_array()
                img1 = cam1.capture_array()
            except Exception as e:
                print(f"Error capturing frames: {e}", file=sys.stderr)
                break

            if img0 is None or img1 is None:
                print("Error: received None frame", file=sys.stderr)
                break

            try:
                img = np.hstack((img0, img1))
            except Exception as e:
                print(f"Error combining frames: {e}", file=sys.stderr)
                break

            try:
                cv2.imshow("Dual CSI Cameras", img)
            except cv2.error as e:
                print(f"OpenCV display error: {e}", file=sys.stderr)
                break

            key = cv2.waitKey(30) & 0xFF
            if key == 27:  # ESC
                break

    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    finally:
        if cam0 is not None:
            try:
                cam0.stop()
            except Exception:
                pass
        if cam1 is not None:
            try:
                cam1.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

