#!/usr/bin/env python3
"""
QR Code Scanner for Raspberry Pi using picamera2 and pyzbar.
Captures a 640x480 frame, decodes QR codes, and prints a greeting.
"""

import sys
import signal
import cv2
from pyzbar.pyzbar import decode as pyzbar_decode
from picamera2 import Picamera2

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initialize the Raspberry Pi camera using picamera2."""
    try:
        picam2 = Picamera2()
        # Configure for 640x480 RGB888 (BGR for OpenCV)
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def capture_frame(picam2):
    """Capture a single frame from the camera."""
    try:
        frame = picam2.capture_array()
        if frame is None or frame.size == 0:
            print("Error: Captured empty frame.", file=sys.stderr)
            return None
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}", file=sys.stderr)
        return None

def decode_qr_code(frame):
    """Decode QR codes from a BGR frame using pyzbar."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar_decode(gray)
        return decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}", file=sys.stderr)
        return []

def process_qr_code(decoded_objects):
    """Process detected QR codes and print a greeting."""
    if decoded_objects:
        print("Hello, World!")
    else:
        print("No QR code detected.")

def main():
    """Main function to run the QR code scanner."""
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    try:
        frame = capture_frame(picam2)
        if frame is None:
            sys.exit(1)

        decoded_objects = decode_qr_code(frame)
        process_qr_code(decoded_objects)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Release camera resources
        try:
            picam2.stop()
            picam2.close()
        except Exception as e:
            print(f"Error releasing camera: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

