#!/usr/bin/env python3
"""
Microscope Stage Controller for Raspberry Pi

Controls two stepper motors (X and Y axes) via gpiozero, captures images
with picamera2, and allows sweeping the stage for automated microscopy.

Wiring (BCM numbering):
  X_DIR  -> GPIO17
  X_STEP -> GPIO18
  X_ENABLE -> GPIO27
  Y_DIR  -> GPIO22
  Y_STEP -> GPIO23
  Y_ENABLE -> GPIO24
  X_LIMIT -> GPIO5
  Y_LIMIT -> GPIO6
"""

import json
import os
import signal
import sys
import time
from pathlib import Path

from gpiozero import DigitalOutputDevice, Button
from gpiozero.exc import GPIOZeroError, DeviceClosed

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
X_DIR_PIN = 17
X_STEP_PIN = 18
X_ENABLE_PIN = 27
Y_DIR_PIN = 22
Y_STEP_PIN = 23
Y_ENABLE_PIN = 24
X_LIMIT_PIN = 5
Y_LIMIT_PIN = 6

STEPS_PER_REVOLUTION = 1600
MOTOR_DELAY = 0.0005

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
x_position = 0
y_position = 0
running = True

# gpiozero devices
x_dir = y_dir = x_step = y_step = x_enable = y_enable = None
x_limit = y_limit = None

# picamera2
picam2 = None

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def cleanup(signum=None, frame=None):
    """Release all hardware resources and disable motors on exit."""
    global running
    running = False
    try:
        if x_enable is not None:
            x_enable.off()
        if y_enable is not None:
            y_enable.off()
    except Exception:
        pass
    try:
        if x_limit is not None:
            x_limit.close()
    except Exception:
        pass
    try:
        if y_limit is not None:
            y_limit.close()
    except Exception:
        pass
    try:
        if x_dir is not None:
            x_dir.close()
    except Exception:
        pass
    try:
        if y_dir is not None:
            y_dir.close()
    except Exception:
        pass
    try:
        if x_step is not None:
            x_step.close()
    except Exception:
        pass
    try:
        if y_step is not None:
            y_step.close()
    except Exception:
        pass
    try:
        if picam2 is not None:
            picam2.close()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

# ---------------------------------------------------------------------------
# Motor helpers
# ---------------------------------------------------------------------------

def move_steps(direction, steps, delay):
    """Move *steps* steps in the given direction (1=forward, 0=backward)."""
    global x_position, y_position
    if direction not in (0, 1):
        raise ValueError("direction must be 0 or 1")
    if steps < 0:
        raise ValueError("steps must be non-negative")

    if direction == 1:
        dir_val = 1
    else:
        dir_val = 0

    if x_step is None or y_step is None:
        raise RuntimeError("Stepper pins not initialised")

    for _ in range(steps):
        if not running:
            return
        x_step.on()
        time.sleep(delay)
        x_step.off()
        time.sleep(delay)
        if direction == 1:
            x_position += 1
        else:
            x_position -= 1
        if x_position < 0:
            x_position = 0
        if x_position >= STEPS_PER_REVOLUTION:
            x_position = 0

        if y_step is None:
            raise RuntimeError("Stepper pin not initialised")
        y_step.on()
        time.sleep(delay)
        y_step.off()
        time.sleep(delay)
        if direction == 1:
            y_position += 1
        else:
            y_position -= 1
        if y_position < 0:
            y_position = 0
        if y_position >= STEPS_PER_REVOLUTION:
            y_position = 0

    if x_enable is not None:
        x_enable.off()
    if y_enable is not None:
        y_enable.off()


def home_stage():
    """Move both axes toward their limit switches (direction=0)."""
    global x_position, y_position
    print("Moving to home position...")
    if x_limit is None or y_limit is None:
        raise RuntimeError("Limit switches not initialised")
    if x_limit.is_active:
        print("X limit switch triggered; cannot home")
        return
    if y_limit.is_active:
        print("Y limit switch triggered; cannot home")
        return

    move_steps(0, x_position, MOTOR_DELAY)
    move_steps(0, y_position, MOTOR_DELAY)
    print("Home position reached.")
    x_position = 0
    y_position = 0
    if x_enable is not None:
        x_enable.off()
    if y_enable is not None:
        y_enable.off()


# ---------------------------------------------------------------------------
# Camera helpers
# ---------------------------------------------------------------------------

def init_camera():
    """Initialise picamera2; return the camera object or None on failure."""
    global picam2
    try:
        from picamera2 import Picamera2
    except ImportError:
        print("picamera2 not installed; install with: pip install picamera2")
        return None
    try:
        picam2 = Picamera2()
        config = picam2.create_still_configuration(
            main={"size": (1280, 720), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Camera init failed: {e}")
        picam2 = None
        return None


def capture_image(x, y, image_dir):
    """Capture a 1280x720 JPEG at (x, y) and return the path."""
    if picam2 is None:
        print("Camera not initialised")
        return None
    try:
        Path(image_dir).mkdir(parents=True, exist_ok=True)
        filename = f"image_{x:04d}_{y:04d}.jpg"
        filepath = os.path.join(image_dir, filename)
        picam2.capture_file(filepath)
        print(f"Image saved: {filepath}")
        return filepath
    except Exception as e:
        print(f"Capture error: {e}")
        return None


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    global x_position, y_position, running

    # --- Initialise GPIO devices (active-low enable, pull-up on limit switches) ---
    try:
        x_dir = DigitalOutputDevice(X_DIR_PIN)
        y_dir = DigitalOutputDevice(Y_DIR_PIN)
        x_step = DigitalOutputDevice(X_STEP_PIN)
        y_step = DigitalOutputDevice(Y_STEP_PIN)
        x_enable = DigitalOutputDevice(X_ENABLE_PIN, active_high=False)
        y_enable = DigitalOutputDevice(Y_ENABLE_PIN, active_high=False)
        x_limit = Button(X_LIMIT_PIN, pull_up=True)
        y_limit = Button(Y_LIMIT_PIN, pull_up=True)
    except GPIOZeroError as e:
        print(f"GPIO init failed: {e}")
        cleanup()
        sys.exit(1)

    # --- Initialise camera ---
    init_camera()

    # --- CLI menu ---
    while running:
        print("\n=== Microscope Stage Controller ===")
        print("Commands: H=home, S=<x>, E=<y>, C=<dir>, Q=quit")
        print("Limit switches: X=GPIO5, Y=GPIO6 (pull-up, active LOW)")
        try:
            cmd = input("Enter command: ").strip().upper()
        except EOFError:
            break

        if cmd == "H":
            home_stage()
        elif cmd == "S":
            try:
                x = int(input("X steps: "))
                move_steps(1, x, MOTOR_DELAY)
            except ValueError:
                print("Invalid X value")
        elif cmd == "E":
            try:
                y = int(input("Y steps: "))
                move_steps(1, y, MOTOR_DELAY)
            except ValueError:
                print("Invalid Y value")
        elif cmd == "C":
            try:
                x = int(input("X steps: "))
                y = int(input("Y steps: "))
                move_steps(1, x, MOTOR_DELAY)
                move_steps(1, y, MOTOR_DELAY)
            except ValueError:
                print("Invalid coordinates")
        elif cmd == "Q":
            break
        else:
            print("Unknown command")

    cleanup()


if __name__ == "__main__":
    main()

