from typing import Tuple, Optional

from flask import Flask, render_template, Response, request
from picamera2 import Picamera2

from config import Classifier, MotionDetector, mail_config
from helpers import config, capture, detect

app = Flask(__name__)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
camera: Optional[Picamera2] = None
shutdown_event = threading.Event()


def init_camera() -> Picamera2:
    """Initialize the Raspberry Pi camera; exit on failure."""
    global camera
    try:
        cam = Picamera2()
        # JPEG streaming at 640x480; picamera2 uses a still/preview config.
        video_config = cam.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            transform=transform,
        )
        cam.configure(video_config)
        cam.start()
        camera = cam
        return cam
    except Exception as exc:
        print(f"ERROR: Failed to initialize camera: {exc}")
        traceback.print_exc()
        raise


def transform(vflip: bool = False, hflip: bool = False) -> dict:
    """picamera2 transform dict: vflip and hflip are keyword-only; return None if not used."""
    if vflip:
        return {"transform": {"vflip": True)}
    if hflip:
        return {"transform": {"hflip": True)}
    return None


def send_email(frame: bytes, config: dict) -> None:
    """Send an email notification; tolerate failures without crashing."""
    try:
        mail_config.send_email(frame, config)
    except Exception as exc:
        print(f"ERROR: Failed to send email: {exc}")


def check_for_objects() -> None:
    """Background thread: detect objects and send email notifications."""
    last_email_time = 0.0
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == "motion_detector":
                jpeg, detected = detect(config, camera)
            else:
                jpeg, detected = detect(config.classifier, camera)

            if detected and config.send_email_notifications:
                now = time.time()
                if now - last_email_time >= config.email_send_interval:
                    last_email_time = now
                    send_email(jpeg, config)
        except Exception as exc:
            print(f"ERROR in check_for_objects: {exc}")
            traceback.print_exc()
        shutdown_event.wait(1.0)


def generate_frame() -> bytes:
    """Yield JPEG-encoded frames for the multipart/x-mixed-replace stream."""
    while not shutdown_event.is_set():
        try:
            if config.live_preview:
                jpeg, _ = detect(config.classifier, camera)
            else:
                jpeg, _ = detect(config.classifier, camera)
            yield (
                b"--frame\r\n"
                b"Content-Type: image/jpeg\r\n\r\n" + jpeg + b"\r\n\r\n"
            )
        except Exception as exc:
            print(f"ERROR generating frame: {exc}")
            shutdown_event.wait(0.1)


@app.route("/")
def index() -> str:
    """Main page: form for configuration + live preview."""
    return render_template(
        "index.html",
        classifiers=config.classifier_names,
        config=config,
    )


@app.route("/video_feed")
def video_feed() -> Response:
    """Multipart/x-mixed-replace stream of JPEG frames."""
    return Response(
        generate_frame(),
        mimetype="multipart/x-mixed-replace; boundary=frame",
    )


def cleanup() -> None:
    """Release camera resources on exit."""
    global camera
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass
        camera = None


def signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    shutdown_event.set()
    cleanup()
    exit(0)


if __name__ == "__main__":
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Register cleanup on normal exit
    atexit.register(cleanup)

    # Initialize camera
    try:
        init_camera()
    except Exception:
        print("ERROR: Camera initialization failed. Exiting.")
        exit(1)

    # Start background object-detection thread
    object_thread = threading.Thread(target=check_for_objects, daemon=True)
    object_thread.start()

    # Run Flask app
    try:
        app.run(host="0.0.0.0", port=5000, threaded=True)
    finally:
        shutdown_event.set()
        cleanup()

