import time
import datetime
import statistics
import json
import logging
import signal
import sys
from gpiozero import OutputDevice, InputDevice

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("config.json not found; creating default config.")
        try:
            with open(config_file, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            logging.error(f"Could not write default config: {e}")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config.json: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def measure_distance(trigger, echo, offset, max_distance):
    try:
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.warning("Echo pin stuck LOW (timeout).")
                return None
        pulse_start = time.time()

        timeout = time.time() + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.warning("Echo pin stuck HIGH (timeout).")
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2
        distance += offset
        distance = max(0.0, min(distance, max_distance))
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None


def get_water_level(trigger, echo, offset, max_distance):
    readings = []
    for _ in range(3):
        d = measure_distance(trigger, echo, offset, max_distance)
        if d is not None:
            readings.append(d)
        time.sleep(0.1)
    if not readings:
        logging.error("No valid readings from sensor.")
        return None
    return statistics.median(readings)


def check_alerts(alerts, water_level, alert_threshold_low, alert_threshold_high):
    if water_level < alert_threshold_low:
        if "low_alert" not in alerts:
            alerts["low_alert"] = time.time()
        if (time.time() - alerts["low_alert"]) > alert_repeat_delay:
            logging.warning(f"Low water level alert: {water_level:.2f}")
    elif water_level > alert_threshold_high:
        if "high_alert" not in alerts:
            alerts["high_alert"] = time.time()
        if (time.time() - alerts["high_alert"]) > alert_repeat_delay:
            logging.warning(f"High water level alert: {water_level:.2f}")
    return alerts


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    log_file = config["log_file"]
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting water level monitoring system.")

    sensors = []
    try:
        for s in config["sensors"]:
            trigger = OutputDevice(s["trigger_pin"])
            echo = InputDevice(s["echo_pin"])
            sensors.append((trigger, echo, s["offset"], s["max_distance"]))
            logging.info(f"Initialized sensor on trigger={s['trigger_pin']}, echo={s['echo_pin']}")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        logging.info("Exiting cleanly due to GPIO initialization failure.")
        return

    alerts = {"low_alert": 0, "high_alert": 0}
    excluded_sensors = set()

    try:
        while _running:
            water_levels = []
            for trigger, echo, offset, max_distance in sensors:
                if (trigger, echo) in excluded_sensors:
                    continue
                w = get_water_level(trigger, echo, offset, max_distance)
                if w is not None:
                    water_levels.append(w)
                time.sleep(0.1)

            if not water_levels:
                logging.warning("No valid water level readings.")
            else:
                avg_water_level = sum(water_levels) / len(water_levels)
                logging.info(f"Average water level: {avg_water_level:.2f}")

                check_alerts(alerts, avg_water_level, config["alert_threshold_low"], config["alert_threshold_high"])

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        for trigger, echo in (t, e) for t, e in sensors:
            try:
                trigger.close()
                echo.close()
            except Exception:
                pass
        logging.info("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

