#!/usr/bin/env python3
"""
Raspberry Pi Greenhouse Control System

Controls a simulated greenhouse environment using voice commands.
Uses RPi.GPIO for GPIO control, picamera2 for camera capture, and adafruit_dht for temperature sensing.
"""

import RPi.GPIO as GPIO
import time
import datetime
import os
import signal
import sys
import speech_recognition as sr
import board
import adafruit_dht

# Constants
LIGHT_PIN = 17
DHT_PIN = 4
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"
COMMANDS = {
    "turn on the lights": "turn_lights_on",
    "turn off the lights": "turn_lights_off",
    "what is the temperature": "read_temperature",
    "take a picture": "capture_image"
}

# Global state
running = True
camera = None
dht_device = None

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False

def cleanup():
    global camera, dht_device
    if camera:
        try:
            camera.stop()
            camera.close()
        except Exception as e:
            print(f"Error closing camera: {e}")
    if dht_device:
        try:
            dht_device.exit()
        except Exception as e:
            print(f"Error exiting DHT device: {e}")
    GPIO.cleanup()
    print("GPIO cleaned up.")

def init_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"GPIO initialization failed: {e}. Falling back to simulation mode.")
        global dht_device
        try:
            dht_device = adafruit_dht.DHT11(board.D4)
            print("DHT11 initialized successfully.")
        except Exception as e:
            print(f"DHT11 initialization failed: {e}. Falling back to simulation mode.")
        return False
    return True

def init_camera():
    global camera
    try:
        from picamera2 import Picamera2
        cam = Picamera2()
        cam.configure(cam.create_still_configuration(main={"size": CAMERA_RESOLUTION}))
        camera = cam
        print("Camera initialized successfully.")
        return True
    except Exception as e:
        print(f"Camera initialization failed: {e}. Falling back to simulation mode.")
        camera = None
        return False

def read_temperature():
    if dht_device:
        try:
            temp = dht_device.temperature
            if temp is not None:
                return round(temp, 1)
            else:
                print("DHT11 returned None temperature.")
        except RuntimeError as e:
            print(f"DHT11 read error (checksum or timeout): {e}")
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}")
    else:
        print("DHT11 not available, using simulated temperature.")
    return round(25.0 + (time.time() % 10), 1)

def turn_lights_on():
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        print("Lights turned on.")
    else:
        print("Lights turned on (simulation).")

def turn_lights_off():
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        print("Lights turned off.")
    else:
        print("Lights turned off (simulation).")

def capture_image():
    if camera:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            print(f"Image saved as {filename}")
        except Exception as e:
            print(f"Camera capture failed: {e}")
    else:
        print("Camera not available, image capture simulated.")

def listen_for_command():
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Listening for voice command...")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
    except Exception as e:
        print(f"Microphone error: {e}")
        return None

    try:
        text = recognizer.recognize_google(audio).lower()
        print(f"Recognized: {text}")
        if WAKE_WORD in text:
            command = text.split(" ", 1)[1] if " " in text else text
            return command
    except sr.UnknownValueError:
        print("Could not understand audio")
    except sr.RequestError as e:
        print(f"Speech recognition service error: {e}")
    return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    gpio_ok = init_gpio()
    camera_ok = init_camera()

    try:
        while running:
            command = listen_for_command()
            if command:
                if command in COMMANDS:
                    action = COMMANDS[command]
                    if action == "turn_lights_on":
                        turn_lights_on()
                    elif action == "turn_lights_off":
                        turn_lights_off()
                    elif action == "read_temperature":
                        temp = read_temperature()
                        print(f"Temperature: {temp}°C")
                    elif action == "capture_image":
                        capture_image()
                else:
                    print(f"Unknown command: {command}")
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

