import select
import sys
import time
import signal
import config
import face
import hardware

# Global resources for cleanup
_camera = None
_box = None
_running = True


def _cleanup():
    """Release camera and restore box state on exit."""
    global _camera, _box
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        _camera = None
    if _box is not None:
        try:
            _box.lock()
        except Exception:
            pass
        _box = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_camera():
    """Initialize picamera2 and return a BGR-compatible capture handle."""
    global _camera
    try:
        from picamera2 import Picamera2
    except ImportError:
        print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
        sys.exit(1)

    cam = Picamera2()
    config_cam = cam.create_preview_configuration(
        main={"size": (640, 480), "format": "XRGB8888"}
    )
    cam.configure(config_cam)
    cam.start()
    _camera = cam
    return cam


def _init_box():
    """Create and return a hardware.Box instance, locked on startup."""
    global _box
    try:
        box = hardware.Box()
    except Exception as exc:
        print(f"Failed to initialize Box: {exc}", file=sys.stderr)
        sys.exit(1)

    box.lock()
    _box = box
    return box


def _detect_face(gray):
    """Detect a single face in grayscale; return (x, y, w, h) or None."""
    try:
        cascade = cv2.CascadeClassifier(config.CAHADE_PATH)
        if cascade.empty():
            print("Error: failed to load Haar cascade.", file=sys.stderr)
            return None
        faces = cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
        if len(faces) == 1:
            return tuple(faces[0])
        return None
    except Exception as exc:
        print(f"Error during face detection: {exc}", file=sys.stderr)
        return None


def _process_face(gray, box):
    """Process a detected face: resize to 100x100 and predict."""
    try:
        face_coords = _detect_face(gray)
        if face_coords is None:
            return

        x, y, w, h = face_coords
        cropped = gray[y:y + h, x:x + w]
        resized = cv2.resize(cropped, (100, 100))

        try:
            model = cv2.face.EigenFaceRecognizer_create()
            model.read(config.TRAINING_FILE)
        except Exception as exc:
            print(f"Error loading training data: {exc}", file=sys.stderr)
            return

        label, confidence = model.predict(resized)
        print(f"Predicted {label} face with confidence {confidence}")

        if label == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > confidence > 1500:
            print("Recognized face! Unlocking box...")
            box.unlock()
        else:
            print("Face not recognized.")
    except Exception as exc:
        print(f"Error during face processing: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    box = _init_box()
    cam = _init_camera()

    try:
        while _running:
            try:
                if box.is_button_up():
                    if not box.is_locked:
                        box.lock()
                        print("Box is now locked.")
                    else:
                        print("Button pressed, looking for face...")
                        try:
                            frame = cam.capture_array()
                            if frame is None:
                                print("Warning: captured empty frame.", file=sys.stderr)
                                time.sleep(0.1)
                                continue
                            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                            _process_face(gray, box)
                        except Exception as exc:
                            print(f"Error during capture/processing: {exc}", file=sys.stderr)
                            time.sleep(0.1)
                else:
                    time.sleep(0.1)
            except Exception as exc:
                print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
                time.sleep(0.1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

