import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

INPUT_PINS = (4, 5, 6)
OUTPUT_PINS = (23, 24)
POLL_INTERVAL = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    inputs = []
    outputs = []
    state = {"gpio24_state": False}

    try:
        for pin in INPUT_PINS:
            try:
                inputs.append(Button(pin, pull_up=True))
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Error: failed to initialize input GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)

        for pin in OUTPUT_PINS:
            try:
                outputs.append(LED(pin, initial_value=False))
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Error: failed to initialize output GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)

        outputs[0].value = False
        outputs[1].value = False

        while _running:
            for pin in INPUT_PINS:
                if not inputs[pin - 4].is_active:
                    if pin == INPUT_PINS[0]:
                        outputs[0].value = True
                    elif pin == INPUT_PINS[1]:
                        outputs[0].value = False
                    elif pin == INPUT_PINS[2]:
                        state["gpio24_state"] = not state["gpio24_state"]
                        outputs[1].value = state["gpio24_state"]

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in inputs + outputs:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

