import time
import os
import signal
import sys
from picamera2 import Picamera2

# Configuration
IMAGE_DIR = "./saved_imgs"
RESOLUTION = (640, 480)
DELTA_THRESH = 5
MIN_AREA = 5000
MIN_MOTION_FRAMES = 8
MIN_UPLOAD_SECONDS = 30

# Global shutdown flag
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_directories():
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        print(f"Error setting up directories: {e}")
        return False
    return True


def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": RESOLUTION, "format": "BGR888"}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(2.0)  # Warm-up for auto-exposure
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None


def detect_motion(frame1, frame2, delta_thresh):
    diff = cv2.absdiff(frame1, frame2)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (5, 5), 0)
    _, thresh = cv2.threshold(blur, delta_thresh, 255, cv2.THRESH_BINARY)
    thresh = cv2.dilate(thresh, None, iterations=2)
    contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    for contour in contours:
        if cv2.contourArea(contour) < MIN_AREA:
            continue
        return True
    return False


def process_frame(frame, avg, motion_flag, motion_times, picam2):
    text = "No motion detected"
    if detect_motion(frame, avg, DELTA_THRESH):
        if not motion_flag:
            motion_times = [0, 0, 0, 0, 0, 0, 0, 0]
        motion_times = [x + 1 if i < len(motion_times) else 0 for i, x in enumerate(motion_times)]
        if all(t > 0 for t in motion_times):
            text = "Motion Detected!"
            if all(t >= MIN_MOTION_FRAMES for t in motion_times):
                if save_image(frame, IMAGE_DIR):
                    upload_image(frame, IMAGE_DIR)
                print("Motion detected and image saved.")
    else:
        motion_times = [0] * len(motion_times)
    return frame, text, motion_flag, motion_times


