    try:
        filename = f"motion_{int(time.time())}.jpg"
        filepath = os.path.join(image_dir, filename)
        success = cv2.imwrite(filepath, frame)
        if success:
            print(f"Image saved: {filepath}")
            return True
        else:
            print(f"Error saving image: {filepath}")
            return False
    except Exception as e:
        print(f"Error saving image: {e}")
        return False


def upload_image(frame, image_dir):
    try:
        filename = f"motion_{int(time.time())}.jpg"
        filepath = os.path.join(image_dir, filename)
        if save_image(frame, image_dir):
            print(f"Uploading image: {filepath}")
            # Placeholder for actual upload (e.g., via FTP/SFTP or AWS S3)
    except Exception as e:
        print(f"Error uploading image: {e}")


