    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not setup_directories():
        sys.exit(1)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    avg = None
    motion_flag = False
    motion_times = [0] * MIN_MOTION_FRAMES

    try:
        while _running:
            frame = picam2.capture_array()
            if frame is None:
                print("Error: Failed to capture frame.")
                break

            if avg is None:
                avg = frame.astype("float")
                continue

            # Picamera2 BGR888 format returns a 3-channel BGR array
            frame = frame[:, :, ::-1].copy()  # Convert RGB to BGR for OpenCV consistency
            frame, text, motion_flag, motion_times = process_frame(frame, avg, motion_flag, motion_times, picam2)

            cv2.putText(frame, text, (10, 20), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 255), 2)
            cv2.imshow("Motion Detection", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cv2.destroyAllWindows()
        try:
            picam2.stop()
        except Exception:
            pass
        print("Camera released. Exiting.")


if __name__ == "__main__":
    main()

