import io
import time
import threading
import zmq
import gps3
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

shutdown_event = threading.Event()
gps_lock = threading.Lock()
gps_data = {"lat": None, "lon": None, "mag": None, "alt": None}

def restart_gps():
    """Restart gpsd with a retry; return True if the connection succeeded."""
    for attempt in range(1, 4):
        try:
            ret = subprocess.run(
                ["sudo", "systemctl", "restart", "gpsd"],
                capture_output=True, text=True, timeout=10
            )
            if ret.returncode == 0:
                time.sleep(2)
                return True
            print(f"gpsd restart attempt {attempt} failed: {ret.stderr.strip()}")
        except subprocess.CalledProcessError as e:
            print(f"gpsd restart attempt {attempt} failed: {e.stderr.strip()}")
        except subprocess.TimeoutExpired:
            print(f"gpsd restart attempt {attempt} timed out")
        except FileNotFoundError:
            print("systemctl not found; cannot restart gpsd")
        time.sleep(2)
    print("Falling back to default GPS coordinates: 22.483425, 88.455463")
    with gps_lock:
        gps_data["lat"] = 22.483425
        gps_data["lon"] = 88.455463
    return False

def get_gps_data():
    """Poll gpsd for TPV latitude/longitude; return dict or None on failure."""
    with gps_lock:
        if gps_data["lat"] is not None and gps_data["lon"] is not None:
            return gps_data
        try:
            sock = gps3.GPSDSocket()
            try:
                sock.connect()
                sock.watch()
                for raw in sock:
                    if shutdown_event.is_set():
                        return None
                    if raw and hasattr(raw, 'class') and raw.class == 'TPV':
                        lat = raw.lat
                        lon = raw.lon
                        if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                            with gps_lock:
                                gps_data["lat"] = lat
                                gps_data["lon"] = lon
                            return gps_data
                        print("GPS fix: non-numeric lat/lon")
                    time.sleep(0.5)
            except Exception as e:
                print(f"GPS socket error: {e}")
            finally:
                try:
                    sock.close()
                except Exception:
                    pass
        except Exception as e:
            print(f"GPS connection error: {e}")
        return None

def send_frame(socket, frame_data):
    """Send a frame as 'lat,lon,mag,alt' + raw bytes."""
    with gps_lock:
        lat = gps_data["lat"] if gps_data["lat"] is not None else "N/A"
        lon = gps_data["lon"] if gps_data["lon"] is not None else "N/A"
        mag = gps_data["mag"] if gps_data["mag"] is not None else "N/A"
        alt = gps_data["alt"] if gps_data["alt"] is not None else "N/A"
        metadata = f"{lat},{lon},{mag},{alt}"
    try:
        socket.send_string(metadata, zmq.SNDMORE)
        socket.send(frame_data)
    except zmq.ZMQError as e:
        print(f"ZMQ send error: {e}")

def camera_thread():
    """Capture MJPEG frames and publish them over ZMQ."""
    context = None
    try:
        context = zmq.Context()
        socket = context.socket(zmq.PUB)
        socket.setsockopt(zmq.LINGER, 0)
        socket.connect("tcp://192.168.1.4:5555")
        print("ZMQ PUB socket connected to 192.168.1.4:5555")
        picam2 = Picamera2()
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "MJPEG"},
            controls={"FrameRate": 100}
        )
        picam2.configure(config)
        picam2.set_controls({"Rotation": 180})
        encoder = MJPEGEncoder()
        output = Output()
        output.frame = send_frame
        picam2.start_recording(encoder, output)
        print("Camera recording started")
        while not shutdown_event.is_set():
            time.sleep(0.1)
    except zmq.ZMQError as e:
        print(f"ZMQ error in camera thread: {e}")
    except Exception as e:
        print(f"Camera error: {e}")
    finally:
        try:
            picam2.stop_recording()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass
        try:
            socket.close()
        except Exception:
            pass
        try:
            context.close()
        except Exception:
            pass

def gps_thread():
    """Poll gpsd and publish GPS data with camera frames."""
    while not shutdown_event.is_set():
        gps_data = get_gps_data()
        if gps_data:
            with gps_lock:
                lat = gps_data["lat"]
                lon = gps_data["lon"]
                mag = gps_data["mag"]
                alt = gps_data["alt"]
            print(f"GPS: lat={lat}, lon={lon}, mag={mag}, alt={alt}")
        shutdown_event.wait(0.5)

def main():
    if restart_gps():
        print("GPS connection established")
    else:
        print("GPS fallback coordinates: 22.483425, 88.455463")
    gps_thread()
    camera_thread()

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("KeyboardInterrupt received")
    finally:
        shutdown_event.set()
        time.sleep(0.5)
        print("Shutting down...")

