import cv2
import pyzbar.pyzbar as pyzbar
from PIL import Image
import datetime
import csv
import os
import sys
import signal

# Configuration
USB_CAMERA_INDEX = 0
LOG_FILE = "inventory_log.csv"
ERROR_LOG = "error_log.txt"
CAPTURE_DELAY = 0.2  # seconds

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def log_error(message):
    """Append a timestamped error message to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"CRITICAL: Cannot write to error log: {e}", file=sys.stderr)

def initialize_camera(camera_index):
    """Initialize the USB camera and return the capture object."""
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise RuntimeError(f"Cannot open USB camera at index {camera_index}")
        return cap
    except Exception as e:
        log_error(f"Camera initialization failed: {e}")
        return None

def decode_qr_code(image):
    """Decode QR codes from a grayscale image and return the decoded text."""
    try:
        decoded_objects = pyzbar.decode(image)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_item_id(item_id):
    """Validate that the item ID is a non-empty alphanumeric string."""
    if not isinstance(item_id, str):
        return False
    if not item_id:
        return False
    if not item_id.isalnum():
        return False
    return True

def log_to_csv(camera_id, item_id, timestamp):
    """Append a row to the CSV log file, writing the header if the file is empty."""
    try:
        file_exists = os.path.isfile(LOG_FILE) and os.path.getsize(LOG_FILE) > 0
        with open(LOG_FILE, "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(["camera_id", "item_id", "capture_time"])
            writer.writerow([camera_id, item_id, timestamp])
    except Exception as e:
        log_error(f"CSV write failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = initialize_camera(USB_CAMERA_INDEX)
    if camera is None:
        print("Failed to initialize camera. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                log_error("Failed to capture frame from camera.")
                break

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            item_id = decode_qr_code(gray)

            if item_id and validate_item_id(item_id):
                timestamp = datetime.datetime.now().isoformat()
                log_to_csv("Camera 1", item_id, timestamp)
                print(f"Logged: Item ID: {item_id}, Timestamp: {timestamp}")
            else:
                print("No valid QR code detected or invalid data.")

            cv2.waitKey(CAPTURE_DELAY * 1000)
    finally:
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

