                log_to_csv("Camera 1", item_id, timestamp)
                print(f"Logged: Item ID: {item_id}, Timestamp: {timestamp}")
            else:
                print("No valid QR code detected or invalid data.")

            cv2.waitKey(CAPTURE_DELAY * 1000)
    finally:
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

