import asyncio
import logging
import signal
import sys
import threading
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Manages WebSocket clients and broadcasts JPEG frames."""

    def __init__(self):
        self._lock = threading.Lock()
        self._connected = False
        self._loop = None

    def has_connections(self) -> bool:
        with self._lock:
            return self._connected

    def add_connection(self) -> None:
        with self._lock:
            self._connected = True

    def remove_connection(self) -> None:
        with self._lock:
            self._connected = False

    def broadcast(self, data: bytes) -> None:
        if not self._loop:
            logger.warning("WebSocketHandler: loop is not running; cannot broadcast.")
            return
        with self._lock:
            if self._connected:
                try:
                    asyncio.get_event_loop().call_soon_threadsafe(self._loop, self._loop.run_in_executor(None, self._loop.call_async, self._send_frame, data))
                except Exception as exc:
                    logger.error("WebSocketHandler: broadcast failed: %s", exc)
            else:
                logger.debug("WebSocketHandler: no clients connected; skipping broadcast.")


def _send_frame(loop, data: bytes) -> None:
    """Send a JPEG frame via a simulated WebSocket."""
    logger.debug("Simulated WebSocket: %s", data)


class CameraHandler:
    """Streams video from the Raspberry Pi camera via picamera2."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None], width: int = 640, height: int = 480, fps: int = 10):
        self.detect_motion_function = detect_motion_function
        self.width = width
        self.height = height
        self.fps = fps
        self._picam2: Optional[Picamera2] = None
        self._buffer = bytearray()
        self._lock = threading.Lock()
        self._stop_event = threading.Event()
        self._loop = asyncio.get_event_loop()
        self._web_socket_handler = WebSocketHandler()

    def start(self) -> None:
        try:
            self._picam2 = Picamera2()
            config = self._picam2.create_video_configuration(
                main={"size": (self.width, self.height), "format": "RGB888"},
                lores={"size": (self.width, self.height), "format": "RGB888"},
                encode="lores",
            )
            self._picam2.configure(config)
            self._picam2.start()
            logger.info("Camera started: %dx%d @ %d fps", self.width, self.height, self.fps)
            self._buffer_thread = threading.Thread(target=self._buffer_thread_main, daemon=True)
            self._buffer_thread.start()
            return True
        except Exception as exc:
            logger.error("CameraHandler: failed to initialize camera: %s", exc)
            self._picam2 = None
            return False

    def _buffer_thread_main(self) -> None:
        try:
            while not self._stop_event.is_set():
                try:
                    frame = self._picam2.capture_array()
                except Exception as exc:
                    logger.error("Camera capture error: %s", exc)
                    break

                if frame is None:
                    continue

                if frame.dtype != np.uint8:
                    frame = frame.astype(np.uint8)

                if frame.shape[0] != self.height or frame.shape[1] != self.width:
                    logger.warning("Frame shape mismatch: %s", frame.shape)
                    continue

                try:
                    self._buffer_thread_safely(frame.tobytes())
                except Exception as exc:
                    logger.error("Buffer write error: %s", exc)

                try:
                    self._process_frame(frame)
                except Exception as exc:
                    logger.error("Frame processing error: %s", exc)

        except Exception as exc:
            logger.error("Camera buffer thread error: %s", exc)
        finally:
            logger.info("Camera buffer thread exiting.")

    def _buffer_thread_safely(self, data: bytes) -> None:
        with self._lock:
            self._buffer.extend(data)

    def _process_frame(self, frame: np.ndarray) -> None:
        try:
            prev_frame = None
            try:
                prev_frame = self._get_previous_frame()
            except Exception as exc:
                logger.error("Failed to retrieve previous frame: %s", exc)

            if prev_frame is not None:
                try:
                    self.detect_motion_function(prev_frame, frame)
                except Exception as exc:
                    logger.error("Motion detection callback error: %s", exc)

            self._send_frame(frame)

        except Exception as exc:
            logger.error("Frame processing error: %s", exc)

    def _get_previous_frame(self) -> Optional[np.ndarray]:
        with self._lock:
            if not self._buffer:
                return None
            try:
                data = self._buffer[: len(b'\xff\xd8')]
                self._buffer = self._buffer[len(b'\xff\xd8'):]
                return cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
            except Exception as exc:
                logger.error("Failed to decode previous frame: %s", exc)
                return None

    def _send_frame(self, frame: np.ndarray) -> None:
        try:
            ret, encoded = cv2.imencode('.jpg', frame)
            if not ret:
                logger.error("Failed to encode frame to JPEG.")
                return
            data = encoded.tobytes()
            self._web_socket_handler.broadcast(data)
        except Exception as exc:
            logger.error("Failed to send frame: %s", exc)

    def stop(self) -> None:
        self._stop_event.set()
        if self._picam2 is not None:
            try:
                self._picam2.stop()
            except Exception as exc:
                logger.error("Error stopping camera: %s", exc)
            self._picam2 = None
        logger.info("Camera stopped.")


def main() -> None:
    def detect_motion(prev: np.ndarray, curr: np.ndarray) -> None:
        diff = cv2.absdiff(prev, curr)
        gray = cv2.cvtColor(diff, cv2.COLOR_RGB2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        for cnt in contours:
            if cv2.contourArea(cnt) > 500:
                logger.info("Motion detected.")

    handler = CameraHandler(detect_motion, width=640, height=480, fps=10)
    if not handler.start():
        sys.exit(1)

    def _signal_handler(signum, frame):
        logger.info("Signal %s received, shutting down.", signum)
        handler.stop()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        asyncio.run(handler._loop.get_loop())
    except KeyboardInterrupt:
        handler.stop()


if __name__ == "__main__":
    main()

