import os
import time
import signal
import logging
import subprocess
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BROKER_ADDRESS = os.environ.get("MQTT_BROKER_ADDRESS", "localhost")
BROKER_PORT = int(os.environ.get("MQTT_BROKER_PORT", 1883))
IMAGE_TOPIC = os.environ.get("IMAGE_TOPIC", "image_topic")
IMAGE_PATH = os.environ.get("IMAGE_PATH", "captured_images")
CAPTURE_INTERVAL = 1.0 / 30.0

running = True
client = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker successfully.")
    else:
        logger.error(f"Failed to connect to MQTT broker. Reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker. Reason code: {reason_code}")


def capture_image():
    timestamp = int(time.time() * 1000)
    image_path = os.path.join(IMAGE_PATH, f"image_{timestamp}.jpg")
    try:
        result = subprocess.run(
            ["libcamera-still", "--width=256", "--height=256", "-o", image_path],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode != 0:
            logger.error(f"libcamera-still failed (rc={result.returncode}): {result.stderr.strip()}")
            return None
        return image_path
    except subprocess.TimeoutExpired:
        logger.error("libcamera-still timed out.")
        return None
    except FileNotFoundError:
        logger.error("libcamera-still not found. Ensure libcamera-apps is installed.")
        return None
    except Exception as e:
        logger.error(f"Unexpected error capturing image: {e}")
        return None


def publish_image(client, image_path):
    try:
        with open(image_path, "rb") as f:
            image_data = f.read()
        info = client.publish(IMAGE_TOPIC, image_data, qos=0)
        info.wait_for_publish(timeout=5)
        if info.rc == mqtt.MQTT_ERR_SUCCESS:
            logger.info(f"Published image to topic {IMAGE_TOPIC}")
        else:
            logger.error(f"Failed to publish image. MQTT error code: {info.rc}")
    except IOError as e:
        logger.error(f"Error reading image file {image_path}: {e}")
    except Exception as e:
        logger.error(f"Error publishing image: {e}")


def main():
    global client

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    os.makedirs(IMAGE_PATH, exist_ok=True)

    client = mqtt.Client(callback_api_version=CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(BROKER_ADDRESS, BROKER_PORT, keepalive=60)
    except Exception as e:
        logger.error(f"Failed to connect to MQTT broker: {e}")
        return

    client.loop_start()

    try:
        while running:
            image_path = capture_image()
            if image_path:
                publish_image(client, image_path)
            time.sleep(CAPTURE_INTERVAL)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        if client is not None:
            try:
                client.loop_stop()
                client.disconnect()
                logger.info("MQTT client disconnected cleanly.")
            except Exception as e:
                logger.error(f"Error disconnecting MQTT client: {e}")


if __name__ == "__main__":
    main()

