            self._picam2.create_encoder(
                self._picam2.capture_array(),
                format="jpeg",
                quality=85,
            )
        )
        logging.info("Camera recording started.")

    def stop(self) -> None:
        self._running = False
        if self._picam2 is not None:
            try:
                self._picam2.stop_recording()
            except Exception as e:
                logging.error(f"Error stopping recording: {e}")
            try:
                self._picam2.stop()
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
            try:
                self._picam2.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
            self._picam2 = None
        logging.info("Camera stopped.")

    def flush(self) -> None:
        """Emit any buffered frame on shutdown."""
        with self._lock:
            if self._picam2 is None:
