    def flush(self) -> None:
        """Emit any buffered frame on shutdown."""
        with self._lock:
            if self._picam2 is None:
                return
            try:
                self._picam2.capture_buffer(
                    self._picam2.capture_array()
                )
            except Exception as e:
                logging.error(f"Error capturing buffer for flush: {e}")
            try:
                self._picam2.stop_recording()
            except Exception as e:
                logging.error(f"Error stopping recording for flush: {e}")
            try:
                self._picam2.stop()
            except Exception as e:
                logging.error(f"Error stopping camera for flush: {e}")
            try:
                self._picam2.close()
            except Exception as e:
                logging.error(f"Error closing camera for flush: {e}")
            self._picam2 = None
        logging.info("Camera flushed and closed.")


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_camera_stream_buffer: Optional[CameraStreamBuffer] = None
_motion_detection_buffer: Optional[MotionDetectionBuffer] = None


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received; shutting down.")
    if _camera_stream_buffer is not None:
        _camera_stream_buffer.stop()
    if _motion_detection_buffer is not None:
        _motion_detection_buffer.stop()
    raise SystemExit(0)


# ---------------------------------------------------------------------------
# Example usage
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ws_handler = WebSocketHandler()
        _camera_stream_buffer = CameraStreamBuffer(ws_handler)
        _motion_detection_buffer = MotionDetectionBuffer(
            lambda p, c: logging.info("Motion detected!"), ws_handler
        )
        _camera_stream_buffer.start()
        _motion_detection_buffer.start()
        logging.info("Streaming and motion detection running. Press Ctrl+C to stop.")
        while True:
            time.sleep(1)
    except Exception as e:
        logging.error(f"Fatal error in main: {e}")
    finally:
        if _camera_stream_buffer is not None:
            _camera_stream_buffer.stop()
        if _motion_detection_buffer is not None:
            _motion_detection_buffer.stop()

