import io
import logging
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Accumulates and flushes MJPEG frames from picamera2."""

    def __init__(self, camera: Picamera2):
        self.camera = camera
        self.b = io.BytesIO()

    def write(self, d: bytes) -> int:
        try:
            self.b.write(d)
        except OSError as exc:
            logger.error('StreamBuffer I/O error: %s', exc)
            return 0
        try:
            cfg = self.camera.current_configuration()
            encode = cfg.get('encode', None)
            if encode is not None and encode.get('frame_type') is not None:
                frame_type = encode['frame_type']
                if frame_type != 1:  # not I-frame
                    if self.b.tell() > 0:
                        yield self.b.getvalue()
                        self.b.seek(0)
                        self.b.truncate()
            return self.b.write(d)
        except Exception as exc:
            logger.error('StreamBuffer config error: %s', exc)
            return 0


class MotionDetectionBuffer:
    """Detects motion by comparing consecutive decoded MJPEG frames."""

    def __init__(self, callback):
        self.callback = callback
        self.b = io.BytesIO()
        self._prev: np.ndarray | None = None

    def write(self, d: bytes) -> int:
        try:
            self.b.write(d)
        except OSError as exc:
            logger.error('StreamBuffer I/O error: %s', exc)
            return 0
        try:
            if d.startswith(b'\xff\xd8'):
                jpeg = self.b.getvalue()
                if not jpeg:
                    return 0
                try:
                    data = np.frombuffer(jpeg, dtype=np.uint8)
                    frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
                    if frame is None:
                        logger.warning('Frame decode failed: %r', jpeg)
                        return 0
                    if self._prev is not None:
                        self.callback(self._prev, frame)
                    self._prev = frame
                except cv2.error as exc:
                    logger.error('OpenCV decode error: %s', exc)
                finally:
                    self.b.seek(0)
                    self.b.truncate()
        except Exception as exc:
            logger.error('MotionBuffer parse error: %s', exc)
        return self.b.write(d)

