import signal
import sys
import time
import logging
import threading

import cv2
import pygame.mixer
from picamera2 import Picamera2
from gpiozero import Button, OutputDevice

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
log = logging.getLogger(__name__)

BUTTON_PIN = 17
LOCK_PIN = 18
UNLOCK_DELAY = 2.0

_running = threading.Event()


def _signal_handler(signum, frame):
    log.info('Signal %s received, shutting down...', signum)
    _running.clear()


def init_mixer():
    try:
        pygame.mixer.init(48000, -16, 1, 1024)
        welcome = pygame.mixer.Sound(config.WELCOME_SOUND_PATH)
        wait = pygame.mixer.Sound(config.WAIT_SOUND_PATH)
        later = pygame.mixer.Sound(config.LATER_SOUND_PATH)
        return welcome, wait, later
    except Exception as exc:
        log.error('Mixer init failed: %s', exc)
        raise


def init_camera():
    try:
        cam = Picamera2()
        cam.configure(cam.create_preview_configuration(main={'format': 'BGR888', 'size': (640, 480)}))
        cam.start()
        return cam
    except Exception as exc:
        log.error('Camera init failed: %s', exc)
        raise


def init_hardware():
    try:
        btn = Button(BUTTON_PIN, pull_up=True)
        lock = OutputDevice(LOCK_PIN, active_high=True, initial_value=True)
        return btn, lock
    except Exception as exc:
        log.error('GPIO init failed: %s', exc)
        raise


def unlock_door(lock):
    log.info('Unlocking door')
    lock.off()
    time.sleep(UNLOCK_DELAY)
    lock.on()


def recognize_face(cam, model, btn, lock):
    try:
        frame = cam.capture_array()
    except Exception as exc:
        log.error('Frame capture failed: %s', exc)
        return

    if frame is None or frame.size == 0:
        log.warning('Empty frame received')
        return

    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    except cv2.error as exc:
        log.error('Grayscale conversion failed: %s', exc)
        return

    try:
        label, confidence = model.predict(gray)
    except Exception as exc:
        log.error('Face recognition failed: %s', exc)
        return

    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
        log.info('Face recognized (label=%s, conf=%.2f)', label, confidence)
        unlock_door(lock)
    else:
        log.info('Face not recognized (label=%s, conf=%.2f)', label, confidence)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        mixer = init_mixer()
    except Exception:
        sys.exit(1)

    try:
        cam = init_camera()
    except Exception:
        sys.exit(1)

    try:
        btn, lock = init_hardware()
    except Exception:
        sys.exit(1)

    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
    except Exception as exc:
        log.error('Model load failed: %s', exc)
        sys.exit(1)

    log.info('Running. Press button to trigger face recognition.')
    _running.set()

    try:
        while _running.is_set():
            if btn.is_pressed:
                recognize_face(cam, model, btn, lock)
            time.sleep(0.1)
    except Exception as exc:
        log.error('Runtime error: %s', exc)
    finally:
        try:
            cam.stop()
        except Exception:
            pass
        try:
            cam.close()
        except Exception:
            pass
        try:
            btn.close()
        except Exception:
            pass
        try:
            lock.close()
        except Exception:
            pass
        try:
            pygame.mixer.quit()
        except Exception:
            pass
        log.info('Cleanup complete.')


if __name__ == '__main__':
    main()

