import cv2
import signal
import sys
import numpy as np
from picamera2 import Picamera2

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)

def main():
    global running

    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        print(f"Error: Failed to load cascade classifier from {cascade_path}", file=sys.stderr)
        sys.exit(1)

    picam2 = Picamera2()
    try:
        config = picam2.create_preview_configuration(
            main={"format": 'XRGB8888', "size": (640, 480)}
        )
        picam2.configure(config)
        picam2.start()
    except Exception as e:
        print(f"Error: Failed to initialize camera: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                continue

            # XRGB8888 has an alpha channel; convert to BGR for OpenCV display
            bgr_frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)

            gray = cv2.cvtColor(bgr_frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, scaleFactor=1.3, minNeighbors=5)

            for (x, y, w, h) in faces:
                cv2.rectangle(bgr_frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

            cv2.imshow('Face Detection', bgr_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"Error during capture loop: {e}", file=sys.stderr)
    finally:
        try:
            picam2.stop()
        except Exception:
            pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

