import signal
import sys
import threading
import time
import logging

import smbus2
import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LCD_I2C_ADDR = 0x27
LCD_I2C_BUS = 1
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0b00000100

# PCF8574 bit layout: P7-P4 = LCD backlights (high = on), P3 = RS, P2 = RW, P1 = E, P0 = BL
LCD_EN = 0x04
LCD_RW = 0x02
LCD_RS = 0x01

LED_PINS = [17, 18, 23, 27, 22]

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("lcd_indicator")

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bus = None
running = True
threads = []
leds = {}


def signal_handler(signum, frame):
    global running
    log.info("Signal %s received – shutting down.", signum)
    running = False


def lcd_write_byte(data, mode):
    """Write a byte to the PCF8574 in two half-cycles (E high then low)."""
    high = data & 0xF0
    low = (data << 4) & 0xF0
    for nibble in (high, low):
        # EN high
        bus.write_byte(LCD_I2C_ADDR, nibble | LCD_BACKLIGHT | mode | LCD_EN)
        time.sleep(0.0005)
        # EN low
        bus.write_byte(LCD_I2C_ADDR, nibble | LCD_BACKLIGHT & ~ENABLE)
        time.sleep(0.0005)


def lcd_init():
    """Initialise the PCF8574 LCD in 4-bit mode per HD44780 datasheet."""
    try:
        bus.write_byte(LCD_I2C_ADDR, 0x33)
        bus.write_byte(LCD_I2C_ADDR, 0x32)
        bus.write_byte(LCD_I2C_ADDR, 0x06)
        bus.write_byte(LCD_I2C_ADDR, 0x0C)
        bus.write_byte(LCD_I2C_ADDR, 0x28)
        bus.write_byte(LCD_I2C_ADDR, 0x01)
        time.sleep(0.002)
    except OSError as exc:
        log.error("LCD init failed: %s", exc)
        raise


def lcd_set_cursor(row, col):
    """Move cursor to (row, col) on the 16x2 display."""
    addr = LCD_LINE_1 if row == 0 else LCD_LINE_2
    addr += col
    lcd_write_byte(addr, LCD_CMD)


def lcd_write_string(text):
    """Write a string to the current cursor position."""
    for ch in text.ljust(LCD_WIDTH)[:LCD_WIDTH]:
        lcd_write_byte(ord(ch), LCD_CHR)


def lcd_clear():
    """Clear the LCD display."""
    lcd_write_byte(0x01, LCD_CMD)
    time.sleep(0.002)


def lcd_backlight_off():
    """Turn off the LCD backlight."""
    try:
        bus.write_byte(LCD_I2C_ADDR, LCD_BACKLIGHT & ~LCD_BACKLIGHT)
    except OSError:
        pass


def get_cpu_usage():
    """Return CPU usage percentage via the psutil module."""
    try:
        import psutil
        return psutil.cpu_percent(interval=None)
    except ImportError:
        log.warning("psutil not installed – using 0 %")
        return 0.0
    except Exception as exc:
        log.error("CPU read error: %s", exc)
        return 0.0


def get_cpu_temp():
    """Return CPU temperature in °C via the w1thermsensor module."""
    try:
        import w1thermsensor
        return w1thermsensor.W1ThermSensor.get_temperature()
    except ImportError:
        log.warning("w1thermsensor not installed – using 0 °C")
        return 0.0
    except Exception as exc:
        log.error("Temp read error: %s", exc)
        return 0.0


def led_on(pin):
    GPIO.output(pin, GPIO.HIGH)


def led_off(pin):
    GPIO.output(pin, GPIO.LOW)


def led_toggle(pin):
    GPIO.output(pin, not GPIO.input(pin))


