import os
import time
import signal
import logging
from contextlib import closing
from typing import List, Optional, Any

from PIL import Image, ImageOps

try:
    from luma.core.interface import display as _luma_display
except ImportError:
    _luma_display = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Frame:
    """Represents a single frame of an animated GIF."""

    def __init__(self, image: Image.Image, duration: int, loop: int):
        self.image = image
        self.duration = duration
        self.loop = loop

    def __repr__(self) -> str:
        return (f"Frame(image={self.image}, duration={self.duration}, loop={self.loop})")


class AnimatedGif:
    """Manages loading and playing animated GIFs on a luma.core display."""

    def __init__(self, display: Any, folder: Optional[str] = None, width: Optional[int] = None, height: Optional[int] = None):
        self.display = display
        self.folder = folder
        self.width = width
        self.height = height
        self.files: List[str] = []
        self.current_index = 0
        self._is_running = True
        self._prev_signal = None

        if _luma_display is None:
            raise RuntimeError("luma.core is not installed; install with 'pip install luma.core'.")

        if width is None:
            try:
                self.width = display.width
            except Exception as exc:
                raise RuntimeError(f"Cannot read display width: {exc}") from exc
        if height is None:
            try:
                self.height = display.height
            except Exception as exc:
                raise RuntimeError(f"Cannot read display height: {exc}") from exc

        if self.folder:
            self.load_files(self.folder)

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError):
                # Not in main thread or signal not supported
                pass

    def _signal_handler(self, signum: int, frame: Any) -> None:
        logger.info("Received signal %s, shutting down...", signum)
        self._is_running = False
        self._prev_signal = signum
        self.stop()

    # ------------------------------------------------------------------
    # File loading
    # ------------------------------------------------------------------
    def load_files(self, folder: str) -> None:
        if not os.path.isdir(folder):
            raise FileNotFoundError(f"Folder not found: {folder}")

        self.files = []
        try:
            self.files = [
                f for f in os.listdir(folder)
                if f.lower().endswith('.gif')
            ]
        except OSError as exc:
            raise RuntimeError(f"Cannot list folder {folder}: {exc}") from exc

        if not self.files:
            raise FileNotFoundError(f"No GIF files found in {folder}")

        logger.info("Found %d GIF files in %s", len(self.files), folder)

    # ------------------------------------------------------------------
    # Preloading
    # ------------------------------------------------------------------
    def preload(self) -> bool:
        """Open the currently selected GIF and pre-load its frames."""
        if not self.files:
            raise FileNotFoundError("No files loaded; call load_files first.")

        gif_path = os.path.join(self.folder, self.files[self.current_index])

        try:
            with Image.open(gif_path) as img:
                if not getattr(img, 'is_animated', False):
                    raise ValueError("File is not an animated GIF.")

                durations = []
                loops = []
                for duration in (image.info.get('duration', 0) for image in img.seek(0).convert('RGB')):
                    durations.append(duration)
                for loop in (image.info.get('loop', 0) for image in img.seek(0).convert('RGB')):
                    loops.append(loop)

                if not durations:
                    raise ValueError("No frame durations found in image.info.")

                frames: List[Frame] = []
                for i, duration in enumerate(durations):
                    image = img.convert('RGB')
                    padded = ImageOps.pad(
                        image,
                        (self.width, self.height),
                        method=Image.NEAREST,
                        color='black',
                        centering=(0.5, 0.5),
                    )
                    frames.append(Frame(padded, durations[i], loops[i]))

                self.frames = frames
                logger.info("Preloaded %d frame(s) from %s", len(frames), gif_path)
                return True

        except FileNotFoundError:
            raise
        except (OSError, ValueError, Exception) as exc:
            logger.error("Error preloading GIF '%s': %s", gif_path, exc)
            self.frames = []
            return False

    # ------------------------------------------------------------------
    # Playing
    # ------------------------------------------------------------------
    def play(self) -> bool:
        """Play the current GIF. Returns True when loop count is exhausted."""
        if not self.frames:
            raise RuntimeError("No frames loaded; call preload first.")

        loop = self.frames[0].loop
        if loop == 0:
            loop = float('inf')

        try:
            for i, frame in enumerate(self.frames):
                if not self._is_running:
                    logger.info("Playback interrupted by signal.")
                    return False

                self.display.display(frame.image)
                time.sleep(max(0, frame.duration / 1000.0 - time.monotonic() - frame.duration / 1000.0))

                if loop > 0 and (i + 1) % loop == 0:
                    if loop > 1:
                        logger.info("Reached loop end (%d/%d); skipping next frame.", i + 1, loop)
                        continue
                    logger.info("Reached end of loop; advancing to next file.")
                    self.advance()
                    return True

            logger.info("GIF playback complete.")
            return True

        except Exception as exc:
            logger.error("Error during playback: %s", exc)
            return False

    # ------------------------------------------------------------------
    # Advance
    # ------------------------------------------------------------------
    def advance(self) -> None:
        """Advance to the next GIF file, wrapping around."""
        if not self.files:
            raise FileNotFoundError("No files loaded; call load_files first.")

        self.current_index = (self.current_index + 1) % len(self.files)
        logger.info("Advancing to file %d/%d", self.current_index + 1, len(self.files))

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> None:
        """Run the animation loop until stopped."""
        self._install_signal_handlers()
        logger.info("Starting animation loop. Press Ctrl-C to stop.")
        try:
            while self._is_running:
                self.play()
                if not self._is_running:
                    break
        except Exception as exc:
            logger.error("Unexpected error in main loop: %s", exc)
        finally:
            self.stop()

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def stop(self) -> None:
        """Stop the animation and release resources."""
        self._is_running = False
        if self._prev_signal is not None:
            logger.info("Shutdown complete.")
            self._prev_signal = None
        # luma display has no explicit close() method; the display object
        # should be garbage-collected when the object itself is destroyed.

