        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the LCD address to confirm it is present
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if LCD_I2C_ADDRESS not in devices:
            print(f"Warning: No device found at I2C address 0x{LCD_I2C_ADDRESS:02X}.")
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_lcd(i2c_bus):
    """Initialize the 16x2 I2C LCD."""
    try:
        lcd = character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS)
        lcd.clear()
        return lcd
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        return None


def initialize_dht22():
    """Initialize the DHT22 sensor."""
    try:
        sensor = adafruit_dht.DHT22(DHT22_PIN, use_pulseio=False)
        return sensor
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None


def read_dht22(sensor):
    """Read temperature and humidity from the DHT22 sensor.

    Returns (temperature, humidity) or (None, None) on failure.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 often throws checksum or timing errors; retry on next cycle
        print(f"DHT22 read error (retryable): {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None


def update_lcd(lcd, temperature, humidity):
    """Update the LCD with the given temperature and humidity."""
    if temperature is not None and humidity is not None:
        lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
    else:
        lcd.message = "Sensor read failed\nLCD will show 'Sensor Error'"


def main():
    """Main loop: read sensor and update LCD every 2 seconds."""
    global lcd, dht_sensor

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = initialize_lcd(i2c_bus)
    if lcd is None:
        cleanup()
        sys.exit(1)

    dht_sensor = initialize_dht22()
    if dht_sensor is None:
        cleanup()
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22(dht_sensor)
            update_lcd(lcd, temperature, humidity)
            time.sleep(2)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

