import os
import sys
import time
import signal
import logging
from typing import List, Optional

from PIL import Image, ImageDraw, ImageFont
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

GIF_EXTS = ('.gif', '.jpg', '.jpeg', '.png')

class Frame:
    def __init__(self, image: Image.Image, duration: int, loop: int):
        self.image = image
        self.duration = duration
        self.loop = loop

class AnimatedGifPlayer:
    def __init__(self, i2c_address: int, i2c_port: int, display_width: int, display_height: int, folder: str):
        self.i2c_address = i2c_address
        self.i2c_port = i2c_port
        self.display_width = display_width
        self.display_height = display_height
        self.folder = folder
        self.frames: List[Frame] = []
        self._running = True
        self.device: Optional[ssd1306] = None
        self._init_display()

    def _init_display(self):
        try:
            serial = i2c(port=self.i2c_port, address=self.i2c_address)
            self.device = ssd1306(serial, width=self.display_width, height=self.display_height)
            logger.info(f"SSD1306 display initialized at I2C address 0x{self.i2c_address:02X}")
        except Exception as e:
            logger.error(f"Failed to initialize SSD1306 display: {e}")
            self.device = None
            raise

    def _load_gifs(self) -> List[str]:
        if not os.path.isdir(self.folder):
            logger.warning(f"Folder '{self.folder}' not found. Exiting.")
            return []
        return sorted([f for f in os.listdir(self.folder) if f.lower().endswith(GIF_EXTS)])

    def _process_gif(self, filepath: str) -> Frame:
        try:
            with Image.open(filepath) as img:
                if getattr(img, 'is_animated', False):
                    n_frames = getattr(img, 'n_frames', 1)
                    durations = getattr(img, 'get_exif', lambda: []) or []
                    loop = getattr(img, 'loop', 0)
                else:
                    n_frames, durations, loop = 1, [], 0

                for i in range(n_frames):
                    img.seek(i)
                    w, h = img.size
                    ratio = min(self.display_width / w, self.display_height / h)
                    new_w = int(w * ratio)
                    new_h = int(h * ratio)
                    img = img.resize((new_w, new_h), Image.LANCZOS)
                    padded = Image.new('1', (self.display_width, self.display_height), 0)
                    padded.paste(img, (0, 0))
                    durations.append(getattr(img, 'get_exif', lambda: []) or [0] if i == 0 else durations[-1])
                    return Frame(padded, durations[-1] if loop == 0 else durations[-1] * loop, loop)
        except Exception as e:
            logger.error(f"Error processing GIF '{filepath}': {e}")
            return Frame(Image.new('1', (self.display_width, self.display_height), 0), 0, 0)

    def _run(self):
        if not self.frames:
            logger.warning("No GIF files found in the specified folder. Exiting.")
            return

        loop_count = getattr(self.frames[0], 'loop', 0)
        for i, frame in enumerate(self.frames):
            if not self._running:
                break
            if loop_count > 0 and (i + 1) % loop_count == 0:
                continue
            self._display_frame(frame)
            time.sleep(max(0, frame.duration / 1000.0))

    def _display_frame(self, frame: Frame):
        if self.device is None:
            logger.error("Display not initialized. Cannot render frame.")
            return
        try:
            with canvas(self.device) as draw:
                draw.rectangle((0, 0, self.display_width, self.display_height), outline=0, fill=0)
                frame.image.show(draw)
        except Exception as e:
            logger.error(f"Error displaying frame: {e}")

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received. Shutting down...")
        self._running = False

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        try:
            gifs = self._load_gifs()
            if not gifs:
                logger.warning("No GIF files found. Exiting.")
                return
            for gif in gifs:
                logger.info(f"Loading GIF: {gif}")
                frame = self._process_gif(os.path.join(self.folder, gif))
                self.frames.append(frame)
            self._run()
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.device is not None:
            try:
                self.device.cleanup()
            except Exception:
                pass
            self.device = None
        logger.info("Cleanup complete.")

if __name__ == '__main__':
    player = AnimatedGifPlayer(i2c_address=0x3C, i2c_port=1, display_width=128, display_height=64, folder='.')
    player.run()

