import signal
import sys
import time
from math import atan2, degrees, hypot

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

# --- Configuration ---
LEFT_MOTOR_PIN_1 = 12
LEFT_MOTOR_PIN_2 = 13
RIGHT_MOTOR_PIN_1 = 18
RIGHT_MOTOR_PIN_2 = 19

BALL = (180, -200)
CAR_FRONT = (180, -15)
CAR_BACK = (200, -15)
GOAL = (0, 200)
EXTENSION = 50

# --- Globals for cleanup ---
left_motor_1 = None
left_motor_2 = None
right_motor_1 = None
right_motor_2 = None
running = True


def signal_handler(sig, frame):
    global running
    running = False


def clamp(value, min_val, max_val):
    return max(min_val, min(value, max_val))


def calculate_distance(x1, y1, x2, y2):
    try:
        return hypot(x2 - x1, y2 - y1)
    except TypeError:
        print("Error: Invalid coordinate type in distance calculation.")
        return 0.0


def calculate_angle(x1, y1, x2, y2, x3, y3):
    try:
        angle1 = degrees(atan2(y2 - y1, x2 - x1))
        angle2 = degrees(atan2(y3 - y2, x3 - x2))
        return angle1 - angle2
    except Exception as e:
        print(f"Error calculating angle: {e}")
        return 0.0


def calculate_image_point(ball_x, ball_y, goal_x, goal_y, extension):
    try:
        dist_bg = calculate_distance(ball_x, ball_y, goal_x, goal_y)
        if dist_bg == 0:
            return ball_x, ball_y
        scale = extension / dist_bg
        img_x = int(ball_x + (goal_x - ball_x) * scale)
        img_y = int(ball_y + (goal_y - ball_y) * scale)
        return img_x, img_y
    except Exception as e:
        print(f"Error calculating image point: {e}")
        return ball_x, ball_y


def calculate_car_heading(car_front_x, car_front_y, car_back_x, car_back_y, target_x, target_y):
    try:
        car_front_to_target = calculate_distance(car_front_x, car_front_y, target_x, target_y)
        car_back_to_target = calculate_distance(car_back_x, car_back_y, target_x, target_y)
        if car_front_to_target == 0 or car_back_to_target == 0:
            return 0.0
        angle = calculate_angle(car_front_x, car_front_y, car_back_x, car_back_y, target_x, target_y)
        return angle
    except Exception as e:
        print(f"Error calculating car heading: {e}")
        return 0.0


def calculate_car_angle(car_front_x, car_front_y, car_back_x, car_back_y):
    try:
        car_to_back = calculate_distance(car_front_x, car_front_y, car_back_x, car_back_y)
        if car_to_back == 0:
            return 0.0
        angle = degrees(atan2(car_back_y - car_front_y, car_back_x - car_front_x))
        return angle
    except Exception as e:
        print(f"Error calculating car angle: {e}")
        return 0.0


def calculate_car_direction(car_front_x, car_front_y, car_back_x, car_back_y, heading):
    try:
        car_to_back = calculate_distance(car_front_x, car_front_y, car_back_x, car_back_y)
        if car_to_back == 0:
            return 0.0
        back_x = car_back_x - car_front_x
        back_y = car_back_y - car_front_y
        front_x = car_front_x + 10 * cos(radians(heading))
        front_y = car_front_y + 10 * sin(radians(heading))
        front_to_back = calculate_distance(front_x, front_y, car_back_x, car_back_y)
