import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

PROXIMITY_SENSOR_I2C_ADDRESS = 0x20
PROXIMITY_SENSOR_COUNT = 8
POLL_INTERVAL_S = 0.1
RETRY_DELAY_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_port(bus, port):
    """Write a single byte to the PCF8574 port register."""
    msg = i2c_msg.write(PROXIMITY_SENSOR_I2C_ADDRESS, [port])
    bus.i2c_rdwr(msg)


def _read_port(bus):
    """Read a single byte from the PCF8574 port register."""
    write_msg = i2c_msg.write(PROXIMITY_SENSOR_I2C_ADDRESS, [0x00])
    read_msg = i2c_msg.read(PROXIMITY_SENSOR_I2C_ADDRESS, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def initialize_proximity_sensors(bus):
    """Configure the PCF8574 as an 8-input, 8-output I2C expander with pull-ups."""
    _write_port(bus, 0xFF)  # P0-P7 inputs, pull-up enabled
    return _read_port(bus)


def read_proximity_sensors(bus, port):
    """Return a list of boolean flags for each proximity sensor (True = obstacle)."""
    return [bit == 0 for bit in port]


def print_proximity_status(sensor_flags):
    """Print obstacle status for each sensor."""
    for idx, flag in enumerate(sensor_flags):
        if flag:
            print(f"Obstacle detected by sensor {idx}")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        port = initialize_proximity_sensors(bus)
        print("Proximity sensors initialized. Polling every 100 ms. Press Ctrl-C to exit.")

        while _running:
            try:
                flags = read_proximity_sensors(bus, port)
                print_proximity_status(flags)
            except OSError as e:
                print(f"I2C bus error: {e}")
                time.sleep(RETRY_DELAY_S)
            except Exception as e:
                print(f"Unexpected error: {e}")
                time.sleep(RETRY_DELAY_S)

            time.sleep(POLL_INTERVAL_S)

    except OSError as e:
        print(f"Failed to open I2C bus: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Initialization error: {e}")
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

