import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x38
DHT20_I2C_BUS = 1
POWER_STABILIZATION_DELAY = 0.5
MEASUREMENT_DELAY = 0.1
MAX_MEASUREMENT_RETRIES = 5
RETRY_DELAY = 2.0


class DHT20:
    def __init__(self, i2c_bus=DHT20_I2C_BUS, i2c_address=DHT20_I2C_ADDRESS):
        self.i2c_address = i2c_address
        self._bus = None
        try:
            self._bus = smbus2.SMBus(i2c_bus)
        except Exception as e:
            logging.error(f"Failed to open I2C bus {i2c_bus}: {e}")
            raise
        time.sleep(POWER_STABILIZATION_DELAY)
        try:
            status = self._read_register(0x71, 1)[0]
            if (status & 0x18) != 0x18:
                self.close()
                raise RuntimeError(f"DHT20 status check failed: 0x{status:02X}")
        except Exception as e:
            logging.error(f"DHT20 not detected at address 0x{i2c_address:02X}: {e}")
            self.close()
            raise

    def get_temperature_and_humidity(self):
        for attempt in range(1, MAX_MEASUREMENT_RETRIES + 1):
            try:
                temperature, humidity, crc_error = self._measure_with_crc_check()
                if crc_error:
                    logging.warning(f"CRC error on attempt {attempt}/{MAX_MEASUREMENT_RETRIES}")
                else:
                    logging.info(f"Temperature = {temperature:.2f} °C, Humidity = {humidity:.2f} %")
                    return temperature, humidity, False
            except Exception as e:
                logging.error(f"Measurement attempt {attempt}/{MAX_MEASUREMENT_RETRIES} failed: {e}")
            if attempt < MAX_MEASUREMENT_RETRIES:
                time.sleep(RETRY_DELAY)
        logging.error("Failed to measure temperature and humidity after multiple retries.")
        return None, None, True

    def _read_register(self, register, length):
        try:
            return self._bus.read_i2c_block_data(self.i2c_address, register, length)
        except Exception as e:
            logging.error(f"I2C read error at register 0x{register:02X}: {e}")
            raise

    def _write_register(self, register, value):
        try:
            self._bus.write_byte_data(self.i2c_address, register, value)
        except Exception as e:
            logging.error(f"I2C write error at register 0x{register:02X}: {e}")
            raise

    def _measure_with_crc_check(self):
        try:
            self._write_register(0xAC, [0x33, 0x00])
        except Exception:
            return None, None, True

        start_time = time.time()
        while True:
            time.sleep(MEASUREMENT_DELAY)
            status = self._read_register(0x71, 1)[0]
            if (status & 0x80) == 0:
                break
            if time.time() - start_time > 0.1:
                logging.warning("Measurement timeout waiting for bit 7 to clear.")
                return None, None, True

        data = self._read_register(0x71, 7)
        if len(data) < 7:
            logging.error("Incomplete data read from sensor.")
            return None, None, True

        raw_humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        raw_temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        temperature = raw_temperature / 5242.88 - 50.0
        humidity = raw_humidity / 1048576.0 * 100.0

        crc_calc = 0xFF
        for b in data[:6]:
            crc_calc ^= b
            for _ in range(8):
                if crc_calc & 0x80:
                    crc_calc = ((crc_calc << 1) ^ 0x31) & 0xFF
                else:
                    crc_calc = (crc_calc << 1) & 0xFF
        if crc_calc != data[6]:
            return None, None, True

        return temperature, humidity, False

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._bus = None

    def __del__(self):
        self.close()


if __name__ == '__main__':
    sensor = DHT20()
    temp, hum, crc_err = sensor.get_temperature_and_humidity()
    if crc_err:
        print("CRC error detected.")
    else:
        print(f"Temperature: {temp:.2f} °C, Humidity: {hum:.2f} %")

