            logging.error(f"No DHT20 found at address 0x{addr:02X} on bus {bus_num}")
            self.close()
            self.bus = None
            return
        logging.info(f"DHT20 initialized on bus {bus_num} at 0x{addr:02X}")

    def _probe(self):
        try:
            return self.bus.read_byte(DHT20_STATUS_REG) == 0x00
        except Exception as e:
