        except Exception as e:
            logging.error(f"Write measure command failed: {e}")
            return None, None, True
        start = time.monotonic()
        while True:
            try:
                status = self.bus.read_byte_data(self.addr, DHT20_STATUS_REG)
            except Exception as e:
                logging.error(f"Read status failed: {e}")
                return None, None, True
            if (status & 0x80) == 0:
                break
            if time.monotonic() - start > MEASURE_TIMEOUT:
                logging.warning("Measurement timeout")
                return None, None, True
            time.sleep(POLL_INTERVAL)
        try:
            data = self.bus.read_i2c_block_data(self.addr, DHT20_STATUS_REG, 7)
        except Exception as e:
            logging.error(f"Read measurement data failed: {e}")
            return None, None, True
        if len(data) < 7:
            logging.error("Incomplete data read")
            return None, None, True
        crc_error = self._crc8(data[:6]) != data[6]
