import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 50
TEMP_PATH = "/sys/class/thermal/thermal_zone0/temp"
INTERVAL = 1.0

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    try:
        with open(TEMP_PATH, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= 40:
        return 0.0
    if temp >= 50:
        return 100.0
    return (temp - 40) * 10.0

def main():
    signal.signal(signal.SIGTERM, handle_signal)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                fan.value = duty / 100.0
                print(f"CPU Temp: {temp:.1f}°C  Fan Duty: {duty:.1f}%")
            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        fan.value = 0.0
        fan.close()
        print("Fan control stopped and GPIO released.")

if __name__ == "__main__":
    main()

