import serial
import csv
import sys
import signal
from datetime import datetime

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = 'temperature_log.csv'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def open_serial_port():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0
        )
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

def ensure_csv_header(filename):
    try:
        with open(filename, 'x', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['timestamp', 'celsius', 'fahrenheit'])
    except FileExistsError:
        pass
    except OSError as e:
        print(f"Error creating CSV file: {e}", file=sys.stderr)
        sys.exit(1)

def read_temperature_line(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    line = raw.decode('ascii', errors='replace').strip()
    return line if line else None

def convert_to_fahrenheit(celsius):
    try:
        return float(celsius) * 9.0 / 5.0 + 32.0
    except ValueError:
        print(f"Invalid temperature value: {celsius}", file=sys.stderr)
        return None

def log_temperature(filename, celsius, fahrenheit):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(filename, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow([timestamp, celsius, fahrenheit])
    except OSError as e:
        print(f"Error writing to CSV file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = open_serial_port()
    ensure_csv_header(LOG_FILE)

    print(f"Logging temperature data from {SERIAL_PORT} to {LOG_FILE}...")

    try:
        while running:
            line = read_temperature_line(ser)
            if line:
                fahrenheit = convert_to_fahrenheit(line)
                if fahrenheit is not None:
                    log_temperature(LOG_FILE, line, fahrenheit)
            if not running:
                break
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == '__main__':
    main()

