import time
import signal
import sys
import board
import busio
import adafruit_bme680

LOG_FILE = 'air_quality_log.txt'
DELAY_SECONDS = 10
I2C_ADDR = 0x77

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_sensor(i2c_bus):
    try:
        sensor = adafruit_bme680.Adafruit_BME680_I2C(i2c_bus, address=I2C_ADDR)
        return sensor
    except ValueError as e:
        print(f"Sensor not found at address 0x{I2C_ADDR:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BME680 sensor: {e}")
        return None

def read_sensor_data(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        gas = sensor.gas
        return temperature, humidity, pressure, gas
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None, None

def log_data(log_file, temperature, humidity, pressure, gas):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp},{temperature},{humidity},{pressure},{gas}\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def display_data(temperature, humidity, pressure, gas):
    print(f"Temperature: {temperature:.2f} C")
    print(f"Humidity: {humidity:.2f} %")
    print(f"Pressure: {pressure:.2f} hPa")
    print(f"Gas: {gas:.2f} ohms")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        sys.exit(1)

    try:
        while _running:
            temperature, humidity, pressure, gas = read_sensor_data(sensor)
            if temperature is not None:
                log_data(LOG_FILE, temperature, humidity, pressure, gas)
                display_data(temperature, humidity, pressure, gas)
            time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

