import signal
import sys
import time
import serial
import adafruit_dht
from board import D4

SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600
READ_INTERVAL = 1.0
DHT_PIN = D4

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO4: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        dht_device.exit()
        sys.exit(1)

    try:
        while running:
            try:
                temperature = dht_device.temperature
            except RuntimeError as e:
                print(f"DHT22 read error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
            else:
                if temperature is not None:
                    temperature_str = f"Temperature: {temperature:.2f}C\n"
                    try:
                        serial_port.write(temperature_str.encode("utf-8"))
                        serial_port.flush()
                        print(f"Transmitted: {temperature_str.strip()}")
                    except serial.SerialException as e:
                        print(f"UART write error: {e}", file=sys.stderr)
                else:
                    print("DHT22 returned None for temperature.", file=sys.stderr)

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        try:
            serial_port.close()
        except Exception:
            pass
        try:
            dht_device.exit()
        except Exception:
            pass
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

