import signal
import sys
import time
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5
TEMP_THRESHOLDS = [70, 60, 50, 40, 32, 25]
FAN_SPEEDS = [100, 85, 70, 50, 25, 15, 0]


class FanController:
    def __init__(self, fan_pin, pwm_frequency, check_interval):
        self.fan_pin = fan_pin
        self.pwm_frequency = pwm_frequency
        self.check_interval = check_interval
        self.fan = None
        self._running = True

    def _read_cpu_temp(self):
        try:
            with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                return float(f.read().strip()) / 1000.0
        except (FileNotFoundError, PermissionError, ValueError, OSError) as e:
            logging.error("Failed to read CPU temperature: %s", e)
            return None

    def _set_fan_speed(self, temp):
        for threshold, speed in zip(TEMP_THRESHOLDS, FAN_SPEEDS):
            if temp > threshold:
                self.fan.value = speed / 100.0
                logging.info("Temp %.1f°C -> fan %.0f%%", temp, speed)
                return
        self.fan.value = 0
        logging.info("Temp %.1f°C -> fan 0%%", temp)

    def run(self):
        try:
            self.fan = PWMOutputDevice(self.fan_pin, frequency=self.pwm_frequency, initial_value=0)
            logging.info("Fan controller started on GPIO%d @ %d Hz", self.fan_pin, self.pwm_frequency)
            while self._running:
                temp = self._read_cpu_temp()
                if temp is not None:
                    self._set_fan_speed(temp)
                time.sleep(self.check_interval)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received, shutting down...")
        except Exception as e:
            logging.error("Unexpected error: %s", e)
        finally:
            self._cleanup()

    def _cleanup(self):
        if self.fan is not None:
            try:
                self.fan.value = 0
                self.fan.close()
                logging.info("GPIO released.")
            except Exception as e:
                logging.error("Error during cleanup: %s", e)

    def stop(self, signum=None, frame=None):
        logging.info("Signal %s received, stopping...", signum)
        self._running = False


def main():
    controller = FanController(FAN_PIN, PWM_FREQ, CHECK_INTERVAL)
    signal.signal(signal.SIGTERM, controller.stop)
    signal.signal(signal.SIGINT, controller.stop)
    controller.run()


if __name__ == "__main__":
    main()

