import time
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

FAN_PIN = 18
THRESHOLD = 30
NUM_READINGS = 5
DELAY_SECONDS = 2


def read_temp():
    """Simulate a temperature reading between 20 and 40 degrees Celsius."""
    return random.randint(20, 40)


def main():
    # gpiozero uses BCM numbering by default.
    fan = OutputDevice(FAN_PIN, active_high=True, initial_value=False)
    try:
        for i in range(NUM_READINGS):
            temp = read_temp()
            print(f"Reading {i + 1}/{NUM_READINGS}: {temp}°C")

            if temp > THRESHOLD:
                fan.on()
                print("  -> Fan ON")
            else:
                fan.off()
                print("  -> Fan OFF")

            if i < NUM_READINGS - 1:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        fan.close()
        print("GPIO18 released.")


if __name__ == "__main__":
    main()

