import time
import signal
import sys
import board
import adafruit_dht
import requests

# Configuration
DHT_PIN = board.D4
TEMPERATURE_FILE = "temperature.txt"
ERROR_LOG_FILE = "error.log"
THINGSPEAK_CHANNEL_ID = "1234567"
THINGSPEAK_API_KEY = "YOUR_API_KEY"
READ_INTERVAL_SECONDS = 60
DHT_TIMEOUT_SECONDS = 2

# Global state for clean shutdown
_running = True
_sensor = None
_error_log = None

def log_error(message):
    """Append a timestamped error message to the error log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)

def send_to_thingspeak(temperature):
    """Send temperature to ThingSpeak via REST API."""
    try:
        data = {"field1": temperature}
        response = requests.post(
            f"https://api.thingspeak.com/update",
            json=data,
            timeout=10
        )
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        log_error(f"Error sending data to ThingSpeak: {e}")

def read_temperature():
    """Read temperature from DHT22 with timeout; return float or None on failure."""
    try:
        temperature = _sensor.temperature
        if temperature is None:
            return None
        return float(temperature)
    except RuntimeError as e:
        # DHT22 checksum or timing errors are common; retry on next cycle
        return None
    except Exception as e:
        log_error(f"Unexpected error reading temperature: {e}")
        return None

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global _running, _sensor, _error_log
    _running = False
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
    if _error_log is not None:
        try:
            _error_log.close()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)

def main():
    global _sensor, _error_log

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT22 sensor
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        log_error(f"Failed to initialize DHT22 sensor: {e}")
        print("Failed to initialize DHT22 sensor. Check wiring and pull-up resistors.", file=sys.stderr)
        sys.exit(1)

    # Initialize error log file
    try:
        _error_log = open(ERROR_LOG_FILE, "a")
    except Exception as e:
        log_error(f"Failed to open error log file: {e}")
        print("Failed to open error log file. Check permissions.", file=sys.stderr)
        cleanup()

    print("Starting temperature monitoring. Press Ctrl+C to stop.")

    while _running:
        temperature = read_temperature()

        if temperature is not None:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            try:
                with open(TEMPERATURE_FILE, "a") as f:
                    f.write(f"{timestamp}, Temperature: {temperature:.2f} C\n")
            except Exception as e:
                log_error(f"Failed to write to temperature file: {e}")

            send_to_thingspeak(temperature)
            print(f"Temperature: {temperature:.2f} C")
        else:
            log_error("Failed to read temperature (sensor error or timeout).")

        # Wait for next reading interval, but allow early exit on signal
        for _ in range(READ_INTERVAL_SECONDS):
            if not _running:
                break
            time.sleep(1)

    cleanup()

if __name__ == "__main__":
    main()

