import time
import board
import adafruit_dht

# DHT11 data pin connected to physical pin 7 (GPIO4 / board.D4).
# The library uses board.D4 for the data line.
DATA_PIN = board.D4
READ_INTERVAL_SECONDS = 5


def main() -> None:
    # Initialize the DHT11 sensor on the specified pin.
    # adafruit_dht.DHT11 uses a single-wire protocol; it can be initialized
    # with a given pin object.
    try:
        sensor = adafruit_dht.DHT11(DATA_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT11 on {DATA_PIN}: {exc}")
        raise SystemExit(1)

    print("DHT11 temperature monitor started. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                temperature_c = sensor.temperature
                if temperature_c is None:
                    print("Sensor returned None for temperature.")
                else:
                    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                    print(f"[{timestamp}] Temperature: {temperature_c:.1f} °C")
            except RuntimeError as exc:
                # DHT11 checksum or timing errors are common; log and continue.
                print(f"Sensor read error: {exc}")
            except Exception as exc:
                # Catch-all for unexpected I/O or library errors so the loop
                # never crashes silently.
                print(f"Unexpected error during read: {exc}")

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        # Release the sensor resource cleanly on every exit path.
        try:
            sensor.exit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

