#!/usr/bin/env python3
"""
Raspberry Pi UPS Plus HAT Monitor

Reads voltage, current, and power from the UPS Plus HAT's battery and Raspberry Pi
via the INA219 sensors, and reads all 256 registers from the UPS Plus controller
(big-endian multi-byte fields).

Wiring:
  - UPS Plus HAT SDA -> GPIO2 (I2C bus 1 SDA)
  - UPS Plus HAT SCL -> GPIO3 (I2C bus 1 SCL)
  - Raspberry Pi 3.3V -> UPS Plus HAT VCC
  - Raspberry Pi GND -> UPS Plus HAT GND

Dependencies:
  pip install ina219 smbus2
"""

import signal
import sys
import time

from ina219 import INA219, DeviceRangeError

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)


class UPSPlus:
    """Driver for the Raspberry Pi UPS Plus HAT."""

    def __init__(self, bus=1, address=0x17, shunt_resistance=0.00725):
        self.bus = bus
        self.address = address
        self.shunt_resistance = shunt_resistance
        self.bus = None
        self._running = True
        self._init_bus()
        self._init_device()

    def _init_bus(self):
        try:
            self.bus = SMBus(self.bus)
        except OSError as e:
            raise RuntimeError(f"Failed to open I2C bus {self.bus}: {e}") from e

    def _init_device(self):
        try:
            # Verify device presence by reading the power state register (0x17).
            self.bus.write_byte(self.address, 0x17)
        except OSError as e:
            raise RuntimeError(
                f"No device acknowledged at address 0x{self.address:02X} on bus {self.bus}: {e}"
            ) from e

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _read_register(self, register, length=1):
        """Read `length` bytes from `register` with error handling."""
        try:
            write_msg = i2c_msg.write(self.address, [register])
            read_msg = i2c_msg.read(self.address, length)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)
        except OSError as e:
            raise RuntimeError(
                f"I2C read error at register 0x{register:02X}: {e}"
            ) from e

    def _write_register(self, register, value):
        """Write a single byte `value` to `register` with error handling."""
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise RuntimeError(
                f"I2C write error at register 0x{register:02X}: {e}"
            ) from e

    def read_all_registers(self):
        """Read all 256 registers (0x00-0xFF) and return them as a list."""
        return [self.bus.read_byte_data(self.address, reg) for reg in range(256)]

    def get_register_value(self, register):
        """Read a single byte from `register`."""
        return self.bus.read_byte_data(self.address, register)

    def get_register_block(self, register, length):
        """Read `length` bytes starting at `register`."""
        return self.bus.read_i2c_block_data(self.address, register, length)

    def get_register_value_list(self, register, length):
        """Read `length` bytes starting at `register` and return as a list."""
