import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

FAN_PIN = 14
PWM_FREQ = 100
POLL_INTERVAL = 5
TEMP_THRESHOLDS = [70, 60, 50, 40, 32, 25]
DUTY_RATIOS = [100, 85, 70, 50, 25, 15, 0]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_cpu_temperature():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True, text=True, timeout=5, check=True
        )
        return float(result.stdout.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired) as e:
        logging.error(f"Failed to read CPU temperature: {e}")
        return None

def calculate_fan_speed(temperature):
    for threshold, duty in zip(TEMP_THRESHOLDS, DUTY_RATIOS):
        if temperature > threshold:
            return duty
    return DUTY_RATIOS[-1]

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
        last_speed = 0

        while _running:
            temp = get_cpu_temperature()
            if temp is not None:
                speed = calculate_fan_speed(temp)
                if speed != last_speed:
                    fan.value = speed / 100.0
                    last_speed = speed
                    logging.info(f"CPU Temp: {temp:.1f}C -> Fan Speed: {speed}%")
            else:
                logging.warning("Temperature read failed; keeping last fan speed.")
            time.sleep(POLL_INTERVAL)

    except Exception as e:
        logging.error(f"Error during fan control: {e}")
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
                logging.info("Fan stopped and GPIO released.")
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")

if __name__ == "__main__":
    main()

