import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_INTERVAL = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_sensor_data(data_string):
    try:
        temperature, humidity = data_string.split(',')
        temperature = float(temperature)
        humidity = float(humidity)
        return temperature, humidity
    except ValueError:
        print(f"Error: Invalid data format received: {data_string}")
        return None, None
    except Exception as e:
        print(f"Error parsing data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print(f"ALERT: Temperature {temperature:.1f}°C exceeds threshold {TEMP_THRESHOLD}°C")
    if humidity > HUMIDITY_THRESHOLD:
        print(f"ALERT: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud")

        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue

                data_string = raw.decode('ascii', errors='replace').strip()
                if not data_string:
                    continue

                temperature, humidity = parse_sensor_data(data_string)
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error: {e}")
                break

