import time
import signal
import sys
from gpiozero import InputDevice

DOOR_SENSOR_PIN = 22

# gpiozero auto-detects the active level when pull_up is enabled.
# When pull_up is False, active_state must be explicitly set.
door_sensor = None

try:
    # pull_up=True  -> internal pull-up enabled; pin reads HIGH when open.
    # The reed switch wired to GND pulls the pin LOW when the door is closed.
    door_sensor = InputDevice(DOOR_SENSOR_PIN, pull_up=True, active_state=None)
except Exception as e:
    print(f"Failed to initialize GPIO {DOOR_SENSOR_PIN}: {e}", file=sys.stderr)
    sys.exit(1)

def cleanup(signum=None, frame=None):
    """Release the GPIO resource on exit."""
    global door_sensor
    if door_sensor is not None:
        try:
            door_sensor.close()
        except Exception:
            pass
        door_sensor = None
    if signum is not None:
        print("\nExiting gracefully.")
        sys.exit(0)

# Register signal handlers for graceful shutdown
signal.signal(signal.SIGTERM, cleanup)

try:
    while True:
        try:
            # gpiozero InputDevice.is_active returns True when the pin is HIGH.
            # For a normally-closed reed switch wired to GND, LOW means the door is closed.
            if not door_sensor.is_active:
                print("Door Closed")
            else:
                print("Door Open")
        except Exception as e:
            print(f"Error reading sensor: {e}", file=sys.stderr)
        time.sleep(1)
except KeyboardInterrupt:
    print("\nProgram stopped by user.")
except Exception as e:
    print(f"Unexpected error: {e}", file=sys.stderr)
finally:
    cleanup()

