import signal
import sys
import time
from gpiozero import DigitalInputDevice, GPIOZeroError, GPIOZeroWarning
import warnings

# Pin definitions (BCM numbering)
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global list of sensor objects for cleanup
_sensors = []

def cleanup(signum=None, frame=None):
    """Release all GPIO resources on exit."""
    global _sensors
    for sensor in _sensors:
        try:
            sensor.close()
        except Exception:
            pass
    _sensors.clear()
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting gracefully.")
        sys.exit(0)

def main():
    global _sensors

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Suppress non-critical gpiozero warnings but let errors propagate
    warnings.simplefilter('ignore', GPIOZeroWarning)

    try:
        # Initialize all sensor pins with active-high pull-up resistors
        for pin in SENSOR_PINS:
            sensor = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
            _sensors.append(sensor)
        print(f"GPIO pins {SENSOR_PINS} initialized with pull-up resistors. Polling every {POLL_INTERVAL}s.")
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while True:
            for idx, sensor in enumerate(_sensors):
                try:
                    if sensor.is_active:  # HIGH == active (pull-up enabled)
                        print(f"Response for sensor {idx + 1}")
                except GPIOZeroError as e:
                    print(f"Error reading sensor {idx + 1}: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"Unexpected error reading sensor {idx + 1}: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

