import sys
import time
import threading
import signal
import RPi.GPIO as GPIO

# Define GPIO pin for the button (BCM numbering)
BUTTON_PIN = 17

# Define the log file name
LOG_FILE_NAME = "log.txt"

# Global variables
server_running = False
receive_thread = None
log_file_handle = None
last_command_time = 0
help_messages = {
    "help": "Available commands: help, start, stop, display, send, write, exit",
    "start": "Starts the server and logs data to the file. Usage: start <filename>",
    "stop": "Stops the server and the receive thread. Usage: stop",
    "display": "Displays the contents of the log file. Usage: display",
    "send": "Sends data using DOG.send(). Usage: send <data>",
    "write": "Writes data directly to the log file. Usage: write <data>",
    "exit": "Stops the server and exits. Usage: exit"
}

def signal_handler(sig, frame):
    """Handle SIGINT and SIGTERM to ensure clean shutdown."""
    print("\nExiting program...")
    if server_running:
        stop_server()
    GPIO.cleanup()
    sys.exit(0)

def start_server(filename):
    """Starts the server and the receive thread."""
    global server_running, receive_thread, log_file_handle
    if server_running:
        print("Server is already running.")
        return

    try:
        log_file_handle = open(filename, "a")
        server_running = True
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()
        print(f"Server started. Logging to {filename}")
    except IOError as e:
        print(f"Error opening log file: {e}")
        server_running = False
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        server_running = False

def receive_data():
    """Continuously receives data and writes it to the log file."""
    global server_running, log_file_handle
    while server_running:
        try:
            data = DOG.receive()
            if data:
                log_file_handle.write(data + "\n")
                log_file_handle.flush()
        except Exception as e:
            print(f"Error receiving data: {e}")
            server_running = False
            break
        time.sleep(0.1)

def send_data(data):
    """Sends data using DOG.send()."""
    if not server_running:
        print("Server is not running. Please start the server first.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file."""
    if not server_running:
        print("Server is not running. Please start the server first.")
        return
    try:
        log_file_handle.write(data + "\n")
        log_file_handle.flush()
        print(f"Wrote to log: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def display_log():
    """Displays the contents of the log file."""
    if not server_running:
        print("Server is not running. Please start the server first.")
        return
    try:
        with open(LOG_FILE_NAME, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def stop_server():
    """Stops the server and the receive thread."""
    global server_running, receive_thread
    if not server_running:
        return
    server_running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    if log_file_handle:
        try:
            log_file_handle.close()
        except Exception as e:
            print(f"Error closing log file: {e}")
    print("Server stopped.")

def process_command(command):
    """Processes the given command."""
    global last_command_time
    current_time = time.time()
    if current_time - last_command_time < 0.5:
        print("Command too fast. Please wait a moment.")
        return

    try:
        parts = command.split()
        if not parts:
            return

        command_name = parts[0].lower()

        if command_name == "help":
            if len(parts) == 2:
                print(help_messages.get(parts[1], help_messages["help"]))
            else:
                print(help_messages["help"])

        elif command_name == "start":
            if len(parts) == 2:
                start_server(parts[1])
            else:
                print(help_messages["start"])

        elif command_name == "stop":
            stop_server()

        elif command_name == "display":
            display_log()

        elif command_name == "send":
            if len(parts) == 2:
                send_data(parts[1])
            else:
                print(help_messages["send"])

        elif command_name == "write":
            if len(parts) == 2:
                write_to_log(parts[1])
            else:
                print(help_messages["write"])

        elif command_name == "exit":
            stop_server()
            sys.exit(0)

        else:
            print("Unknown command. Try 'help'.")

        last_command_time = current_time

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to handle user input and command execution."""
    global server_running
    server_running = False
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting DOG server...")
    start_server(LOG_FILE_NAME)

    try:
        while True:
            try:
                user_input = input("Enter command: ")
                process_command(user_input)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
    finally:
        stop_server()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

