    if log_file_handle:
        try:
            log_file_handle.close()
        except Exception as e:
            print(f"Error closing log file: {e}")
    print("Server stopped.")

def process_command(command):
    """Processes the given command."""
    global last_command_time
    current_time = time.time()
    if current_time - last_command_time < 0.5:
        print("Command too fast. Please wait a moment.")
        return

    try:
        parts = command.split()
        if not parts:
            return

        command_name = parts[0].lower()

        if command_name == "help":
            if len(parts) == 2:
                print(help_messages.get(parts[1], help_messages["help"]))
            else:
                print(help_messages["help"])

        elif command_name == "start":
            if len(parts) == 2:
                start_server(parts[1])
            else:
                print(help_messages["start"])

        elif command_name == "stop":
            stop_server()

        elif command_name == "display":
            display_log()

        elif command_name == "send":
            if len(parts) == 2:
                send_data(parts[1])
            else:
                print(help_messages["send"])

        elif command_name == "write":
            if len(parts) == 2:
                write_to_log(parts[1])
            else:
                print(help_messages["write"])

        elif command_name == "exit":
            stop_server()
            sys.exit(0)

        else:
            print("Unknown command. Try 'help'.")

        last_command_time = current_time

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to handle user input and command execution."""
    global server_running
    server_running = False
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting DOG server...")
    start_server(LOG_FILE_NAME)

    try:
        while True:
            try:
                user_input = input("Enter command: ")
                process_command(user_input)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
    finally:
        stop_server()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

