import time
import requests
import sys

# Configuration
VOLTAGE_SENSOR_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
ALERT_TIMEOUT = 5  # seconds
POLL_INTERVAL = 1  # seconds

def setup_gpio():
    """Initialize GPIO with BCM numbering and set pin as input with pull-up."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(VOLTAGE_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_voltage_status():
    """Read the voltage status from the sensor pin."""
    return GPIO.input(VOLTAGE_SENSOR_PIN)

def send_alert():
    """Send an HTTP POST alert if power failure is detected."""
    try:
        response = requests.post(
            ALERT_ENDPOINT,
            json={'alert': 'Power failure detected'},
            timeout=ALERT_TIMEOUT
        )
        response.raise_for_status()
        print('Alert sent successfully.')
    except requests.exceptions.Timeout:
        print('Error sending alert: Request timed out.')
    except requests.exceptions.ConnectionError as e:
        print(f'Error sending alert: Connection failed - {e}')
    except requests.exceptions.HTTPError as e:
        print(f'Error sending alert: HTTP error - {e}')
    except requests.exceptions.RequestException as e:
        print(f'Error sending alert: {e}')

def main():
    """Main loop: monitor voltage and send alerts on failure."""
    try:
        setup_gpio()
        print('Monitoring voltage on GPIO 17...')
        while True:
            voltage_status = read_voltage_status()
            if voltage_status == GPIO.LOW:
                print('Power failure detected (GPIO LOW). Sending alert...')
                send_alert()
            else:
                print('Power is good (GPIO HIGH).')
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print('\nExiting program.')
    except Exception as e:
        print(f'Unexpected error: {e}')
        sys.exit(1)
    finally:
        GPIO.cleanup()
        print('GPIO cleanup completed.')

if __name__ == '__main__':
    main()

