import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDRESS = 0x26
RETRY_DELAY = 1  # seconds


def initialize_i2c():
    """Initializes the I2C bus with error handling."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C bus: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing I2C bus: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor with error handling."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, address=I2C_ADDRESS)
        return sensor
    except ValueError as e:
        print(f"Error initializing fingerprint sensor at address 0x{I2C_ADDRESS:02X}: {e}")
        return None
    except RuntimeError as e:
        print(f"Error: Fingerprint sensor not found at address 0x{I2C_ADDRESS:02X}. {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None


def authenticate_user(sensor):
    """Authenticates a fingerprint and returns the match ID and confidence."""
    try:
        print("Place your finger on the sensor...")
        ret = sensor.get_image()
        if ret == adafruit_fingerprint.OK:
            print("Image captured.")
            template = sensor.image_2_tz(1)
            if template == adafruit_fingerprint.OK:
                print("Creating template...")
                ret = sensor.image_2_tz(2)
                if ret == adafruit_fingerprint.OK:
                    print("Template created.")
                    print("Waiting for match...")
                    id_num = sensor.finger_search(template)
                    if id_num == adafruit_fingerprint.OK:
                        print(f"Match found. ID: {id_num}, Confidence: {sensor.finger_confidence}")
                        return id_num, sensor.finger_confidence
                    else:
                        print("No match found.")
                        return None, None
                else:
                    print("Error creating template.")
                    return None, None
            else:
                print("Error creating template.")
                return None, None
        else:
            print(f"Error capturing image: {ret}")
            return None, None
    except Exception as e:
        print(f"Error during authentication: {e}")
        return None, None


def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            id_num, confidence = authenticate_user(sensor)
            if id_num is not None:
                if confidence > 70:
                    print("Access Granted")
                else:
                    print("Access Denied")
            time.sleep(RETRY_DELAY)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")


if __name__ == "__main__":
    main()

