import time
import sys
import pigpio
import board
import busio
import adafruit_tsl2561

# --- Configuration -----------------------------------------------------------
LED_PIN = 18            # GPIO18 (hardware PWM0)
PWM_FREQ = 1000         # Hz
SAMPLE_INTERVAL = 1.0   # seconds
TSL2561_ADDR = 0x39      # default I2C address (ADDR pin tied to GND)

# --- Globals for cleanup -----------------------------------------------------
pi = None
led = None
running = True


def cleanup():
    """Release hardware resources safely."""
    global pi, led
    if led is not None:
        try:
            led.stop()
        except Exception:
            pass
    if pi is not None and pi.connected:
        try:
            pi.stop()
        except Exception:
            pass
    print("Cleanup complete.")


def main():
    global pi, led, running

    # --- Initialize pigpio ---------------------------------------------------
    try:
        pi = pigpio.pi()
        if not pi.connected:
            print("Error: could not connect to pigpio daemon (is pigpiod running?).")
            sys.exit(1)
    except Exception as e:
        print(f"Error initializing pigpio: {e}")
        sys.exit(1)

    # --- Initialize TSL2561 sensor -------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDR)
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
    except Exception as e:
        print(f"Error initializing TSL2561 at 0x{TSL2561_ADDR:02X}: {e}")
        cleanup()
        sys.exit(1)

    # --- Initialize LED PWM --------------------------------------------------
    try:
        led = pi.hardware_PWM(LED_PIN, PWM_FREQ, 0)
    except Exception as e:
        print(f"Error initializing PWM on GPIO{LED_PIN}: {e}")
        cleanup()
        sys.exit(1)

    print("Starting light-to-LED dimmer. Press Ctrl+C to exit.")

    # --- Main loop -----------------------------------------------------------
    while running:
        try:
            lux = sensor.lux
        except Exception as e:
            print(f"Warning: failed to read lux: {e}")
            lux = None

        if lux is not None:
            duty = min(max(lux / 10.0, 0.0), 100.0)
            try:
                led = pi.hardware_PWM(LED_PIN, PWM_FREQ, int(duty * 10000))
            except Exception as e:
                print(f"Warning: failed to set PWM duty cycle: {e}")
        else:
            try:
                led = pi.hardware_PWM(LED_PIN, PWM_FREQ, 0)
            except Exception as e:
                print(f"Warning: failed to reset PWM duty cycle: {e}")

        time.sleep(SAMPLE_INTERVAL)

    cleanup()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

