import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import DeviceClosed, BadPinFactory

DOOR_PIN = 19
SIREN_PIN = 26
BOUNCE_TIME = 0.05
SAMPLE_INTERVAL = 0.4
NUM_SAMPLES = 8

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        door = Button(DOOR_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
        siren = LED(SIREN_PIN)
    except (BadPinFactory, DeviceClosed) as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        siren.off()
        print("Home security system armed. Monitoring door...")
        print("Press Ctrl+C to exit.\n")

        armed = True
        for i in range(NUM_SAMPLES):
            if not _running:
                break

            try:
                if door.is_active:  # True when reed switch is open (HIGH)
                    if armed:
                        siren.on()
                        print(f"ALARM: Door opened at sample {i}!")
                else:
                    siren.off()
            except DeviceClosed:
                print("Error: GPIO device was closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Error reading door sensor: {exc}", file=sys.stderr)
                break

            time.sleep(SAMPLE_INTERVAL)

        if _running:
            print("Monitoring complete.")
        else:
            print("\nInterrupted by user.")
    finally:
        try:
            siren.off()
            siren.close()
        except Exception:
            pass
        try:
            door.close()
        except Exception:
            pass
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

