import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz – standard for 4-wire PWM fans

fan = None
running = True


def cleanup():
    """Stop PWM and release GPIO resources."""
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None


def handle_signal(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def main():
    global fan

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGTERM, handle_signal)
    signal.signal(signal.SIGINT, handle_signal)

    # Initialize PWM output device; fall back to software PWM if hardware is unavailable
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Warning: Could not initialize hardware PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        print("Falling back to software PWM (no hardware PWM available).", file=sys.stderr)
        try:
            from gpiozero import PWMOutputDevice
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
        except (GPIOZeroError, GPIODeviceError) as e2:
            print(f"Error: Could not initialize PWM on GPIO{FAN_PIN}: {e2}", file=sys.stderr)
            sys.exit(1)

    print(f"PWM fan control initialized on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Press 'q' or Ctrl+C to exit.\n")

    while running:
        try:
            user_input = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
        except EOFError:
            break

        if user_input.lower() == 'q':
            break

        if not user_input:
            continue

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input: please enter a number between 0 and 100.")
            continue

        if not 0 <= speed <= 100:
            print("Invalid input: speed must be between 0 and 100.")
            continue

        try:
            fan.value = speed / 100.0
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error setting PWM duty cycle: {e}", file=sys.stderr)
            continue

        print(f"Fan speed set to {speed:.1f}%")

    cleanup()
    print("Fan control stopped.")


if __name__ == "__main__":
    main()

