import signal
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 18
PORT = 8080

led = None
httpd = None


class LEDRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            led.on()
            body = 'LED is ON'
        elif self.path == '/led/off':
            led.off()
            body = 'LED is OFF'
        else:
            body = 'Not Found'
            self.send_response(404)
            self.end_headers()

        self.send_response(200)
        self.send_header('Content-type', 'text/plain')
        self.end_headers()
        self.wfile.write(body.encode('utf-8'))

    def log_message(self, fmt, *args):
        # Suppress default stderr logging; keep stderr for clean shutdown.
        pass


def cleanup(signum=None, frame=None):
    global httpd, led
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global led, httpd

    try:
        led = LED(LED_PIN)
    except GPIOZeroError as exc:
        print(f'Failed to initialize LED on GPIO{LED_PIN}: {exc}', file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f'Unexpected error initializing LED: {exc}', file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        httpd = ThreadingHTTPServer(('0.0.0.0', PORT), LEDRequestHandler)
    except OSError as exc:
        print(f'Failed to bind socket on port {PORT}: {exc}', file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f'Server running on 0.0.0.0:{PORT}  (LED on GPIO{LED_PIN})')
    try:
        httpd.serve_forever()
    except Exception as exc:
        print(f'Web server error: {exc}', file=sys.stderr)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

