import time
import signal
import threading
from gpiozero import Button

CLK_PIN = 17
DT_PIN = 18
DEBOUNCE_TIME = 0.005


class RotaryEncoder:
    """
    A class to handle a rotary encoder connected to a Raspberry Pi using gpiozero.

    Wiring (BCM numbering):
        CLK  -> GPIO17
        DT   -> GPIO18
        GND  -> encoder common
        VCC  -> encoder common (3V3 or 5V, depending on encoder)

    The internal pull-up resistors are enabled by default in gpiozero Button.
    """

    def __init__(self, clk_pin=CLK_PIN, dt_pin=DT_PIN, callback=None):
        if not callable(callback):
            raise TypeError("callback must be callable")
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self._lock = threading.Lock()
        self._counter = 0
        self._last_clk_state = None
        self._encoder_thread = None
        self._running = False

        try:
            self.clk = Button(clk_pin, pull_up=True, bounce_time=DEBOUNCE_TIME)
            self.dt = Button(dt_pin, pull_up=True, bounce_time=DEBOUNCE_TIME)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize GPIO pins {clk_pin}/{dt_pin}: {e}") from e

        self._last_clk_state = self.clk.is_active
        self._running = True
        self._encoder_thread = threading.Thread(target=self._encoder_loop, daemon=True)
        self._encoder_thread.start()

    def _encoder_loop(self):
        while self._running:
            try:
                current_clk_state = self.clk.is_active
                if current_clk_state != self._last_clk_state:
                    with self._lock:
                        if current_clk_state:
                            self._last_clk_state = True
                            if self._last_clk_state != self._last_clk_state:
                                self._counter += 1
                        else:
                            self._last_clk_state = False
                            if self._last_clk_state != self._last_clk_state:
                                self._counter -= 1
                    if self.callback:
                        try:
                            self.callback(self._counter)
                        except Exception as e:
                            print(f"Callback exception: {e}")
            except Exception as e:
                print(f"Encoder loop error: {e}")
                self._running = False
                break
            time.sleep(0.001)

    def get_position(self):
        with self._lock:
            return self._counter

    def cleanup(self):
        self._running = False
        if self._encoder_thread and self._encoder_thread.is_alive():
            self._encoder_thread.join(timeout=0.5)
        for pin in (self.clk, self.dt):
            try:
                pin.close()
            except Exception:
                pass


def main():
    encoder = None
    try:
        encoder = RotaryEncoder()
        print("Rotary encoder initialized. Rotating the knob (Ctrl+C to exit).")
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        if encoder:
            encoder.cleanup()


if __name__ == "__main__":
    main()

