import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0

def main():
    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected failure initializing GPIO{LED_PIN}: {e}")
        sys.exit(1)

    print(f"Blinking LED on GPIO{LED_PIN} (1s on, 1s off). Press Ctrl+C to stop.")

    try:
        while True:
            led.on()
            time.sleep(ON_DURATION)
            led.off()
            time.sleep(OFF_DURATION)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"Error during blink loop: {e}")
    finally:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    try:
        # Test for Raspberry Pi platform
        if sys.platform != 'linux' and sys.platform != 'arm':
            print("Warning: This script requires a Raspberry Pi or compatible system with GPIO support.")
    except Exception:
        pass
    main()

