#!/usr/bin/env python3
"""
3-bit binary counter controlled by Pimoroni Rainbow HAT touchpads.

Touchpad A (GPIO5)  -> MSB (bit 2, value 4)
Touchpad B (GPIO6)  -> bit 1 (value 2)
Touchpad C (GPIO12) -> LSB (bit 0, value 1)

LEDs: green (GPIO7), blue (GPIO8)
Display: HT16K33 14-seg alphanumeric at I2C 0x70
APA102 strip: GPIO10 data, GPIO11 clock
Buzzer: piezo on GPIO13 (MIDI note 60 + decimal value)
"""

import signal
import sys
import time

import board
import busio
import digitalio

try:
    import adafruit_ht16k33.segments
    _HAS_HT16K33 = True
except Exception:
    _HAS_HT16K33 = False

try:
    import adafruit_dotstar
    _HAS_DOTSTAR = True
except Exception:
    _HAS_DOTSTAR = False

try:
    from adafruit_apa102 import APA102
    _HAS_APA102 = True
except Exception:
    _HAS_APA102 = False

try:
    from gpiozero import Button, LED, Buzzer
    _HAS_GPIOZERO = True
except Exception:
    _HAS_GPIOZERO = False

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}
LED_PINS = {"red": 12, "green": 7, "blue": 8}
I2C_ADDR = 0x70
MIDI_BASE = 60
DIM_WHITE = 0x101000
ALL_WHITE = 0x7F0000
COLOR_MASK = 0x1F

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bit_states = [False, False, False]
_running = True
_i2c = None
_display = None
_leds = {}
_strip = None
_buzzer = None


def _cleanup():
    """Turn off all outputs and release hardware resources."""
    global _running
    _running = False
    for led in list(_leds.values()):
        try:
            led.off()
        except Exception:
            pass
    if _buzzer is not None:
        try:
            _buzzer.off()
        except Exception:
            pass
    if _strip is not None:
        try:
            _strip.fill(0)
            _strip.show()
        except Exception:
            pass
    if _display is not None:
        try:
            _display.fill(0)
            _display.show()
        except Exception:
            pass
    print("Cleanup complete.")


def _signal_handler(signum, frame):
    print(f"\nSignal {signum} received, exiting...", file=sys.stderr)
    _cleanup()
    sys.exit(0)


def _set_leds():
    """Drive discrete LEDs from bit states."""
    for name, led in _leds.items():
        try:
            if bit_states[0] and bit_states[1] and bit_states[2]:
                led.on()
            else:
                led.off()
        except Exception as e:
            print(f"Error setting LED '{name}': {e}", file=sys.stderr)


def _display_value(value):
    """Display decimal value 0-7 on the HT16K33 display."""
    if not _HAS_HT16K33:
        return
    try:
        _display.fill(0)
        _display.print_int(value)
        _display.show()
    except Exception as e:
        print(f"Error displaying value {value}: {e}", file=sys.stderr)


def _apa102_update(value):
    """Update APA102 strip based on bit states and value."""
    if not _HAS_APA102:
        return
    try:
        if value == 0:
            _strip.fill(DIM_WHITE)
        elif value == 7:
            _strip.fill(ALL_WHITE)
        else:
            red = COLOR_MASK if bit_states[0] else 0
            green = COLOR_MASK if bit_states[1] else 0
            blue = COLOR_MASK if bit_states[2] else 0
            _strip.fill((red, green, blue))
    except Exception as e:
        print(f"Error updating APA102: {e}", file=sys.stderr)


def _buzzer_update(value):
    """Play a tone on the piezo buzzer at MIDI note 60 + value."""
    if not _HAS_GPIOZERO or _buzzer is None:
        return
    try:
        midi_note = MIDI_BASE + value
        _buzzer.play(midi_note)
    except Exception as e:
        print(f"Error playing buzzer: {e}", file=sys.stderr)


def _handle_touch(channel):
    """Toggle the bit for the touched pad and update all outputs."""
    global bit_states
    try:
        bit_states[channel] = not bit_states[channel]
    except Exception as e:
        print(f"Error toggling bit {channel}: {e}", file=sys.stderr)
        return

    _set_leds()
    value = sum(bit_states)
    _display_value(value)
    _apa102_update(value)
    _buzzer_update(value)
    time.sleep(0.5)


def main():
    global _i2c, _display, _leds, _strip, _buzzer

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- I2C / display -----------------------------------------------------
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
        if not _HAS_HT16K33:
            print("adafruit_ht16k33 not available; display disabled.", file=sys.stderr)
            _display = None
        else:
            _display = adafruit_ht16k33.segments(_i2c, addr=I2C_ADDR)
            _display.brightness = 0.5
            _display.fill(0)
            _display.show()
    except Exception as e:
        print(f"Error initializing display: {e}", file=sys.stderr)
        _display = None

    # --- LEDs --------------------------------------------------------------
    for name, pin in LED_PINS.items():
        try:
            _leds[name] = LED(pin)
        except Exception as e:
            print(f"Error initializing LED '{name}' on GPIO{pin}: {e}", file=sys.stderr)
            _leds[name] = None

    # --- APA102 strip ------------------------------------------------------
    if not _HAS_APA102:
        print("adafruit_apa102 not available; APA102 disabled.", file=sys.stderr)
        _strip = None
    else:
        try:
            _strip = APA102(board.SCK, board.SO)
            _strip.fill(0)
            _strip.show()
        except Exception as e:
            print(f"Error initializing APA102: {e}", file=sys.stderr)
            _strip = None

    # --- Buzzer ------------------------------------------------------------
    if not _HAS_GPIOZERO:
        print("gpiozero not available; buzzer disabled.", file=sys.stderr)
        _buzzer = None
    else:
        try:
            _buzzer = Buzzer(13)
        except Exception as e:
            print(f"Error initializing buzzer on GPIO13: {e}", file=sys.stderr)
            _buzzer = None

    # --- Touchpads --------------------------------------------------------
    for name, pin in TOUCH_PINS.items():
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.05)
            btn.when_pressed = lambda ch=name: _handle_touch(ch)
        except Exception as e:
            print(f"Error initializing touchpad '{name}' on GPIO{pin}: {e}", file=sys.stderr)
            btn = None

    print("Rainbow HAT ready. Press touchpads A/B/C to toggle bits. Ctrl-C to exit.")

    # --- Main loop ---------------------------------------------------------
    try:
        while _running:
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

