import logging
import sys
from collections import deque

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LED_PIN = 18
GRID_SIZE = 5
START_CELL = (0, 0)
DEFECT_CELL = (4, 4)


class Grid:
    """Breadth-first search path planner for a grid of free/obstacle cells."""

    def __init__(self, width: int, height: int):
        if width <= 0 or height <= 0:
            raise ValueError("Grid dimensions must be positive")
        self.width = width
        self.height = height
        self.cells = [[0] * width for _ in range(height)]

    def mark_obstacle(self, row: int, col: int) -> None:
        if 0 <= row < self.height and 0 <= col < self.width:
            self.cells[row][col] = 1

    def is_free(self, row: int, col: int) -> bool:
        if 0 <= row < self.height and 0 <= col < self.width:
            return self.cells[row][col] == 0
        return False

    def neighbors(self, cell: tuple) -> list:
        row, col = cell
        return [
            (row - 1, col),
            (row + 1, col),
            (row, col - 1),
            (row, col + 1),
        ]


def plan_route(grid: Grid, start: tuple, defect: tuple) -> list:
    """Return a shortest path from start to defect using BFS."""
    if not grid.is_free(*start) or not grid.is_free(*defect):
        raise ValueError("Start or defect cell is an obstacle")
    if start == defect:
        return [start]

    frontier = deque([start])
    came_from = {start: None}

    while frontier:
        current = frontier.popleft()
        if current == defect:
            break
        for neighbor in grid.neighbors(current):
            if neighbor not in came_from:
                came_from[neighbor] = current
                frontier.append(neighbor)

    if defect not in came_from:
        raise ValueError("No path found from start to defect")

    # Reconstruct path
    path = []
    cell = defect
    while cell is not None:
        path.append(cell)
        cell = came_from[cell]
    path.reverse()
    return path


def drive_led(led, action: str) -> None:
    """Drive the status LED to indicate success or failure."""
    try:
        if action == "success":
            led.on()
            led.wait(2)
            led.off()
        elif action == "failure":
            led.blink(on_time=0.5, off_time=0.5, n=3, background=False)
        else:
            logging.warning("Unknown LED action: %s", action)
    except Exception as e:
        logging.error("LED control failed: %s", e)
        raise


def main() -> None:
    try:
        from gpiozero import LED
    except Exception as e:
        logging.error("gpiozero not available: %s", e)
        sys.exit(1)

    led = None
    try:
        led = LED(LED_PIN)
        grid = Grid(GRID_SIZE, GRID_SIZE)
        grid.mark_obstacle(*START_CELL)
        grid.mark_obstacle(*DEFECT_CELL)

        path = plan_route(grid, START_CELL, DEFECT_CELL)
        logging.info("Path length: %d", len(path))

        drive_led(led, "success")

    except ValueError as e:
        logging.error("Planning error: %s", e)
        drive_led(led, "failure")
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
        drive_led(led, "failure")
    finally:
        if led is not None:
            led.close()


if __name__ == "__main__":
    main()

