import RPi.GPIO as GPIO
import time
import sys

# BCM pin assignments for the RGB LED (common cathode)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

PWM_FREQ = 200  # Hz

# Preset color tuples (R, G, B)
COLORS = [
    (255, 0, 0),   # Red
    (0, 255, 0),   # Green
    (0, 0, 255),   # Blue
    (255, 255, 0), # Yellow
    (0, 255, 255), # Cyan
]

# Timing constants
HOLD_SEC = 1.0

def setup_gpio():
    """Configure GPIO mode and PWM channels. Returns dict of PWM objects."""
    try:
        GPIO.setmode(GPIO.BCM)
    except Exception as e:
        print(f"ERROR: Failed to set GPIO mode: {e}", file=sys.stderr)
        sys.exit(1)

    pwm_channels = {}
    try:
        for color, pin in (('Red', RED_PIN), ('Green', GREEN_PIN), ('Blue', BLUE_PIN)):
            GPIO.setup(pin, GPIO.OUT)
            pwm = GPIO.PWM(pin, PWM_FREQ)
            pwm.start(0)
            pwm_channels[pin] = pwm
            print(f"  {color} channel started on GPIO{pin} at {PWM_FREQ} Hz")
    except Exception as e:
        print(f"ERROR: Failed to initialize PWM channels: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    return pwm_channels

def set_color(pwm_channels, r, g, b):
    """Set RGB LED color by writing duty cycles to PWM channels."""
    try:
        pwm_channels[RED_PIN].ChangeDutyCycle(r)
        pwm_channels[GREEN_PIN].ChangeDutyCycle(g)
        pwm_channels[BLUE_PIN].ChangeDutyCycle(b)
    except Exception as e:
        print(f"ERROR: Failed to set color (R={r}, G={g}, B={b}): {e}", file=sys.stderr)
        raise

def cleanup(pwm_channels):
    """Stop all PWM channels and release GPIO resources."""
    for pin, pwm in pwm_channels.items():
        try:
            pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    print("GPIO cleanup completed.")

def main():
    pwm_channels = setup_gpio()
    try:
        for color in COLORS:
            print(f"Setting color to {color}")
            set_color(pwm_channels, *color)
            time.sleep(HOLD_SEC)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup(pwm_channels)

if __name__ == "__main__":
    main()

