import time
import atexit
import signal
import sys
import logging
from adafruit_pca9685 import PCA9685
from board import SCL, SDA

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Fuchikoma:
    SERVO_MIN_PULSE = 150
    SERVO_MAX_PULSE = 600
    PWM_FREQUENCY = 60
    DEFAULT_DELAY = 0.029
    PCA9685_ADDRESS = 0x40

    def __init__(self, i2c_address=PCA9685_ADDRESS, pwm_frequency=PWM_FREQUENCY):
        self.pwm = None
        self.servo_positions = {'claw': 0, 'lock': 0, 'water_gun': 0}
        self._initialized = False
        try:
            self.pwm = PCA9685(self.PCA9685_ADDRESS)
            self.pwm.frequency = pwm_frequency
            self._initialized = True
            logger.info(f"PCA9685 initialized at I2C address 0x{self.PCA9685_ADDRESS:02X} with {pwm_frequency} Hz.")
        except (ValueError, OSError) as e:
            logger.error(f"Failed to initialize PCA9685 at 0x{self.PCA9685_ADDRESS:02X}: {e}")
            raise

        atexit.register(self.cleanup)

    def _map_angle_to_pulse(self, angle):
        zero_pulse = (self.SERVO_MIN_PULSE + self.SERVO_MAX_PULSE) / 2
        pulse_width = zero_pulse - self.SERVO_MIN_PULSE if angle < 0 else zero_pulse + (self.SERVO_MAX_PULSE - zero_pulse)
        pulse = int(pulse_width + 0.5)
        return pulse

    def move_servo(self, servo_name, angle, delay=DEFAULT_DELAY):
        if not self._initialized:
            raise RuntimeError("PCA9685 not initialized.")
        if servo_name not in self.servo_positions:
            raise ValueError(f"Invalid servo name: {servo_name}. Valid: {list(self.servo_positions.keys())}")
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range [-77, 77].")

        pulse = self._map_angle_to_pulse(angle)
        channel = self.servo_positions[servo_name]
        try:
            self.pwm.channels[channel].duty_cycle = pulse
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
            self.servo_positions[servo_name] = angle
            logger.debug(f"Moved {servo_name} to {angle} (pulse {pulse}).")
        except Exception as e:
            logger.error(f"Error moving {servo_name}: {e}")
            raise

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if self.pwm:
            try:
                for ch in self.pwm.channels:
                    ch.duty_cycle = 0
                logger.info("PCA9685 channels deinitialized.")
            except Exception as e:
                logger.error(f"Error deinitializing PCA9685: {e}")
        self.pwm = None
        logger.info("Fuchikoma cleaned up.")


def main():
    fuchikoma = None
    try:
        fuchikoma = Fuchikoma()
        fuchikoma.bite()
        fuchikoma.open_claw()
        fuchikoma.lock()
        fuchikoma.shoot()
        fuchikoma.unlock()
        fuchikoma.open_claw()
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if fuchikoma:
            fuchikoma.cleanup()


if __name__ == "__main__":
    main()

