        if not self._initialized:
            raise RuntimeError("PCA9685 not initialized.")
        if servo_name not in self.servo_positions:
            raise ValueError(f"Invalid servo name: {servo_name}. Valid: {list(self.servo_positions.keys())}")
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range [-77, 77].")

        pulse = self._map_angle_to_pulse(angle)
        channel = self.servo_positions[servo_name]
        try:
            self.pwm.channels[channel].duty_cycle = pulse
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
            self.servo_positions[servo_name] = angle
            logger.debug(f"Moved {servo_name} to {angle} (pulse {pulse}).")
        except Exception as e:
            logger.error(f"Error moving {servo_name}: {e}")
            raise

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if self.pwm:
            try:
                for ch in self.pwm.channels:
                    ch.duty_cycle = 0
                logger.info("PCA9685 channels deinitialized.")
            except Exception as e:
                logger.error(f"Error deinitializing PCA9685: {e}")
        self.pwm = None
        logger.info("Fuchikoma cleaned up.")


def main():
    fuchikoma = None
    try:
        fuchikoma = Fuchikoma()
        fuchikoma.bite()
        fuchikoma.open_claw()
        fuchikoma.lock()
        fuchikoma.shoot()
        fuchikoma.unlock()
        fuchikoma.open_claw()
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if fuchikoma:
            fuchikoma.cleanup()


if __name__ == "__main__":
    main()

