import gzip
import threading
import random
import signal
import sys

# Configuration
SENSOR_ADDRESSES = [0x3B, 0x3C, 0x3D]
LOG_FILE_SIZE_LIMIT = 1 * 1024 * 1024  # 1 MB
LOG_FILE_PERMISSIONS = 0o600
ACQUISITION_INTERVAL = 5  # seconds
I2C_BUS = 1

# Global state
log_lock = threading.Lock()
log_files = {}
current_log_file = None
shutdown_event = threading.Event()

# Simulated sensor data
def get_simulated_sensor_data(address):
    """Simulate MCP39F511N sensor readings at the given I2C address."""
    # MCP39F511N registers: REG_POWER, REG_VOLTAGE, REG_CURRENT, REG_FREQUENCY, REG_POWER_FACTOR
    # These registers hold 32-bit values; we simulate 16-bit readings for demonstration
    power = random.randint(50, 200)  # Active power in Watts
    voltage = random.randint(220, 240)  # Voltage in Volts
    current = random.uniform(0.2, 1.0)  # Current in Amperes
    frequency = round(random.uniform(59.5, 60.5), 2)  # Frequency in Hz
    power_factor = round(random.uniform(0.8, 1.0), 3)  # Power factor
    timestamp = datetime.datetime.now().isoformat()
    return {
        'address': address,
        'timestamp': timestamp,
        'active_power': power,
        'voltage': voltage,
        'current': current,
        'frequency': frequency,
        'power_factor': power_factor
    }

def create_log_file():
    """Create a new log file for the current date and time."""
    today = datetime.date.today()
    filename = f"energy_log_{today.strftime('%Y-%m-%d')}.json"
    try:
        with open(filename, 'w') as f:
            f.write("{}")
        log_files[today] = filename
        current_log_file = filename
        print(f"New log file created: {filename}")
    except OSError as e:
        print(f"Error creating log file: {e}")
        raise

def rotate_log_file():
    """Compress the existing log file and create a new one."""
    global current_log_file
    today = datetime.date.today()
    if today not in log_files:
        create_log_file()
        return

    filename = log_files[today]
    try:
        if os.path.exists(filename):
            with open(filename, 'rb') as f_in:
                data = f_in.read()
            with gzip.open(f"{filename}.gz", 'wb') as f_out:
                f_out.write(data)
            os.remove(filename)
            log_files[today] = f"{filename}.gz"
