#!/usr/bin/env python3
"""
Predictive maintenance for urban monitoring using a SW-420 digital vibration sensor.
Sensor: SW-420 (active-low digital output)
Wiring: Sensor VCC -> 3V3, Sensor GND -> GND, Sensor OUT -> GPIO17 (with internal pull-up)
"""

import time
import random
import sys
from gpiozero import DigitalInputDevice
from gpiozero.exc import BadPinFactory, DeviceClosed

# Configuration
VIBRATION_PIN = 17          # BCM GPIO17
SAMPLE_COUNT = 6
SAMPLE_INTERVAL = 0.3       # seconds between readings
THRESHOLD = 7.5             # average amplitude threshold for maintenance


def read_sensor(sensor):
    """Read the SW-420 digital output. Returns True if vibration detected (LOW)."""
    try:
        # Active-low: LOW means vibration detected
        return sensor.value == 0
    except DeviceClosed:
        print("Error: Sensor device closed unexpectedly.")
        return False
    except Exception as e:
        print(f"Error reading sensor: {e}")
        return False


def generate_amplitude(vibration_detected):
    """Simulate amplitude based on sensor state. Higher when vibration detected."""
    if vibration_detected:
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)


def main():
    sensor = None
    try:
        # Initialize sensor with internal pull-up enabled
        sensor = DigitalInputDevice(VIBRATION_PIN, pull_up=True, bounce_time=0.01)
        print(f"Vibration sensor initialized on GPIO{VIBRATION_PIN}")
    except BadPinFactory:
        print("Error: GPIO library not available on this platform.")
        sys.exit(1)
    except Exception as e:
        print(f"Error setting up sensor: {e}")
        sys.exit(1)

    amplitude_sum = 0.0
    healthy_count = 0

    try:
        for i in range(SAMPLE_COUNT):
            vibration_detected = read_sensor(sensor)
            amplitude = generate_amplitude(vibration_detected)
            amplitude_sum += amplitude
            if vibration_detected:
                healthy_count += 1

            print(f"Sample {i+1}: vibration={vibration_detected}, amplitude={amplitude:.2f}")

            if i < SAMPLE_COUNT - 1:
                time.sleep(SAMPLE_INTERVAL)

        average_amplitude = amplitude_sum / SAMPLE_COUNT
        print(f"\nAverage amplitude: {average_amplitude:.2f}")
        print(f"Vibration detected {healthy_count} times (out of {SAMPLE_COUNT})")

        if average_amplitude > THRESHOLD:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

    except KeyboardInterrupt:
        print("\nMonitoring interrupted by user.")
    except Exception as e:
        print(f"Unexpected error during monitoring: {e}")
    finally:
        if sensor is not None:
            try:
                sensor.close()
                print("Sensor resources released.")
            except Exception as e:
                print(f"Error closing sensor: {e}")


if __name__ == "__main__":
    main()

