import time
from gpiozero import LED
from gpiozero.exc import GPIODeviceError

# Configuration
LED_PIN = 17
MOISTURE_THRESHOLD = 30
INITIAL_MOISTURE = 50
DECREMENT_INTERVAL = 2  # seconds

def main():
    led = None
    try:
        led = LED(LED_PIN)
    except GPIODeviceError as e:
        print(f"Error initializing LED on GPIO {LED_PIN}: {e}")
        return
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}")
        return

    moisture = INITIAL_MOISTURE

    try:
        while True:
            print(f"Moisture: {moisture}")

            if moisture < MOISTURE_THRESHOLD:
                led.on()
                print("Watering started!")
            else:
                led.off()
                print("Watering stopped!")

            moisture -= 1
            if moisture < 0:
                moisture = 60  # Simulate rain

            time.sleep(DECREMENT_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        if led is not None:
            led.off()
            print("LED turned off.")

if __name__ == "__main__":
    main()

