import time
import signal
import sys
from smbus2 import SMBus
from gpiozero import LED, Buzzer

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x18
LED_PIN = 21
BUZZER_PIN = 20

# LIS3DH register addresses
WHO_AM_I = 0x0F
CTRL_REG1 = 0x20
CTRL_REG4 = 0x23
OUT_X_L = 0x28

# Expected WHO_AM_I value
WHO_AM_I_EXPECTED = 0x33

# Sensitivity: 1 g/LSB for ±2g full-scale (12-bit right-justified)
SENSITIVITY = 1.0 / 16384.0

# Thresholds (g)
THRESHOLD_LED = 0.3
THRESHOLD_BUZZER = 0.7

# Timing
SAMPLE_INTERVAL = 0.1
POLL_INTERVAL = 1.0

# --- Globals for cleanup -----------------------------------------------------
led = None
buzzer = None
bus = None
running = True


def cleanup():
    """Turn off outputs and close resources on exit."""
    global led, buzzer, bus
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global running
    running = False


def init_led():
    """Initialize the LED on GPIO 21."""
    try:
        return LED(LED_PIN)
    except Exception as e:
        print(f"Error initializing LED on GPIO {LED_PIN}: {e}")
        return None


def init_buzzer():
    """Initialize the buzzer on GPIO 20."""
    try:
        return Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing buzzer on GPIO {BUZZER_PIN}: {e}")
        return None


def init_i2c():
    """Open the I2C bus and verify the LIS3DH is present."""
    global bus
    try:
        bus = SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error opening I2C bus {I2C_BUS}: {e}")
        return None

    try:
        who = bus.read_byte_data(LIS3DH_ADDR, WHO_AM_I)
    except Exception as e:
        print(f"Error reading WHO_AM_I from LIS3DH at 0x{LIS3DH_ADDR:02X}: {e}")
        try:
            bus.close()
        except Exception:
            pass
        return None

    if who != WHO_AM_I_EXPECTED:
        print(f"Error: LIS3DH WHO_AM_I mismatch (got 0x{who:02X}, expected 0x{WHO_AM_I_EXPECTED:02X})")
        try:
            bus.close()
        except Exception:
            pass
        return None

    return bus


def init_lis3dh(bus):
    """Configure LIS3DH: 100 Hz data rate, normal mode, ±2g full-scale."""
    try:
        bus.write_byte_data(LIS3DH_ADDR, CTRL_REG1, 0x57)
        time.sleep(0.01)
        bus.write_byte_data(LIS3DH_ADDR, CTRL_REG4, 0x00)
        time.sleep(0.01)
    except Exception as e:
        print(f"Error configuring LIS3DH: {e}")
        try:
            bus.close()
        except Exception:
            pass
        return False
    return True


def read_accel_x(bus):
    """Read the X-axis acceleration in g. Returns None on error."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDR, OUT_X_L, 2)
    except Exception as e:
        print(f"Error reading X-axis acceleration: {e}")
        return None

    raw = (data[0] << 8) | data[1]
    if raw & 0x8000:
        raw -= 1 << 16
    return raw * SENSITIVITY


def main():
    global led, buzzer, running

    signal.signal(signal.SIGTERM, signal_handler)

    led = init_led()
    buzzer = init_buzzer()
    bus = init_i2c()

    if bus is None:
        print("I2C initialization failed. Exiting.")
        cleanup()
        sys.exit(1)

    if not init_lis3dh(bus):
        print("LIS3DH initialization failed. Exiting.")
        cleanup()
        sys.exit(1)

    print("Earthquake early warning system started. Press Ctrl+C to exit.")

    try:
        while running:
            accel_x = read_accel_x(bus)

            if accel_x is None:
                # I2C read failed: turn off outputs and wait before retrying
                if led is not None:
                    led.off()
                if buzzer is not None:
                    buzzer.off()
                time.sleep(0.5)
                continue

            print(f"X acceleration: {accel_x:.4f} g")

            if abs(accel_x) > THRESHOLD_LED:
                if led is not None:
                    led.on()
            else:
                if led is not None:
                    led.off()

            if abs(accel_x) > THRESHOLD_BUZZER:
                if buzzer is not None:
                    buzzer.on()
            else:
                if buzzer is not None:
                    buzzer.off()

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

