import signal
import sys
import time

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

DOOR_LOCK_PIN = 27
UNLOCK_DURATION = 5.0
LOOP_DELAY = 0.1

_lock: OutputDevice | None = None
_running = True


def _cleanup() -> None:
    """Drive the lock pin LOW and release resources."""
    global _lock
    if _lock is not None:
        try:
            _lock.off()  # Drive LOW
        except Exception:
            pass
        try:
            _lock.close()
        except Exception:
            pass
        _lock = None


def _handle_signal(signum, frame) -> None:
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def main() -> int:
    global _lock

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _lock = OutputDevice(DOOR_LOCK_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"Error: Failed to initialize GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error: Unexpected GPIO initialization failure: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            # Simulate receiving an authorization signal
            authorization_granted = True  # Replace with real input logic

            if authorization_granted:
                print("Authorization granted. Unlocking door.")
                try:
                    _lock.on()  # Drive HIGH
                    time.sleep(UNLOCK_DURATION)
                except GPIOZeroError as exc:
                    print(f"Error: Failed to drive lock HIGH: {exc}", file=sys.stderr)
                    return 1
                except Exception as exc:
                    print(f"Error: Unexpected error during unlock: {exc}", file=sys.stderr)
                    return 1
                try:
                    _lock.off()  # Drive LOW
                except GPIOZeroError as exc:
                    print(f"Error: Failed to drive lock LOW: {exc}", file=sys.stderr)
                    return 1
                except Exception as exc:
                    print(f"Error: Unexpected error during relock: {exc}", file=sys.stderr)
                    return 1
            else:
                print("Authorization denied. Door remains locked.")

            time.sleep(LOOP_DELAY)

    except Exception as exc:
        print(f"Error: Unexpected runtime error: {exc}", file=sys.stderr)
        return 1
    finally:
        _cleanup()
        print("Program terminated. GPIO resources released.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

