#!/usr/bin/env python3
"""
Control two DC motors via an Arduino Motor Shield (L293D + 74HC595 shift register)
on a Raspberry Pi using RPi.GPIO (bit-bang) and gpiozero (PWM).

Wiring (BCM numbering):
  74HC595  LATCH  -> GPIO 11
  74HC595  CLOCK  -> GPIO 9
  74HC595  DATA   -> GPIO 10
  Motor 1 PWM -> GPIO 13
  Motor 2 PWM -> GPIO 12
"""

import logging
import signal
import sys
import time

import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class Motor:
    """Single DC motor driven by an Arduino Motor Shield via a 74HC595 shift register."""

    def __init__(self, name, pwm_pin, direction_bits, pwm_frequency=100):
        self.name = name
        self.pwm_pin = pwm_pin
        self.direction_bits = direction_bits
        self.pwm_frequency = pwm_frequency
        self.pwm = None

    def setup(self):
        """Configure the PWM pin and start the motor at 0% duty cycle."""
        try:
            self.pwm = PWMOutputDevice(self.pwm_pin, frequency=self.pwm_frequency, initial_value=0.0)
            logger.info("Motor '%s' PWM pin %d configured at %d Hz.", self.name, self.pwm_pin, self.pwm_frequency)
        except Exception as exc:
            logger.error("Failed to setup Motor '%s' on pin %d: %s", self.name, self.pwm_pin, exc)
            raise

    def start(self, clockwise=True, duty_cycle=100):
        """Start the motor in the given direction at the given duty cycle (0-100)."""
        if self.pwm is None:
            raise RuntimeError("Motor '%s' not setup; cannot start." % self.name)
        direction = self.direction_bits[0] if clockwise else self.direction_bits[1]
        try:
            self.pwm.value = direction / 256.0
            self.pwm.frequency = self.pwm_frequency
            self.pwm.value = duty_cycle / 100.0
            logger.info("Motor '%s' started %s at %d%%.", self.name, "CW" if clockwise else "CCW", duty_cycle)
        except Exception as exc:
            logger.error("Failed to start Motor '%s': %s", self.name, exc)
            raise

    def change_duty_cycle(self, duty_cycle):
        """Change the motor's duty cycle (0-100)."""
        if self.pwm is None:
            raise RuntimeError("Motor '%s' not setup; cannot change duty cycle." % self.name)
        try:
            self.pwm.value = duty_cycle / 100.0
            logger.info("Motor '%s' duty cycle changed to %d%%.", self.name, duty_cycle)
        except Exception as exc:
            logger.error("Failed to change duty cycle for Motor '%s': %s", self.name, exc)
            raise

    def stop(self):
        """Stop the motor (duty cycle 0)."""
        if self.pwm is not None:
            try:
                self.pwm.value = 0.0
                logger.info("Motor '%s' stopped.", self.name)
            except Exception as exc:
                logger.error("Failed to stop Motor '%s': %s", self.name, exc)

    def close(self):
        """Release the PWM resource."""
        if self.pwm is not None:
            try:
                self.pwm.close()
            except Exception as exc:
                logger.error("Error closing PWM for Motor '%s': %s", self.name, exc)
            finally:
                self.pwm = None


class MotorShield:
    """Control two DC motors via an Arduino Motor Shield (74HC595 + L293D) on a Raspberry Pi."""

    def __init__(self, latch_pin, clock_pin, data_pin, motor1_pin, motor2_pin, pwm_frequency=100):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
