        self.motor1 = Motor("Motor1", motor1_pin, [0b00000010, 0b00000001, 0b00000000], pwm_frequency)
        self.motor2 = Motor("Motor2", motor2_pin, [0b00001000, 0b00000100, 0b00000000], pwm_frequency)
