            self._initialized = True
            logger.info("74HC595 control pins (LATCH=%d, CLOCK=%d, DATA=%d) configured.", self.latch_pin, self.clock_pin, self.data_pin)
        except Exception as exc:
            logger.error("Failed to setup 74HC595 control pins: %s", exc)
            raise

    def add_motor(self, motor):
        """Add a Motor instance to the shield."""
        raise NotImplementedError

    def start(self, motor1_clockwise=True, motor1_duty_cycle=100, motor2_clockwise=True, motor2_duty_cycle=100):
        """Start both motors."""
        try:
            self.motor1.start(motor1_clockwise, motor1_duty_cycle)
            self.motor2.start(motor2_clockwise, motor2_duty_cycle)
        except Exception as exc:
            logger.error("Failed to start motors: %s", exc)
            raise

    def change_duty_cycle(self, motor1_duty_cycle=None, motor2_duty_cycle=None):
        """Change duty cycles for motors 1 and/or 2."""
        if motor1_duty_cycle is not None:
            self.motor1.change_duty_cycle(motor1_duty_cycle)
        if motor2_duty_cycle is not None:
            self.motor2.change_duty_cycle(motor2_duty_cycle)

    def stop(self):
        """Stop both motors."""
        try:
            self.motor1.stop()
            self.motor2.stop()
        except Exception as exc:
            logger.error("Failed to stop motors: %s", exc)
            raise

    def stop_all_motors(self):
        """Stop all motors."""
        self.stop()

