import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two reflectance sensors (left and right)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
# GPIO pins for the two motors (left and right)
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_gpio():
    """Configure GPIO pins for the healthcare cart line following."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def read_sensors():
    """Read the two reflectance sensors and return their states."""
    try:
        left_sensor_state = GPIO.input(LEFT_SENSOR_PIN)
        right_sensor_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_sensor_state, right_sensor_state
    except Exception as e:
        print(f"Sensor read error: {e}")
        return None, None

def control_motors(left_state, right_state):
    """Control the left and right motors based on sensor states."""
    try:
        if left_state == 0 and right_state == 0:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        elif left_state == 0 and right_state == 1:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
        elif left_state == 1 and right_state == 0:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        elif left_state == 1 and right_state == 1:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
        else:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Motor control error: {e}")

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}")

if __name__ == "__main__":
    try:
        setup_gpio()
        for step_index in range(20):
            left_sensor_state, right_sensor_state = read_sensors()
            if left_sensor_state is None or right_sensor_state is None:
                print("Sensor read error, stopping motors")
                break
            control_motors(left_sensor_state, right_sensor_state)
            print(f"Step {step_index}: Left={left_sensor_state}, Right={right_sensor_state}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Line following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

