import signal
import sys
import time
from gpiozero import AngularServo, Device
from gpiozero.exc import OutputDeviceBadValue, DeviceClosed

# SG90 micro servo pulse-width limits (microseconds): 0.5ms -> 2.5ms
MIN_PULSE_WIDTH = 0.5 / 1000
MAX_PULSE_WIDTH = 2.5 / 1000
SERVO_FREQUENCY = 50  # Hz

# GPIO pins (Broadcom numbering)
BASE_PIN = 17
SHOULDER_PIN = 27
GRIPPER_PIN = 22

# Global list so signal handler can clean up
_servos = []


def _cleanup(signum=None, frame=None):
    """Detach all servos and release GPIO resources."""
    for s in _servos:
        try:
            s.detach()
        except (DeviceClosed, RuntimeError):
            pass
    for s in _servos:
        try:
            s.close()
        except Exception:
            pass
    _servos.clear()
    if signum is not None:
        sys.exit(0)


def create_servo(pin, min_pw=MIN_PULSE_WIDTH, max_pw=MAX_PULSE_WIDTH,
                  max_angle=90, initial_angle=0):
    """Create and return an AngularServo with error handling."""
    try:
        return AngularServo(
            pin,
            min_pulse_width=min_pw,
            max_pulse_width=max_pw,
            max_angle=max_angle,
            initial_angle=initial_angle,
            frame_rate=SERVO_FREQUENCY,
        )
    except ValueError as e:
        print(f"ValueError: Invalid pin or conflict: {e}", file=sys.stderr)
        raise
    except RuntimeError as e:
        print(f"RuntimeError: GPIO allocation failed: {e}", file=sys.stderr)
        raise


class RoboticArm:
    """Three-servo robotic arm controller using gpiozero AngularServo."""

    def __init__(self, base_pin=BASE_PIN, shoulder_pin=SHOULDER_PIN,
                 gripper_pin=GRIPPER_PIN):
        self.base_servo = create_servo(base_pin)
        self.shoulder_servo = create_servo(shoulder_pin)
        self.gripper_servo = create_servo(gripper_pin)
        _servos.extend([self.base_servo, self.shoulder_servo, self.gripper_servo])

    def move_joint(self, servo, angle):
        """Move a servo to a clamped angle (degrees)."""
        if not -90 <= angle <= 90:
            raise OutputDeviceBadValue(
                f"Angle {angle} out of range [-90, 90]"
            )
        try:
            servo.angle = angle
            time.sleep(0.4)  # settling delay
        except (DeviceClosed, OutputDeviceBadValue) as e:
            print(f"OutputDeviceBadValue: {e}", file=sys.stderr)
            raise

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints to the specified angles."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos."""
        for s in _servos:
            try:
                s.detach()
            except (DeviceClosed, RuntimeError):
                pass

    def close(self):
        """Release all servos and clean up GPIO."""
        self.release()
        for s in _servos:
            try:
                s.close()
            except Exception:
                pass
        _servos.clear()


def run_demo_sequence(robot_arm):
    """Run a short pose demonstration sequence."""
    poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]
    for base_angle, shoulder_angle, gripper_angle in poses:
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)
        time.sleep(1)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    try:
        robot_arm = RoboticArm()
        run_demo_sequence(robot_arm)
    except (ValueError, RuntimeError) as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        _cleanup()

