import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class GSMModule:
    """
    A class to encapsulate GSM/GPS module functionality, including serial
    communication, AT command execution, and data transmission.
    """

    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2,
                 power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.serial_port = None
        self._gpio_initialized = False
        self._running = True

        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout
            )
            logging.info(f"Serial port {self.port} opened at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.power_pin, GPIO.OUT, initial=GPIO.LOW)
            self._gpio_initialized = True
            logging.info(f"GPIO pin {self.power_pin} initialized for power control.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self._gpio_initialized = False

        self._install_signal_handlers()
        self._pulse_power()
        self._wait_for_network_ready()
        self._send_at_command(b'AT', expected_response='OK', attempts=3)
        logging.info("GSM module initialized successfully.")

