        if self._gpio_initialized:
            GPIO.output(self.power_pin, GPIO.HIGH)
            time.sleep(2)
            GPIO.output(self.power_pin, GPIO.LOW)
            time.sleep(0.5)
        else:
            logging.warning("GPIO not initialized; skipping power pulse.")

    def _wait_for_network_ready(self):
