            logging.error("Serial port is not open.")
            return None

        accumulated_response = b''
        for _ in range(attempts):
            try:
                waiting = self.serial_port.in_waiting
                if waiting > 0:
                    chunk = self.serial_port.read(waiting)
                    if chunk:
