import signal
import sys
import json
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)

@app.route('/relay', methods=['POST'])
def relay_control():
    global relay
    if relay is None:
        return jsonify({'error': 'Relay not initialized'}), 500

    try:
        payload = request.get_json(silent=True)
    except Exception:
        return jsonify({'error': 'Invalid request body'}), 400

    if not isinstance(payload, dict):
        return jsonify({'error': 'Invalid request body: expected JSON object'}), 400

    if 'state' not in payload:
        return jsonify({'error': 'Invalid request: missing "state" key'}), 400

    state = payload['state']
    if state not in ('on', 'off'):
        return jsonify({'error': 'Invalid state value. Must be "on" or "off"'}), 400

    try:
        if state == 'on':
            relay.on()
        else:
            relay.off()
    except GPIOZeroError as e:
        return jsonify({'error': f'GPIO operation failed: {e}'}), 500

    return jsonify({'status': 'Relay state changed'}), 200

if __name__ == '__main__':
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f'Failed to initialize GPIO {RELAY_PIN}: {e}', file=sys.stderr)
        sys.exit(1)
    app.run(host='0.0.0.0', port=5000)

