import logging
import sys
from typing import Dict, Any, Optional

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# Actuator configuration: {name: BCM pin}
ACTUATOR_PINS: Dict[str, int] = {
    "nutrient_pump": 20,
    "grow_light": 21,
}

# Intent -> (actuator_name, action)
INTENT_MAP: Dict[str, tuple] = {
    "pump_on": ("nutrient_pump", "on"),
    "pump_off": ("nutrient_pump", "off"),
    "light_toggle": ("grow_light", "toggle"),
}

# Global actuator handles for safe cleanup
_actuators: Dict[str, OutputDevice] = {}


def parse_intent(phrase: str) -> Optional[Dict[str, Any]]:
    """Parse a plain English phrase into a hydroponics intent.

    Args:
        phrase: The input phrase to parse.

    Returns:
        A dict with 'intent' and 'action' keys, or None if the phrase
        does not match any known intent.
    """
    # Case-insensitive keyword matching
    lower_phrase = phrase.lower()
    for intent_name, (actuator_name, action) in INTENT_MAP.items():
        if lower_phrase.find(intent_name) != -1:
            return {"intent": intent_name, "action": action}
    return None


def apply_intent(intent: Dict[str, Any], actuators: Dict[str, OutputDevice]) -> None:
    """Apply the parsed intent to the configured actuators.

    Args:
        intent: The parsed intent dict.
        actuators: A dict mapping actuator names to gpiozero OutputDevice objects.
    """
    actuator_name = intent.get("intent")
    action = intent.get("action")

    if actuator_name not in ACTUATOR_PINS:
        logger.warning("Unknown actuator: %s", actuator_name)
        return

    try:
        actuator = actuators[actuator_name]
        if action == "on":
            actuator.on()
            logger.info("Actuator '%s' turned ON", actuator_name)
        elif action == "off":
            actuator.off()
            logger.info("Actuator '%s' turned OFF", actuator_name)
        elif action == "toggle":
            actuator.toggle()
            logger.info("Actuator '%s' toggled", actuator_name)
        else:
            logger.warning("Unknown action '%s' for actuator '%s'", action, actuator_name)
    except GPIOZeroError as e:
        logger.error("GPIO error applying intent '%s': %s", actuator_name, e)
    except Exception as e:
        logger.error("Unexpected error applying intent '%s': %s", actuator_name, e)


def init_actuators() -> Dict[str, OutputDevice]:
    """Initialize all configured actuator OutputDevice objects.

    Returns:
        A dict mapping actuator names to gpiozero OutputDevice objects.

    Raises:
        RuntimeError: If any actuator cannot be initialized.
    """
    actuators: Dict[str, OutputDevice] = {}
    for name, pin in ACTUATOR_PINS.items():
        try:
            actuators[name] = OutputDevice(pin)
            logger.info("Initialized actuator '%s' on BCM GPIO%d", name, pin)
        except GPIOZeroError as e:
            logger.error("Failed to initialize actuator '%s' on GPIO%d: %s", name, pin, e)
            raise RuntimeError(f"Failed to initialize actuator '{name}' on GPIO{pin}") from e
    return actuators


def cleanup_actuators(actuators: Dict[str, OutputDevice]) -> None:
    """Turn off and close all actuator OutputDevice objects safely."""
    for name, actuator in actuators.items():
        try:
            actuator.off()
            actuator.close()
            logger.info("Closed actuator '%s'", name)
        except Exception as e:
            logger.error("Error closing actuator '%s': %s", name, e)


def main() -> None:
    """Main entry point: parse phrases and drive actuators."""
    try:
        actuators = init_actuators()
        _actuators.update(actuators)
    except RuntimeError as e:
        logger.critical("Actuator initialization failed: %s", e)
        sys.exit(1)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    for phrase in test_phrases:
        intent = parse_intent(phrase)
        if intent:
            apply_intent(intent, _actuators)
        else:
            logger.warning("No intent matched: %s", phrase)

    # Ensure all actuators are off and resources are released
    cleanup_actuators(_actuators)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
    except Exception as e:
        logger.critical("Unhandled exception: %s", e)
    finally:
        cleanup_actuators(_actuators)

