import signal
import sys
import time
from datetime import datetime
from smbus2 import SMBus, i2c_msg

DS1338_I2C_ADDR = 0x68
I2C_BUS = 1


class DS1338Error(Exception):
    """Custom exception for DS1338 RTC errors."""
    pass


class DS1338:
    """Driver for the Maxim DS1338 I2C RTC."""

    def __init__(self, bus_num=I2C_BUS, addr=DS1338_I2C_ADDR):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as e:
            raise DS1338Error(f"Failed to open I2C bus {bus_num}: {e}") from e

        # Verify device presence with a zero-length write to the seconds register.
        try:
            self.bus.write_byte_data(self.addr, 0x00, 0x00)
        except OSError as e:
            self.close()
            raise DS1338Error(
                f"No DS1338 found at address 0x{self.addr:02X} on bus {bus_num}: {e}"
            ) from e

    def close(self):
        """Release the I2C bus handle."""
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def _bcd_to_int(self, bcd):
        return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)

    def _int_to_bcd(self, n):
        return ((n // 10) << 4) | (n % 10)

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.addr, reg, value)
        except OSError as e:
            raise DS1338Error(f"I2C write to register 0x{reg:02X} failed: {e}") from e

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.addr, reg)
        except OSError as e:
            raise DS1338Error(f"I2C read from register 0x{reg:02X} failed: {e}") from e

    def read_seconds(self):
        data = self._read_register(0x00)
        return self._bcd_to_int(data & 0x7F)

    def read_minutes(self):
        data = self._read_register(0x01)
        return self._bcd_to_int(data & 0x7F)

    def read_hours(self):
        data = self._read_register(0x02)
        return self._bcd_to_int(data & 0x3F)

    def read_date(self):
        data = self._read_register(0x04)
        return self._bcd_to_int(data & 0x3F)

    def read_month(self):
        data = self._read_register(0x05)
        return self._bcd_to_int(data & 0x1F)

    def read_year(self):
        data = self._read_register(0x06)
        return self._bcd_to_int(data & 0x3F)

    def write_seconds(self, value):
        self._write_register(0x00, self._int_to_bcd(value))

    def write_minutes(self, value):
        self._write_register(0x01, self._int_to_bcd(value))

    def write_hours(self, value):
        self._write_register(0x02, self._int_to_bcd(value))

    def write_date(self, value):
        self._write_register(0x04, self._int_to_bcd(value))

    def write_month(self, value):
        self._write_register(0x05, self._int_to_bcd(value))

    def write_year(self, value):
        self._write_register(0x06, self._int_to_bcd(value))

    def read_datetime(self, century=21):
        """Read and return a datetime object (24-hour format)."""
        if not 0 <= century <= 2:
            raise ValueError("Century must be 0, 1, or 2.")
        year = (century - 1) * 100 + self.read_year()
        try:
            return datetime(
                year=year,
                month=self.read_month(),
                day=self.read_date(),
                hour=self.read_hours(),
                minute=self.read_minutes(),
                second=self.read_seconds(),
            )
        except ValueError as e:
            raise DS1338Error(f"Invalid RTC data: {e}") from e

    def write_all(self, second=None, minute=None, hour=None, date=None, month=None, year=None):
        """Write all fields; fields not provided are read from the RTC."""
        if second is not None:
            self.write_seconds(second)
        if minute is not None:
            self.write_minutes(minute)
        if hour is not None:
            self.write_hours(hour)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting...")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    rtc = None
    try:
        rtc = DS1338()
        print("RTC initialized successfully.")

        # Example: read current time
        now = rtc.read_datetime()
        print(f"Current RTC time: {now.strftime('%Y-%m-%d %H:%M:%S')}")

        # Example: write time to 2024-10-05 14:30:00
        rtc.write_year(24)
        rtc.write_month(10)
        rtc.write_date(5)
        rtc.write_hours(14)
        rtc.write_minutes(30)
        rtc.write_seconds(0)
        print("Time written to RTC.")

        # Example: read back
        back = rtc.read_datetime()
        print(f"Read back time: {back.strftime('%Y-%m-%d %H:%M:%S')}")

    except DS1338Error as e:
        print(f"DS1338 error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if rtc is not None:
            rtc.close()


if __name__ == "__main__":
    main()

