            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    def test_connection(self):
        response = self._send_command(b'AT', timeout=1.0, wait_for=b'OK')
        if response and b'OK' in response:
            return True
        return False

    def restart(self):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return False
        try:
            self._send_command(b'AT+RST', timeout=2.0)
            time.sleep(2)
            response = self._send_command(b'AT', timeout=1.0, wait_for=b'OK')
            return response and b'OK' in response
        except serial.SerialException as e:
            print(f"Error restarting ESP8266: {e}", file=sys.stderr)
            return False

    def connect_wifi(self, ssid, password):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return False
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command.encode(), timeout=10.0)
        if response and b'OK' in response:
            return True
        return False

    def disconnect_wifi(self):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return False
        try:
            self._send_command(b'AT+CWQAP', timeout=1.0)
            return True
        except serial.SerialException as e:
            print(f"Error disconnecting WiFi: {e}", file=sys.stderr)
            return False

    def get_ip(self):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return None
        response = self._send_command(b'AT+CIFSR', timeout=1.0)
        if response and b'+CIFSR' in response:
            match = re.search(r'(\d+\.\d+)', response.decode(errors='ignore'))
            if match:
                return match.group(1)
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return None
        try:
            start_cmd = f'AT+CIPSTART="HTTP/{method}",{host},{port}'
            self._send_command(start_cmd.encode(), timeout=5.0)
            if not self._send_command(b'AT+CIPSEND', timeout=2.0):
                return None
            request = (f'{method} {url}\r\n'
                       f'Host: {host}\r\n'
                       f'Connection: close\r\n')
            if headers:
                request += (f'{headers}\r\n')
            if data:
                request += (f'Content-Type: application/json\r\n'
                           f'Content-Length: {len(data)}\r\n')
                request += (f'{{}}\r\n'.format(data))
            self._send_command(request.encode())
            response = b''
            while time.time() - 10.0 < 10.0:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk
                        if b'CLOSED' in response:
                            break
                else:
                    time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Error sending HTTP request: {e}", file=sys.stderr)
            return None

    def receive_http_response(self, timeout=5.0):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized.", file=sys.stderr)
            return None
        try:
            response = b''
            while time.time() - 10.0 < timeout:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk
                        if b'+IPD,' in response:
                            start_idx = response.index(b'+IPD,')
                            data_start = start_idx + 6
                            data_end = data_start + int(response[data_start:].split(b',')[0])
                            payload = response[data_start:data_start + data_end]
                            return payload
                else:
                    time.sleep(0.01)
            return None
        except serial.SerialException as e:
            print(f"Error receiving HTTP response: {e}", file=sys.stderr)
            return None

    def close(self):
        if self.uart and self.uart.is_open:
            try:
                self.uart.close()
            except serial.SerialException as e:
                print(f"Error closing UART: {e}", file=sys.stderr)
        self.uart = None

def main():
    esp = None
    try:
        esp = ESP8266()
        if esp.uart and esp.uart.is_open:
            print("ESP8266 initialized successfully.")
            if esp.test_connection():
                print("ESP8266 is connected.")
                if esp.connect_wifi("SSID", "PASSWORD"):
                    print("Connected to WiFi.")
                    ip = esp.get_ip()
                    print(f"IP Address: {ip}")
                    esp.send_http_request("GET", "/api/data", "192.168.1.100", 80)
                    resp = esp.receive_http_response()
                    if resp:
                        print(f"Received response: {resp}")
                else:
                    print("Failed to connect to WiFi.")
            else:
                print("ESP8266 not responding.")
        else:
            print("UART not initialized.")
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        if esp:
            esp.close()

if __name__ == '__main__':
    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))
    main()

