import serial
import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_radiation_level(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return float(raw.decode('ascii', errors='replace'))
    except ValueError:
        print(f"Invalid data received (not a float): {raw!r}", file=sys.stderr)
        return None

def control_alarm(alarm, radiation_level):
    if radiation_level is None:
        return
    if radiation_level > RADIATION_THRESHOLD:
        alarm.on()
        print(f"ALARM: Radiation level {radiation_level:.2f} µSv/h exceeds threshold {RADIATION_THRESHOLD} µSv/h")
    else:
        alarm.off()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        alarm = OutputDevice(ALARM_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO {ALARM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        alarm.close()
        sys.exit(1)

    try:
        while _running:
            radiation = read_radiation_level(ser)
            control_alarm(alarm, radiation)
            time.sleep(LOOP_DELAY)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")

if __name__ == '__main__':
    main()

