from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

running = True
serial_port = None
alarm = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_port, alarm
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
        except Exception:
            pass
    if alarm is not None:
        try:
            alarm.close()
        except Exception:
            pass

def main():
    global serial_port, alarm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Error initializing GPIO pin {ALARM_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f"Monitoring radiation levels on {SERIAL_PORT} @ {BAUD_RATE} baud. "
          f"Alarm on BCM pin {ALARM_PIN}. Press Ctrl+C to exit.")

    try:
        while running:
            try:
                raw = serial_port.readline()
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation_level = float(line)
            except ValueError:
                print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
                continue

            if radiation_level > RADIATION_THRESHOLD:
