            else:
                if alarm.is_active:
                    print(f"Deactivated alarm: Radiation level {radiation_level:.2f} "
                          f"µSv/h is within safe limits.")
                    alarm.off()

            print(f"Radiation Level: {radiation_level:.2f} µSv/h")

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
