import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
READ_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_reading(raw_data):
    try:
        parts = raw_data.split(',')
        if len(parts) != 2:
            raise ValueError(f"Expected 2 fields, got {len(parts)}")
        hr_str, spo2_str = parts[0].strip(), parts[1].strip()
        if not hr_str or not spo2_str:
            raise ValueError("Empty field")
        return int(hr_str), int(spo2_str)
    except ValueError as e:
        print(f"Error parsing data '{raw_data}': {e}")
        return None, None

def log_reading(hr, spo2):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f"{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %\n"
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(line)
    except OSError as e:
        print(f"Error writing to log file: {e}")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Waiting for data...")
            while _running:
                try:
                    raw_bytes = ser.readline()
                except serial.SerialException as e:
                    print(f"Serial I/O error: {e}")
                    time.sleep(READ_INTERVAL)
                    continue

                if not raw_bytes:
                    continue

                raw_data = raw_bytes.decode('ascii', errors='replace').strip()
                if not raw_data:
                    continue

                hr, spo2 = parse_reading(raw_data)
                if hr is not None and spo2 is not None:
                    print(f"Heart Rate: {hr} bpm, SpO2: {spo2} %")
                    log_reading(hr, spo2)
                else:
                    print(f"Invalid data received: {raw_data}")

                time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()

