import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    num_satellites: int


class GPSReader:
    """
    Reads NMEA GPS data from a serial port and parses GPGGA sentences.
    """

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        """Open the serial port. Returns True on success, False on failure."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            logging.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logging.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_port = None
            return False
        except Exception as e:
            logging.error("Unexpected error opening %s: %s", self.port, e)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        """Idempotently close the serial port if open."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logging.info("Serial port closed")
            except Exception as e:
                logging.error("Error closing serial port: %s", e)
            finally:
                self.serial_port = None

    def _signal_handler(self, signum, frame):
        """Handle SIGINT/SIGTERM for graceful shutdown."""
        logging.info("Received signal %d, shutting down...", signum)
        self._running = False

    def read_gps_data(self) -> Optional[GPS_readings]:
        """
        Read one line from the serial port and parse a GPGGA sentence.
        Returns the parsed GPS_readings dataclass, or None on error/timeout.
        """
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logging.error("Serial read error: %s", e)
            return None
        except Exception as e:
            logging.error("Unexpected read error: %s", e)
            return None

        if not raw:
            # readline() returns b'' on timeout
            logging.warning("Read timeout, no data received")
            return None

        try:
            line = raw.decode("utf-8", errors="ignore").strip()
        except Exception as e:
            logging.error("Decode error: %s", e)
            return None

        if not line:
            return None

        if line.startswith("$GPGGA"):
            return self._parse_gpgga(line)
        return None

    def _validate_checksum(self, sentence: str) -> bool:
        """Validate the NMEA checksum (X*XX)."""
        if "*" not in sentence:
            return False
        body, _, csum = sentence.partition("*")
        if not body.startswith("$GPGGA"):
            return False
        try:
            expected = int(csum.strip()[:2], 16)
        except ValueError:
            return False
        try:
            calculated = 0
            for ch in body[1:]:
                calculated ^= ord(ch)
        except Exception:
            return False
        return calculated == expected

    def _parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        """
        Parse a $GPGGA sentence into a GPS_readings dataclass.
        """
        if not self._validate_checksum(sentence):
            logging.warning("Checksum failed: %s", sentence)
            return None

        fields = sentence.split(",")
        if len(fields) < 15:
            logging.warning(
                "Incomplete GPGGA (expected >= 15 fields, got %d): %s",
                len(fields),
                sentence,
            )
            return None

        talker = fields[0]
        if talker != "$GPGGA":
            logging.warning("Not from GPGGA talker: %s", talker)
            return None

        try:
            fix_quality = int(fields[6])
        except ValueError:
            logging.warning("Invalid fix quality field: %s", fields[6])
            return None

        if fix_quality == 0:
            logging.warning("GPS fix not valid (fix_quality=0)")
            return None

        try:
            latitude = float(fields[2])
            latitude_dir = fields[3]
            longitude = float(fields[4])
            longitude_dir = fields[5]
            altitude = float(fields[9])
            num_satellites = int(fields[7])
        except ValueError as e:
            logging.error("Numeric parse error in GPGGA: %s", e)
            return None

        if latitude_dir not in ("N", "S"):
            logging.warning("Invalid latitude direction: %s", latitude_dir)
            return None
        if longitude_dir not in ("E", "W"):
            logging.warning("Invalid longitude direction: %s", longitude_dir)
            return None

        try:
            decimal_latitude = self._to_decimal(latitude, latitude_dir)
            decimal_longitude = self._to_decimal(longitude, longitude_dir)
        except ValueError as e:
            logging.error("Coordinate conversion error: %s", e)
            return None

        return GPS_readings(
            latitude=decimal_latitude,
            longitude=decimal_longitude,
            altitude=altitude,
            num_satellites=num_satellites,
        )

    @staticmethod
    def _to_decimal(value: float, direction: str) -> float:
        """Convert NMEA ddmm.mmmm to decimal degrees."""
        if not direction in ("N", "S"):
            raise ValueError(f"Invalid direction: {direction}")
        degrees = int(value // 100)
        minutes = value - (degrees * 100)
        decimal = degrees + (minutes / 60.0)
        if direction == "S":
            decimal = -decimal
        return decimal

    def run(self) -> None:
        """Main loop: connect, read, and clean up on exit."""
        if not self.connect():
            return

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            while self._running:
                readings = self.read_gps_data()
                if readings is not None:
                    logging.info(
                        "Lat: %.6f, Lon: %.6f, Alt: %.1f m, Satellites: %d",
                        readings.latitude,
                        readings.longitude,
                        readings.altitude,
                        readings.num_satellites,
                    )
        except Exception as e:
            logging.error("Unexpected error in main loop: %s", e)
        finally:
            self.disconnect()


if __name__ == "__main__":
    reader = GPSReader(port="/dev/serial0", baudrate=9600)
    reader.run()

