class ESP8266:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=5):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self._running = True
        try:
            self.ser = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=timeout,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE
            )
            if not self.ser.is_open:
                raise serial.SerialException(f"Failed to open serial port {port}")
            print(f"ESP8266 initialized on {port} at {baudrate} baud.")
        except serial.SerialException as e:
            print(f"Error initializing serial port: {e}")
            self.ser = None
            raise

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received, shutting down...")
        self._running = False
        self.close()
        sys.exit(0)

    def close(self):
        if self.ser and self.ser.is_open:
            self.ser.close()
            print("Serial port closed.")
        self.ser = None

    def _send_command(self, command, delay=1, max_retries=3):
        if not self.ser or not self.ser.is_open:
            print("Serial port not open.")
            return None

        for attempt in range(max_retries):
            try:
                self.ser.write(command.encode('utf-8'))
                self.ser.flush()
                time.sleep(delay)
                response = self.ser.readline().decode('utf-8', errors='ignore').strip()
                if response and (response == 'OK' or response == 'ERROR' or response == 'FAIL'):
                    return response
                else:
                    print(f"Attempt {attempt + 1}/{max_retries}: No valid response. Response: {response}")
            except serial.SerialException as e:
                print(f"Serial communication error on attempt {attempt + 1}: {e}")
            except Exception as e:
                print(f"Unexpected error on attempt {attempt + 1}: {e}")
            time.sleep(0.5)
        return None

    def _read_response(self):
        if not self.ser or not self.ser.is_open:
            print("Serial port not open.")
            return None
        start_time = time.time()
        response = b""
        while time.time() - start_time < self.timeout:
            if self.ser.in_waiting > 0:
                chunk = self.ser.read(self.ser.in_waiting)
                if chunk:
                    response += chunk
                    if b"OK" in response or b"ERROR" in response or b"FAIL" in response:
                        break
            else:
                time.sleep(0.01)
        try:
            decoded = response.decode('utf-8', errors='ignore').strip()
            if decoded and (decoded == 'OK' or decoded == 'ERROR' or decoded == 'FAIL'):
                return decoded
            return None
        except Exception as e:
            print(f"Error decoding response: {e}")
            return None

    def test_connection(self):
        response = self._send_command("AT\r\n")
        return response == 'OK'

    def restart(self):
        response = self._send_command("AT+RST\r\n", delay=2)
        return response == 'OK'

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5)
        return response == 'WIFI GOT IP'

    def disconnect_wifi(self):
        response = self._send_command("AT+CWQAP\r\n")
        return response == 'OK'

if __name__ == '__main__':
    esp = None
    try:
