import serial
import time
import signal
import sys


class GPS:
    """
    A class to control and read data from a GPS module (e.g., SIM28 or SIM808)
    connected via a serial port on a Raspberry Pi using pyserial.
    """

    def __init__(self, port='/dev/ttyAMA0', baud=9600, timeout=1.0):
        self.port = port
        self.baud = baud
        self.timeout = timeout
        self.ser = None
        self._closed = False

        try:
            self.ser = serial.Serial(
                port=port,
                baudrate=baud,
                timeout=timeout,
                write_timeout=timeout
            )
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open serial port {port}: {e}") from e

    def attach(self):
        """Powers on the GNSS module."""
        if self.ser is None or self.ser.closed:
            raise RuntimeError("Serial port is not initialized.")
        try:
            self.ser.write(b'AT+CGNSPWR=1\r\n')
            self.ser.flush()
            time.sleep(1)
            if self.ser.in_waiting > 0:
                data = self.ser.read(self.ser.in_waiting)
                if b'OK' in data:
                    return True
                print(f"GNSS power-on response: {data}")
            else:
                print("GNSS power-on successful (no data waiting).")
        except serial.SerialException as e:
            print(f"Error powering on GNSS: {e}")
            return False
