import serial
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial connection error on {self.port}: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if self.serial_connection is None:
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                data = self.serial_connection.readline()
                if data:
                    return data.decode('utf-8', errors='ignore').strip()
            return None
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS read error: {e}")
            return None

    def parse_gga(self, nmea_sentence):
        if not nmea_sentence:
            return None
        try:
            parts = nmea_sentence.split(',')
            if len(parts) < 15:
                return None
            talker_id = parts[0]
            if talker_id not in ('$GPGGA', '$GNGGA'):
                return None
            utc_time = parts[1]
            lat = parts[2]
            lat_dir = parts[3]
            lon = parts[4]
            lon_dir = parts[5]
            fix_quality = parts[6]
            num_satellites = parts[7]
            if not utc_time or not lat or not lon:
                return None
            try:
                latitude = float(lat)
                longitude = float(lon)
            except ValueError:
                return None
            if lat_dir not in ('N', 'S') or lon_dir not in ('E', 'W'):
                return None
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except IndexError as e:
            logging.error(f"NMEA parse error (index {e}): {nmea_sentence}")
            return None
        except ValueError as e:
            logging.error(f"NMEA parse error (value {e}): {nmea_sentence}")
            return None

    def close(self):
        if self.serial_connection is not None:
            try:
                if self.serial_connection.is_open:
                    self.serial_connection.close()
                logging.info("Serial connection closed.")
            except Exception as e:
                logging.error(f"Error closing serial connection: {e}")
            finally:
                self.serial_connection = None

    def stop(self):
        self._running = False

def main():
    gps = SimpleGPS()
    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

    def signal_handler(sig, frame):
        logging.info("Shutdown signal received.")
        gps.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while gps._running:
            line = gps.read_data()
            if line:
                parsed = gps.parse_gga(line)
                if parsed:
                    logging.info(f"Parsed GPS: {parsed}")
            else:
                logging.debug("No data received.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

