import signal
import sys
import threading
import time
from flask import Flask, Response, request, jsonify
from serial import Serial, SerialException, SerialTimeoutException

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1.0
DATA_STORE = [
    {'id': 1, 'name': 'CHIPS', 'done': False},
    {'id': 2, 'name': 'fruit', 'done': True},
]
SERIAL_LOCK = threading.Lock()
serial_port = None
shutdown_event = threading.Event()


class SerialCommunicator:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None
        self._closed = False

    def open(self):
        with SERIAL_LOCK:
            if self._closed:
                try:
                    self.serial = Serial(
                        port=self.port,
                        baudrate=self.baudrate,
                        bytesize=8,
                        parity='N',
                        stopbits=1,
                        timeout=self.timeout,
                    )
                    if not self.serial.is_open:
                        raise SerialException(f"Failed to open {self.port}")
                except SerialException as e:
                    print(f"Serial open error: {e}", file=sys.stderr)
                    self.serial = None
                    return False
            return True

    def close(self):
        with SERIAL_LOCK:
            if self.serial is not None:
                try:
                    if self.serial.is_open:
                        self.serial.close()
                except SerialException as e:
                    print(f"Serial close error: {e}", file=sys.stderr)
                finally:
                    self.serial = None
                    self._closed = True

    def send(self, cmd):
        if self.serial is None or not self.serial.is_open:
            print("Serial port not open", file=sys.stderr)
            return False
        try:
            payload = cmd.encode('ascii')
            written = self.serial.write(payload)
            self.serial.flush()
            if written != len(payload):
                print(f"Short write: {written}/{len(payload)} bytes", file=sys.stderr)
                return False
            return True
        except SerialException as e:
            print(f"Serial send error: {e}", file=sys.stderr)
            return False

    def receive_line(self):
        if self.serial is None or not self.serial.is_open:
            print("Serial port not open", file=sys.stderr)
            return None
        try:
            raw = self.serial.readline()
            if not raw:
                return None
            return raw.decode('ascii', errors='replace').strip()
        except SerialException as e:
            print(f"Serial receive error: {e}", file=sys.stderr)
            return None


def get_serial_instance():
    global serial_port
    with SERIAL_LOCK:
        if serial_port is None:
            serial_port = SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE, SERIAL_TIMEOUT)
        return serial_port


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    shutdown_event.set()


@app.route('/version', methods=['GET'])
def get_version():
    comm = get_serial_instance()
    try:
        if not comm.open():
            return Response("Serial port unavailable", status=500, mimetype='text/plain')
        cmd = '*IDN?\n'
        if not comm.send(cmd):
            return Response("Send failed", status=502, mimetype='text/plain')
        line = comm.receive_line()
        if line is None:
            return Response("No response (timeout)", status=504, mimetype='text/plain')
        return Response(line, mimetype='text/plain')
    except Exception as e:
        print(f"Error in /version: {e}", file=sys.stderr)
        return Response(f"Internal server error: {e}", status=500, mimetype='text/plain')
    finally:
        comm.close()


@app.route('/data', methods=['GET'])
def get_data():
    with SERIAL_LOCK:
        if serial_port is None:
            return Response("Serial port not initialized", status=500, mimetype='text/plain')
        try:
            comm = get_serial_instance()
            if not comm.open():
                return Response("Serial port unavailable", status=500, mimetype='text/plain')
            line = comm.receive_line()
            if line is None:
                return Response("No data available", status=500, mimetype='text/plain')
            return Response(line, mimetype='text/plain')
        except Exception as e:
            print(f"Error in /data: {e}", file=sys.stderr)
            return Response(f"Internal server error: {e}", status=500, mimetype='text/plain')
        finally:
            comm.close()


@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    with SERIAL_LOCK:
        if serial_port is None:
            return Response("Serial port not initialized", status=500, mimetype='text/plain')
        try:
            comm = get_serial_instance()
            if not comm.open():
                return Response("Serial port unavailable", status=500, mimetype='text/plain')
            item = next((x for x in DATA_STORE if x['id'] == item_id), None)
            if item is None:
                return Response(f"Item not found with id {item_id}", status=404, mimetype='text/plain')
            line = item.get('name', 'unknown')
            return Response(f"{line} (ID: {item_id})", mimetype='text/plain')
        except Exception as e:
            print(f"Error in /data/{item_id}: {e}", file=sys.stderr)
            return Response(f"Internal server error: {e}", status=500, mimetype='text/plain')
        finally:
            comm.close()


@app.route('/data', methods=['POST'])
def create_item():
    try:
        data = request.get_json(silent=True) or {}
        name = data.get('name', '')
        done = bool(data.get('done', False))
    except (TypeError, ValueError) as e:
        return Response(f"Invalid JSON: {e}", status=400, mimetype='text/plain')

    if not name:
        return Response("Name is required", status=400, mimetype='text/plain')
    if not isinstance(done, bool):
        return Response("done must be a boolean", status=400, mimetype='text/plain')

    with SERIAL_LOCK:
        if serial_port is None:
            return Response("Serial port not initialized", status=500, mimetype='text/plain')
        try:
            comm = get_serial_instance()
            if not comm.open():
                return Response("Serial port unavailable", status=500, mimetype='text/plain')
            cmd = f'POST /data\n'
            if not comm.send(cmd):
                return Response("Send failed", status=502, mimetype='text/plain')
            new_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
            new_item = {'id': new_id, 'name': name, 'done': done}
            DATA_STORE.append(new_item)
            return jsonify(new_item), 201
        except Exception as e:
            print(f"Error in /data: {e}", file=sys.stderr)
            return Response(f"Internal server error: {e}", status=500, mimetype='text/plain')
        finally:
            comm.close()


def run_app():
    app.run(host='0.0.0.0', port=5000, debug=False)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        run_app()
    except KeyboardInterrupt:
        pass
    finally:
        with SERIAL_LOCK:
            if serial_port is not None:
                serial_port.close()

