SERIAL_TIMEOUT = 1.0
IDN_QUERY = b'*IDN?\n'

data_store = [
    {'id': 1, 'name': 'CHIPS', 'done': False},
    {'id': 2, 'name': 'soda', 'done': True},
]

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

def open_serial_port():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None

def send_idn_query(ser):
    try:
        ser.write(IDN_QUERY)
        ser.flush()
        time.sleep(0.1)
        raw = ser.read(4096)
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error during IDN query: {e}", file=sys.stderr)
        return None

@app.route('/version', methods=['GET'])
def version():
    ser = open_serial_port()
    if ser is None:
        return Response("Error: Could not open serial port. Is the device connected and recognized?", status=503, mimetype='text/plain')
    try:
        result = send_idn_query(ser)
        if result is None:
            return Response("Error: Could not communicate with the device.", status=503, mimetype='text/plain')
        return Response(result + '<br><br>Serial: ' + SERIAL_PORT + ' Baud: ' + str(BAUD_RATE), status=200, mimetype='text/html')
    except Exception as e:
        print(f"Error during version request: {e}", file=sys.stderr)
        return Response("Error: Could not communicate with the device.", status=503, mimetype='text/plain')
