    for i, existing in enumerate(data_store):
        if existing['id'] == item_id:
            data_store[i] = new_item
            return jsonify(data_store)
    data_store.append(new_item)
    return jsonify(data_store)

@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    if request.method == 'POST':
        content_type = request.headers.get('Content-Type', '')
        if content_type or ('application/json' in request.headers or 'multipart/form-data' in request.headers):
            try:
                if content_type == 'application/json':
                    data = request.get_json(silent=True) or {}
                else:
                    data = request.values.to_dict()
                item_id = data.get('item_id')
                name = data.get('name')
                done = data.get('done')
                if item_id is not None and name is not None and done is not None:
                    if isinstance(done, bool) and done not in (True, False):
                        return Response("Invalid 'done' value. Must be True or False.", status=400, mimetype='text/plain')
                    new_item = {'id': None, 'name': name, 'done': done}
                    for i, existing in enumerate(data_store):
                        if existing['id'] == item_id:
                            data_store[i] = new_item
                            return jsonify(data_store)
                    data_store.append(new_item)
                    return jsonify(data_store)
                return Response("Invalid POST data. Expected 'item_id', 'name', and 'done'.", status=400, mimetype='text/plain')
            except (ValueError, KeyError) as e:
                return Response(f"Invalid POST data: {e}", status=400, mimetype='text/plain')
            except Exception as e:
                print(f"Error processing POST data: {e}", file=sys.stderr)
                return Response("Error processing POST data.", status=500, mimetype='text/plain')
        else:
            return Response("Unsupported media type. Use either application/json or multipart/form-data.", status=415, mimetype='text/plain')
    else:
        return jsonify(data_store)

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    except KeyboardInterrupt:
        pass

