import serial
import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = "X"
EXIT_COMMAND = "exit"


def create_bluetooth_connection(device, baudrate):
    """Establishes a serial connection to the Bluetooth device."""
    try:
        connection = serial.Serial(device, baudrate, timeout=1)
        return connection
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")


def send_command(connection, command):
    """Sends a command to the connected device."""
    if not connection or not connection.is_open:
        raise RuntimeError("Serial connection is not open.")

    command_with_prefix = f"{COMMAND_PREFIX}{command}\n"
    try:
        connection.write(command_with_prefix.encode("utf-8"))
        connection.flush()
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

    time.sleep(0.1)


def main():
    """Main function to interact with the Bluetooth device."""
    bluetooth_connection = None
    try:
        bluetooth_connection = create_bluetooth_connection(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.strip().lower() == EXIT_COMMAND:
                print("Exit command received.")
                break

            if not user_command:
                continue

            try:
                send_command(bluetooth_connection, user_command)
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except RuntimeError as e:
        print(f"Error: {e}")
        sys.exit(1)
    finally:
        if bluetooth_connection and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

